# Water-cut algorithm sourced exclusively from ХАЛ (water_cut_hal) — adaptive
# stable/startup/event model, supplied as-is (see adaptive_water_cut.py backend
# service; DO NOT modify this algorithm here, only its wiring). The running gate
# reuses the canonical WellCtx.wmask, not a separate threshold. Classification of
# Рост/Снижение обводненности (det_wcut) uses PARAMS['wct_*'] (episode_rules_v12_8
# local-window-trend rules), not a separate WC_DIRECTION_* constant block.


# ──────────────────────────────────────────────────────────────────────────
def merge_iv(iv, gap=pd.Timedelta(0)):
    iv = sorted([(s, e) for s, e in iv if pd.notna(s) and pd.notna(e) and e > s])
    out = []
    for s, e in iv:
        if out and s <= out[-1][1] + gap:
            out[-1] = (out[-1][0], max(out[-1][1], e))
        else:
            out.append((s, e))
    return out

def subtract_iv(iv, holes, min_dur=pd.Timedelta(hours=1)):
    """Вычесть интервалы holes из iv (разрезая/обрезая перекрытия)."""
    holes = merge_iv([(s, e) for s, e in holes])
    out = []
    for s, e in iv:
        segs = [(s, e)]
        for hs, he in holes:
            nxt = []
            for a, b in segs:
                if he <= a or hs >= b:
                    nxt.append((a, b))
                else:
                    if a < hs: nxt.append((a, hs))
                    if he < b: nxt.append((he, b))
            segs = nxt
        out += [(a, b) for a, b in segs if (b - a) >= min_dur]
    return out


def in_any(t, iv):
    return any(s <= t <= e for s, e in iv)

def split_at(iv, breaks):
    out = []
    for s, e in iv:
        cuts = sorted([b for b in breaks if s < b < e])
        prev = s
        for c in cuts:
            out.append((prev, c)); prev = c
        out.append((prev, e))
    return out


# ──────────────────────────────────────────────────────────────────────────
class WellCtx:
    def __init__(self, tele, vsp, P=PARAMS, hal_raw=None):
        self.P = P
        self.tele = tele.sort_index()
        # идентификатор скважины нужен для привязки PVT-кривой (ВГФ v11)
        self.well_id = (str(self.tele['well_id'].dropna().iloc[0])
                        if 'well_id' in self.tele and self.tele['well_id'].notna().any() else '')
        self.t0, self.t1 = self.tele.index.min(), self.tele.index.max()
        freq = self.tele[F].dropna()
        self.freq = freq

        iv = []
        if vsp is not None and len(vsp):
            d = vsp[vsp['status'].str.contains('downtime', case=False, na=False)]
            frun = freq[freq >= P['stop_freq_hz']]   # моменты явной работы насоса
            for _, r in d.iterrows():
                s = max(r['start'], self.t0)
                e = min(r['end'] if pd.notna(r['end']) else self.t1, self.t1)
                if e <= s: continue
                rin = frun[(frun.index >= s) & (frun.index <= e)]
                if len(rin):
                    span_d = (rin.index.max() - rin.index.min()).days
                    if span_d >= P['vsp_override_min_run_d']:
                        e = min(e, rin.index.min())
                if e > s: iv.append((s, e))
        run_s = None; prev_t = None
        for t, v in freq.items():
            if v < P['stop_freq_hz']:
                if run_s is None: run_s = t
                prev_t = t
            else:
                if run_s is not None:
                    if (prev_t - run_s) >= pd.Timedelta(minutes=P['stop_min_dur_min']):
                        iv.append((run_s, prev_t))
                    run_s = None
        if run_s is not None and (prev_t - run_s) >= pd.Timedelta(minutes=P['stop_min_dur_min']):
            iv.append((run_s, prev_t))

        self.stops = merge_iv(iv, gap=pd.Timedelta(minutes=10))
        self.long_stops = [(s, e) for s, e in self.stops
                           if (e - s) >= pd.Timedelta(hours=P['long_stop_h'])]

        idx = self.tele.index
        m = np.ones(len(idx), bool)
        for s, e in self.stops:
            m &= ~((idx >= s) & (idx <= e))
        for s, e in self.long_stops:
            cut = e + pd.Timedelta(hours=P['skip_restart_h'])
            m &= ~((idx > e) & (idx < cut))
        if F in self.tele:
            fv = pd.to_numeric(self.tele[F], errors='coerce')
            m &= ~(fv < P['stop_freq_hz']).values
        self.wmask = pd.Series(m, index=idx)

        # Единственный источник обводнённости — ХАЛ (water_cut_hal), отфильтрованная
        # по каноническому признаку «скважина в работе» (self.wmask) ДО суточной
        # медианы, затем сглажена адаптивным алгоритмом (adaptive_water_cut.py).
        # НЕ используются: telemetry_water_cut (АГЗУ), Qж/Qн, TR, СППВ, заполнение
        # пропусков нулём/интерполяцией, rolling('5D').
        self.water_cut_algo_daily = self._compute_water_cut_algo_daily(hal_raw, idx)
        self.tele['water_cut_algo'] = self._broadcast_water_cut_algo(idx)

        tw = self.tele[self.wmask.values]
        # v12: канал загрузки чистится ДО суточной агрегации. Физически загрузка ЭЦН
        # не превышает load_phys_max; в данных встречаются спайки до 3810% (Vt_3311,
        # 11.02.2026), и среднее по суткам вытягивало их в «загрузка 80->440%».
        # По фонду q999=88.7%, поэтому отсечка на 120% не трогает реальные режимы.
        if LD in tw:
            _ld = pd.to_numeric(tw[LD], errors='coerce')
            tw = tw.copy(); tw[LD] = _ld.where(_ld.between(0, P['load_phys_max']))
        self.wd = tw.select_dtypes(include=[np.number]).resample('1D').mean()
        # загрузка агрегируется МЕДИАНОЙ: устойчива к остаточным выбросам внутри суток
        if LD in tw:
            self.wd[LD] = tw[LD].resample('1D').median()
        self.days = self.wd.index

        self.esp_breaks = []
        if 'esp_id' in self.tele:
            e = self.tele['esp_id'].ffill()
            ch = e.ne(e.shift()) & e.notna() & e.shift().notna()
            self.esp_breaks = list(self.tele.index[ch])

        self.stop_starts = [s for s, _ in self.stops]
        _span_d = max((self.t1 - self.t0).days, 1)
        # v10.10: считаем ПОДТВЕРЖДЁННЫЕ полные остановки. Блипы канала частоты раньше
        # делали скважину «циклической», а это смягчало гейт НУР (12ч -> 6ч) и открывало
        # ветку Неопт. режима для периодического фонда — каскад ложных эпизодов.
        self.cyclic = (len(full_stops(self)) / _span_d * 30.0) >= P['cyclic_stop_rate']

        # v9: РАСЧЁТНЫЙ Кпрод = Qж / (Рпл - Рзаб), Рзаб = рабочий интейк (подвижный).
        # Qж и Рпл берём как есть (ffill held-значений), темп падения важнее уровня.
        self.kprod = pd.Series(dtype=float)
        if 'tr_liquid_rate' in self.tele and 'tr_reservoir_pressure' in self.tele:
            q = pd.to_numeric(self.tele['tr_liquid_rate'], errors='coerce').ffill()
            rpl = pd.to_numeric(self.tele['tr_reservoir_pressure'], errors='coerce').ffill()
            ipf = pd.to_numeric(self.tele[IP], errors='coerce').where(self.wmask.values)
            ipf = ipf.where(ipf > 0)
            dd = rpl - ipf
            K = (q / dd).where(dd > 1)
            self.kprod = K.resample('1D').mean().dropna()

    def _compute_water_cut_algo_daily(self, hal_raw, idx):
        """Day-indexed adaptive water-cut table for this well: water_cut_algo (the
        displayed line), water_cut_target/water_cut_mode/water_cut_hal_daily and
        sample-level diagnostics, plus a 'running' column. Классификация Рост/
        Снижение обводненности (det_wcut) больше не читает эту таблицу — она
        считает устойчивый локальный тренд прямо по ctx.tele['water_cut_algo']
        (episode_rules_v12_8-style, см. det_wcut); эта daily-таблица используется
        для диагностики (_antag_series) и остаётся as-is (build_water_cut_line,
        unmodified).

        1) gate every raw ХАЛ measurement by the canonical running mask (self.wmask),
           using the most recent telemetry record at/before the measurement's own
           timestamp — measurements taken during a stop are dropped, not averaged in;
        2) aggregate accepted points to one MEDIAN value per calendar day (sparse,
           measurement days only — daily_hal_median never fabricates placeholder rows);
        3) run build_water_cut_line (supplied module, unmodified)."""
        empty = pd.DataFrame(columns=[
            'water_cut_algo', 'water_cut_target', 'water_cut_mode',
            'water_cut_hal_daily', 'water_cut_outlier', 'water_cut_signal_updated',
            'water_cut_event_confirmed', 'running',
        ])
        if hal_raw is None or not len(hal_raw):
            return empty

        hal_df = pd.DataFrame({
            'timestamp': pd.to_datetime(hal_raw['timestamp'], errors='coerce'),
            'hal_value': pd.to_numeric(hal_raw['hal_value'], errors='coerce'),
        }).dropna()
        hal_df = hal_df[hal_df['hal_value'].between(0.0, 100.0)]
        if hal_df.empty:
            return empty
        hal_df = hal_df.sort_values('timestamp')

        wmask_df = pd.DataFrame({'timestamp': idx, 'running': self.wmask.to_numpy()}).sort_values('timestamp')
        merged = pd.merge_asof(hal_df, wmask_df, on='timestamp', direction='backward')
        hal_running = merged[merged['running'].fillna(False)]
        if hal_running.empty:
            return empty

        raw_for_agg = pd.DataFrame({
            'well_id': self.well_id or '_',
            'date': hal_running['timestamp'],
            'water_cut_hal': hal_running['hal_value'],
        })
        daily = daily_hal_median(raw_for_agg)
        if daily.empty:
            return empty

        daily_series = daily.set_index('date')['water_cut_hal_daily']
        running_daily_full = pd.Series(self.wmask.to_numpy(), index=idx).resample('1D').max()
        running_for_grid = running_daily_full.reindex(
            pd.date_range(daily_series.index.min(), daily_series.index.max(), freq='D')
        ).fillna(False)

        table = compute_well_water_cut_algo(daily_series, running_for_grid)
        if table.empty:
            return empty
        table['running'] = table['running'].astype(bool)
        return table

    def _broadcast_water_cut_algo(self, idx):
        """Per-record broadcast of water_cut_algo (same access pattern the old
        wct_pred/water_cut_5d column had, for callers that key off ctx.tele)."""
        daily = self.water_cut_algo_daily
        if daily is None or daily.empty or 'water_cut_algo' not in daily:
            return pd.Series(np.nan, index=idx)
        return pd.Series(idx.floor('D'), index=idx).map(daily['water_cut_algo'])

    def work_segments(self):
        segs, prev = [], self.t0
        for s, e in self.long_stops:
            if s > prev: segs.append((prev, s))
            prev = e
        if self.t1 > prev: segs.append((prev, self.t1))
        return split_at(segs, self.esp_breaks)

    def rpr_envelope(self):
        # МЕЖЦИКЛОВАЯ огибающая: представительный Рпр (медиана) по каждому рабочему
        # сегменту между остановками. Внутрицикловый шум усредняется.
        # v10.3: нули/неположительные = выключенный датчик / нет данных (НЕ давление) —
        # отбрасываем, иначе медиана сегмента = 0 даёт фейковое «падение» огибающей
        # 95->0 -> ложное Снижение Рпл при реальном РОСТЕ Рпр (Au_389 ноя-дек 2025).
        ip = self.wd[IP].dropna()
        ip = ip[ip > 0]
        env = {}
        for s2, e2 in self.work_segments():
            seg = ip[(ip.index >= s2.normalize()) & (ip.index <= e2.normalize())]
            if len(seg) >= 3:
                env[s2 + (e2 - s2) / 2] = float(seg.median())
        return pd.Series(env).sort_index()

    def pre_stop_ip_mean(self, stop_start, days=3):
        """Среднее Рпр по рабочим точкам за days сут до остановки (нули = нет данных)."""
        ip = self.tele[IP][self.wmask.values].dropna()
        ip = ip[ip > 0]   # нули трактуем как отсутствие данных
        w = ip[(ip.index < stop_start) & (ip.index >= stop_start - pd.Timedelta(days=days))]
        return w.mean() if len(w) else np.nan


# ──────────────────────────────────────────────────────────────────────────
def det_stop(ctx):  return list(ctx.stops)

def det_work(ctx):
    out, prev = [], ctx.t0
    for s, e in ctx.stops:
        if s > prev: out.append((prev, s))
        prev = e
    if ctx.t1 > prev: out.append((prev, ctx.t1))
    return split_at(out, ctx.esp_breaks)


def det_gdi(ctx, gdi_events=None):
    P = ctx.P; out = []
    ip = ctx.tele[IP].dropna()
    ev = [] if gdi_events is None else list(gdi_events)
    for s, e in ctx.stops:
        if (e - s) < pd.Timedelta(hours=P['gdi_min_stop_h']): continue
        if any(max((min(ee if pd.notna(ee) else es + pd.Timedelta(days=1), e)
                    - max(es, s)).total_seconds(), 0) > 0 for es, ee in ev):
            out.append((s, e)); continue
        seg = ip[(ip.index >= s) & (ip.index <= e)]
        if len(seg) < P['gdi_min_pts']: continue
        # Датчик Рпр должен работать: иначе нули/пропуски и «рост» — артефакт,
        # а простой не несёт информации о пластовом давлении -> это не ГДИ.
        seg_valid = seg[seg > 0]
        if len(seg) == 0 or len(seg_valid) / len(seg) < P['gdi_min_valid_frac']: continue
        if len(seg_valid) < P['gdi_min_pts']: continue
        v = seg_valid.values
        best = cur = 1
        for j in range(1, len(v)):
            if v[j] >= v[j-1] - P['gdi_dip_bar']: cur += 1; best = max(best, cur)
            else: cur = 1
        if best < P['gdi_min_run']: continue
        if v.max() - v[0] < P['gdi_total_rise_bar']: continue
        out.append((s, e))
    return merge_iv(out)


def det_rptch(ctx):
    """Два критерия (ИЛИ):
    А) ≥20% рабочих суток с внутрисуточным range Гц ≥ 1.5 (исключая дни range>15 = пуск/останов).
    Б) Межсуточный: std суточных средних ≥ 1.0 Гц + ≥3 смены направления (уставки меняются циклически)
       при мин. 14 рабочих суток в сегменте."""
    P = ctx.P; out = []
    fw = ctx.tele[F][ctx.wmask.values].dropna()
    if not len(fw): return out
    # Внутрисуточный range
    rng = fw.resample('1D').agg(lambda x: x.max() - x.min() if len(x) > 1 else np.nan)
    # Суточные средние для межсуточного критерия
    f_daily = fw.resample('1D').mean()
    # Маска окна стабилизации после длинного пуска (рамп != РПТЧ)
    _keep = pd.Series(True, index=f_daily.index)
    for _ss, _ee in ctx.stops:
        if (_ee - _ss) >= pd.Timedelta(hours=P['rptch_restart_stop_h']):
            _keep[(f_daily.index > _ee) & (f_daily.index <= _ee + pd.Timedelta(days=P['rptch_post_restart_d']))] = False
    f_daily_b = f_daily[_keep]

    for s, e in ctx.work_segments():
        s_n = s.normalize(); e_n = e.normalize()
        # --- Критерий А: внутрисуточный ---
        d_seg = rng[(rng.index >= s_n) & (rng.index <= e_n)].dropna()
        # Исключить дни с range > rptch_max_range_hz (рампа пуска/останова)
        d_valid = d_seg[d_seg < P['rptch_max_range_hz']]
        if len(d_valid) > 0:
            osc = (d_valid >= P['rptch_osc_hz']).sum()
            if osc >= P['rptch_min_osc_days'] and osc / max(len(d_valid), 1) >= P['rptch_density']:
                out.append((s, e)); continue

        # --- Критерий Б: межсуточные хождения частоты в СКОЛЬЗЯЩЕМ окне ---
        # РПТЧ = ЧАСТЫЕ развороты (плотность), и он может НАЧАТЬСЯ в середине
        # сегмента (переход со стабильной частоты на хождения). Поэтому считаем
        # плотность разворотов в окне rptch_roll_win, а не по всему сегменту.
        # (критерий «целых Гц» удалён как ложный: стабильная целая частота != РПТЧ).
        fd = f_daily_b[(f_daily_b.index >= s_n) & (f_daily_b.index <= e_n)].dropna()
        if len(fd) < P['rptch_interday_min_d']: continue
        # (1) ВЕСЬ сегмент: устойчиво высокая плотность разворотов (Ic_370 на всю жизнь)
        std_day = fd.std()
        diff = fd.diff().dropna()
        reversals = int((diff * diff.shift(1) < 0).sum())
        rev_rate = reversals / max(len(fd), 1)
        if (std_day >= P['rptch_interday_std'] and reversals >= P['rptch_interday_rev']
                and rev_rate >= P['rptch_rev_rate']):
            out.append((s, e)); continue
        # (2) иначе СКОЛЬЗЯЩЕЕ окно: РПТЧ может начаться в середине сегмента (Ic_359
        #     с 5 ноя). Амплитуда может быть мелкой (rptch_roll_min_std), главное —
        #     плотность разворотов.
        W = P['rptch_roll_win']; mp = max(W // 2, P['rptch_interday_rev'] + 1)
        sgn = np.sign(fd.diff())
        rev = (sgn * sgn.shift(1) < 0).astype(float)
        roll_rate = rev.rolling(W, center=True, min_periods=mp).mean()
        roll_std  = fd.rolling(W, center=True, min_periods=mp).std()
        osc = (roll_rate >= P['rptch_rev_rate']) & (roll_std >= P['rptch_roll_min_std'])
        out += _flag_to_iv(osc.fillna(False))

    return merge_iv(out, gap=pd.Timedelta(days=P['rptch_merge_gap_d']))


def _rptch_clean(ctx, ivs):
    """РПТЧ v12.7 — чистый режим переменной частоты.

    Эксперт: «убери РПТЧ, когда скважина постоянно запускается и останавливается».
    Прежде интервал сознательно РАСШИРЯЛСЯ через остановки (rptch_merge_gap_d = 60 сут),
    и режим пуск-остановка попадал в РПТЧ наравне с настоящей переуставкой частоты.

    Теперь интервал режется подтверждёнными остановками на непрерывные куски, и кусок
    остаётся, только если:
      * длится >= rptch_clean_min_d без остановок внутри;
      * у его границ нет остановки в буфере rptch_edge_guard_d;
      * внутри частота И выросла, И упала не меньше чем на rptch_amp_min_hz —
        то есть это ходы уставки, а не одиночная ступень или дрейф.
    """
    P = ctx.P
    if not ivs:
        return []
    _sig = pd.Timedelta(hours=P['rptch_split_stop_h'])
    fs = [(a0, b0) for a0, b0 in full_stops(ctx) if (b0 - a0) >= _sig]
    around = pd.Timedelta(days=P['rptch_around_win_d'])
    min_len = pd.Timedelta(days=P['rptch_clean_min_d'])
    fd = ctx.tele[F][ctx.wmask.values].dropna().resample('1D').mean().dropna() \
        if F in ctx.tele else pd.Series(dtype=float)
    out = []
    for a, b in subtract_iv(list(ivs), [(s0, e0) for s0, e0 in fs]):
        if (b - a) < min_len:
            continue
        # «скважина постоянно запускается и останавливается» — это НЕ РПТЧ. Меряем
        # ПЛОТНОСТЬ значимых остановок вокруг куска, а не соседство с одной: соседство
        # бессмысленно, потому что границы куска и созданы разрезанием по остановкам.
        w0, w1 = a - around, b + around
        n_around = sum(1 for s0, e0 in fs if min(w1, e0) > max(w0, s0))
        span_d = max((w1 - w0).total_seconds() / 86400.0, 1.0)
        if n_around / span_d * 30.0 > P['rptch_stop_rate_max']:
            continue
        seg = fd[(fd.index >= a.normalize()) & (fd.index <= b.normalize())]
        if len(seg) < 3:
            continue
        v = seg.to_numpy(dtype=float)
        run_min = np.minimum.accumulate(v)
        run_max = np.maximum.accumulate(v)
        up = float(np.max(v - run_min))      # максимальный подъём от предыдущего минимума
        dn = float(np.max(run_max - v))      # максимальное падение от предыдущего максимума
        if up < P['rptch_amp_min_hz'] or dn < P['rptch_amp_min_hz']:
            continue                         # нет ходов вверх И вниз нужной амплитуды
        out.append((a, b))
    return merge_iv(out, gap=pd.Timedelta(0))


def det_uvch(ctx, rptch_iv=None):
    """УВЧ v8 — устойчивый рост частоты на НОВЫЙ уровень.
    Ключ: УВЧ засчитывается, только если частота ПРЕВЫШАЕТ доостановочный
    уровень (выход на новую уставку). Простой возврат к прежней частоте после
    остановки = восстановление, а не УВЧ — отсекается тем же критерием.
      * суточная рабочая частота, дни с остановкой исключаются (чистый тренд);
      * восходящие прогоны ищутся по сглаж. частоте (полка завершает прогон);
      * амплитуда = пик(сырая частота) - база:
          база = доостановочный уровень, если прогон стартует <=
                 uvch_recover_lookback_d сут после остановки (нужно ПРЕВЫСИТЬ);
          иначе база = уровень полки прямо перед прогоном;
      * засчитывается при амплитуде >= uvch_rise_hz и длит. >= uvch_min_run_d.
    rptch_iv в сигнатуре для совместимости вызова, не используется."""
    P = ctx.P; out = []
    f0 = ctx.wd[F].dropna()
    if len(f0) < 3:
        return out
    stop_days = set()
    for ss, se in ctx.stops:
        dd = ss.normalize()
        while dd <= se.normalize():
            stop_days.add(dd); dd += pd.Timedelta(days=1)
    f = f0[~f0.index.normalize().isin(stop_days)]
    if len(f) < 3:
        return out
    fs = f.rolling(P['uvch_smooth_d'], min_periods=1).mean()
    days = list(fs.index); vs = list(fs.values); n = len(days)
    fraw = f

    def recent_stops(t):
        return [(ss, se) for ss, se in ctx.stops
                if (t - pd.Timedelta(days=P['uvch_recover_lookback_d'])) <= se <= t + pd.Timedelta(hours=23)]

    i = 0
    while i < n - 1:
        if vs[i + 1] - vs[i] < P['uvch_start_step']:
            i += 1; continue
        j = i + 1
        while j < n - 1 and (vs[j + 1] - vs[j]) >= P['uvch_end_flat_hz']:
            j += 1
        s_run, e_run = days[i], days[j]
        dur_d = (e_run - s_run).days
        peak = float(fraw[(fraw.index >= s_run) & (fraw.index <= e_run)].max())

        rec = recent_stops(s_run)
        if rec:
            se_max = max(se for _, se in rec); ss0 = min(ss for ss, _ in rec)
            prior = f0[(f0.index < ss0) & (f0.index >= ss0 - pd.Timedelta(days=5))]
            pre_base = float(prior.median()) if len(prior) else None
            # устоявшаяся полка ПОСЛЕ простоя (новый уровень) — рост от неё = УВЧ
            post_pre = fraw[(fraw.index > se_max) & (fraw.index < s_run)]
            established = (len(post_pre) >= P['uvch_plateau_d'] and
                          (post_pre.max() - post_pre.min()) <= P['uvch_plateau_tol'])
            if pre_base is None or established:
                # база = локальная полка (хватает любого роста на новый уровень)
                if len(post_pre):
                    base = float(post_pre.median())
                else:
                    pr = fraw[fraw.index < s_run]
                    base = float(pr.iloc[-1]) if len(pr) else float(vs[i])
            else:
                # ещё идёт восстановление — нужно ПРЕВЫСИТЬ доостановочный уровень
                base = pre_base
        else:
            pr = fraw[fraw.index < s_run]
            base = float(pr.iloc[-1]) if len(pr) else float(vs[i])

        net = peak - base
        # игнорируем рост, стартующий с низкой частоты (<uvch_min_start_hz) — это
        # пусковой рамп выхода на режим, а не УВЧ
        start_low = float(fraw.loc[s_run]) < P['uvch_min_start_hz'] if s_run in fraw.index else False
        # удержание: после роста частота должна ОСТАТЬСЯ на новом высоком уровне
        # (спайк, вернувшийся к базе, — не УВЧ)
        _post = fraw[(fraw.index > e_run) & (fraw.index <= e_run + pd.Timedelta(days=P['uvch_hold_d']))]
        _held = (len(_post) == 0) or (float(_post.median()) >= base + P['uvch_rise_hz'])
        if dur_d >= P['uvch_min_run_d'] and net >= P['uvch_rise_hz'] and not start_low and _held:
            out.append((s_run, e_run + pd.Timedelta(hours=23)))
        i = max(j, i + 1)
    # ПОЛОГИЙ УВЧ на циклических скважинах: медленный устойчивый рост частоты,
    # который run-детектор (порог start_step) пропускает (напр. 50.8->52.6 за 2.5 мес).
    if getattr(ctx, 'cyclic', False):
        fd = ctx.wd[F].dropna()
        if len(fd) > P['uvch_slow_win']:
            full = fd.reindex(pd.date_range(fd.index.min(), fd.index.max(), freq='D')).interpolate(limit=5)
            sm = full.rolling(7, min_periods=3).mean()
            rise = sm - sm.shift(P['uvch_slow_win'])
            flag = pd.Series((rise >= P['uvch_slow_net']).fillna(False), index=sm.index)
            out += [(_s, _e) for _s, _e in merge_iv(_flag_to_iv(flag), gap=pd.Timedelta(days=10)) if (_e - _s).days >= P['uvch_slow_min_d']]
    return _clear_stops(merge_iv(out), ctx, P['uvch_stop_clear_d'])


def det_nur(ctx):
    """НУР v7 — пик-якорь + мягкое завершение.
    После остановки (>= nur_gate_stop_h) интейк восстанавливается ВЫШЕ
    доостановочного уровня (пик ищется в первые nur_peak_search_d сут, т.к. пик
    может быть ОТЛОЖЕН), затем МОНОТОННО снижается >= nur_min_drop_bar.
    Снижение тянется, пока интейк ставит новые минимумы (допуск nur_rise_tol),
    и закрывается на устойчивом развороте вверх (nur_rise_confirm_d сут).
    Это чинит: (а) отложенный пик (раньше end_i=0), (б) обрыв на затухающем
    наклоне (раньше снижение <0.3 бар/сут резало эпизод раньше времени)."""
    P = ctx.P; out = []
    ip = ctx.wd[IP].dropna()
    if not len(ip): return out
    fs = full_stops(ctx)              # v10.10: только подтверждённые полные остановки
    for s, e in fs:
        _gate = P['nur_gate_periodic'] if getattr(ctx, 'cyclic', False) else P['nur_gate_stop_h']
        if (e - s) < pd.Timedelta(hours=_gate): continue
        pre = ctx.pre_stop_ip_mean(s)
        post = ip[ip.index >= e.normalize()].dropna()
        if len(post) < 3: continue
        # вмешалась другая длинная остановка — первый рабочий день слишком далеко
        if (post.index[0] - e).days > P['nur_max_gap_to_post']:
            continue
        # --- ПИК интейка в первые nur_peak_search_d сут (восстановление за простой) ---
        search = post[post.index <= post.index[0] + pd.Timedelta(days=P['nur_peak_search_d'])]
        peak_pos = int(np.argmax(search.values))
        peak_val = float(search.values[peak_pos])
        if pd.notna(pre) and pre > 0:
            if peak_val - pre < P['nur_min_recovery_bar']:
                continue          # накопления за простой нет -> не переходный процесс, а тренд
        else:
            # нет данных «до» — fallback: явное снижение в первые N сут
            fb = min(P['nur_fallback_days'], len(post) - 1)
            if post.iloc[0] - post.iloc[fb] < P['nur_min_drop_bar']:
                continue
        # --- снижение ОТ ПИКА: тянем, пока ставятся новые минимумы ---
        decl = post.iloc[peak_pos:]
        days = list(decl.index); vals = list(decl.values)
        end_i = 0
        _floor = (pre - P['nur_floor_undershoot'] * (peak_val - pre)) \
            if (pd.notna(pre) and pre > 0 and peak_val > pre) else None
        cyc = bool(getattr(ctx, 'cyclic', False))
        # v12.1: ЕДИНЫЙ ход для обеих веток. Допуск отскока масштабируется НАКОПЛЕННЫМ
        # спадом: транзиент в 39 бар не заканчивается от колебания в 2 бара. Раньше
        # масштабирование стояло только в нециклической ветке, а циклическая рвала эпизод
        # по абсолютному шагу — на Vt_606 (23.06.2025) два дня с отскоком -2.0 и -1.3 бара
        # обрывали спад 100 -> 61 бар, идущий ещё три недели.
        # Циклическую специфику сохраняет ОТДЕЛЬНАЯ проверка выполаживания: НУР там —
        # только крутая фаза, поэтому эпизод закрывается, когда средний темп спада на
        # хвостовом окне падает ниже nur_steep_slope.
        rmin = vals[0]; rise = 0
        W = int(P['nur_flat_win_d'])
        for k in range(1, len(days)):
            if (days[k] - days[0]).days > P['nur_max_d']: break
            if _floor is not None and vals[k] < _floor: break       # избыток рассосался
            tol = max(P['nur_rise_tol'], P['nur_rebound_frac'] * (vals[0] - rmin))
            if vals[k] <= rmin + tol:
                if vals[k] < rmin:
                    rmin = vals[k]; end_i = k
                rise = 0
            else:
                rise += 1
                if rise >= P['nur_rise_confirm_d']: break
            if cyc and k >= W:
                span = (days[k] - days[k - W]).days or W
                if (vals[k - W] - vals[k]) / span < P['nur_steep_slope']:
                    break                                           # спад выполаживается
        if end_i < 1: continue
        # монотонность снижения
        if end_i >= 3:
            pairs = [vals[k] - vals[k + 1] for k in range(end_i)]
            mono = sum(1 for x in pairs if x >= -P['nur_rise_tol']) / len(pairs)
            if mono < P['nur_monotone_ratio']:
                continue
        if vals[0] - vals[end_i] < P['nur_min_drop_bar']: continue
        st, en = days[0], days[end_i] + pd.Timedelta(hours=23)
        # v10.12: доля простоя ВНУТРИ эпизода. Зеркало per_idle_frac_min: периодическая
        # работа требует высокой доли простоя, переходный процесс — низкой.
        _span = (en - st).total_seconds()
        if _span > 0:
            # опорная остановка (s..e) — причина эпизода, а не помеха; ЛЮБАЯ другая
            # остановка внутри окна рвёт наблюдение за транзиентом и считается
            _off = sum(max(0.0, (min(e2, en) - max(s2, st)).total_seconds())
                       for s2, e2 in fs if (s2, e2) != (s, e))
            if _off / _span > P['nur_max_idle_frac']:
                continue          # работа рвётся остановками -> транзиент не установился
        if (en - st) >= pd.Timedelta(days=P['nur_min_d']):
            out.append((st, en))
    return merge_iv(out, gap=pd.Timedelta(hours=12))


def full_stops(ctx):
    """Остановки, где насос ДЕЙСТВИТЕЛЬНО встал: длительность >= full_stop_min_h и
    независимое подтверждение по загрузке/активной мощности (обе ~0).
    Провал в канале частоты при работающем насосе (потеря телеметрии, кратковременная
    переуставка) остановкой не является и циклом стоп-старт считаться не должен."""
    cached = getattr(ctx, '_full_stops', None)
    if cached is not None:
        return cached
    P = ctx.P
    fv = pd.to_numeric(ctx.tele.get(F), errors='coerce') if F in ctx.tele else None
    ld = pd.to_numeric(ctx.tele.get(LD), errors='coerce') if LD in ctx.tele else None
    pw = pd.to_numeric(ctx.tele.get('telemetry_active_power'), errors='coerce') \
        if 'telemetry_active_power' in ctx.tele else None
    out = []
    for s0, e0 in getattr(ctx, 'stops', []):
        if (e0 - s0) < pd.Timedelta(hours=P['full_stop_min_h']):
            continue
        # подтверждаем РОВНО в тех точках, что образуют остановку (частота ниже порога):
        # строки с пустой частотой внутри интервала к остановке отношения не имеют
        win = (ctx.tele.index >= s0) & (ctx.tele.index <= e0)
        if fv is not None:
            win &= (fv < P['stop_freq_hz']).fillna(False).values
        # ИЗВЕСТНОЕ ОГРАНИЧЕНИЕ (Ya_289): канал telemetry_active_power может мерить
        # станцию/куст и держать 57-121 кВт при заведомо стоящем насосе (f=0, load=0) —
        # тогда мощность-свидетель ветирует реальные остановки и НУР по ним не ищется.
        # Приоритетное голосование каналов (load решает, power только без load) чинит
        # это, но каскадно меняет cyclic-флаги и переразметку антагонистов на других
        # скважинах (проверено: -8 Кпрод, -2 строгих Рпл при +7 НУР) — требует
        # отдельной итерации с пересмотром цепочки НУР-Кпрод-Рпл, не точечной правки.
        # Свидетели голосуют единогласно, но вето требует ОПОРЫ НА ДАННЫЕ: канал с одним-двумя
        # отсчётами внутри остановки её не отменяет — медиана одного отсчёта есть сам отсчёт.
        # Приоритет загрузки над мощностью здесь НЕ вводится: проверено, каскадно меняет
        # cyclic-флаги и переразметку антагонистов (-11 Кпрод, -2 строгих Рпл при +6 НУР).
        ok = True
        for ser, lim in ((ld, P['full_stop_load_max']), (pw, P['full_stop_pwr_max'])):
            if ser is None:
                continue
            seg = ser[win].dropna()
            if len(seg) >= P['full_stop_min_votes'] and float(seg.median()) > lim:
                ok = False; break        # насос под нагрузкой — это не остановка
        if ok:
            out.append((s0, e0))
    ctx._full_stops = out
    return out


def det_periodic(ctx):
    """Периодическая работа = частые циклы стоп-старт. v9.5: считаем ПЕРЕХОДЫ
    частоты в стоп (freq>=порог -> <порог) ЛЮБОЙ длительности. v9.9: на скважинах
    с УСТОЙЧИВО периодическим режимом (стретч циклирования содержит >= per_strong_days
    сут плотного цикла count>=per_start_n) режим расширяется на ВЕСЬ смежный стретч
    циклирования (count>=1) — Ic_805/Vt_606/Vt_655 и т.п.; на прочих скважинах —
    прежняя пороговая логика (не раздуваем краткие всплески циклов на непериодич. фонде)."""
    P = ctx.P
    # v10.10: раньше считались ПЕРЕСЕЧЕНИЯ порога частоты ЛЮБОЙ длительности — один
    # провал в канале частоты давал «цикл». Циклом считается только подтверждённая
    # полная остановка (см. full_stops) с последующим пуском: без пуска цикла нет.
    fs = full_stops(ctx)
    if not fs:
        return []
    fv = pd.to_numeric(ctx.tele[F], errors='coerce').dropna() if F in ctx.tele else pd.Series(dtype=float)
    if len(fv) < 5:
        return []
    onsets = [s0 for s0, e0 in fs
              if len(fv[(fv.index > e0)]) and float(fv[fv.index > e0].iloc[0]) >= P['stop_freq_hz']]
    if not onsets:
        return []
    days = pd.date_range(ctx.t0.normalize(), ctx.t1.normalize(), freq='D')
    ss = pd.Series(1, index=pd.DatetimeIndex(onsets)).resample('1D').sum()
    cnt = ss.reindex(days, fill_value=0).rolling(P['per_window_d'], min_periods=1).sum()
    # стретчи циклирования (хоть какие-то циклы в окне: count>=1)
    active = (cnt >= 1).values; n = len(days)
    stretches = []; i = 0
    while i < n:
        if not active[i]:
            i += 1; continue
        j = i
        while j < n and active[j]:
            j += 1
        stretches.append((i, j)); i = j
    # устойчивый периодич. режим: существует стретч с >= per_strong_days сут count>=per_start_n
    qualifies = any((cnt.iloc[a:b] >= P['per_start_n']).sum() >= P['per_strong_days']
                    for a, b in stretches)
    def _idle_frac(a0, b0):
        """Доля времени в подтверждённых остановках на интервале. Периодическая работа —
        это режим, при котором скважина РЕАЛЬНО стоит заметную часть времени; редкие
        короткие стопы на непрерывно работающей скважине режимом не являются."""
        span = (b0 - a0).total_seconds()
        if span <= 0:
            return 0.0
        off = sum(max(0.0, (min(e0, b0) - max(s0, a0)).total_seconds()) for s0, e0 in fs)
        return off / span

    if qualifies:
        out = []
        for a, b in stretches:
            if (cnt.iloc[a:b] >= P['per_start_n']).any():   # стретч с реальными кластерами цикла
                out.append((max(days[a] - pd.Timedelta(days=P['per_window_d'] - 1), ctx.t0),
                            days[b - 1]))
        out = merge_iv(out, gap=pd.Timedelta(days=P['per_merge_gap_d']))
        return [iv for iv in out if _idle_frac(*iv) >= P['per_idle_frac_min']]
    # прежняя пороговая логика (вход >= per_start_n, держим пока >= per_keep_n)
    out, st = [], None
    for dts in days:
        c = cnt[dts]
        if st is None and c >= P['per_start_n']:
            st = dts - pd.Timedelta(days=P['per_window_d'] - 1)
        elif st is not None and c < P['per_keep_n']:
            out.append((max(st, ctx.t0), dts)); st = None
    if st is not None:
        out.append((max(st, ctx.t0), days[-1]))
    out = merge_iv(out, gap=pd.Timedelta(days=P['per_merge_gap_d']))
    return [iv for iv in out if _idle_frac(*iv) >= P['per_idle_frac_min']]


def _trend_runs(series, min_run_d, total_thr, max_slope=None, sign=-1, tol=0.3):
    s = series.dropna()
    out = []
    if len(s) < 2: return out
    days = list(s.index); vals = s.values
    i = 0
    while i < len(days) - 1:
        j = i
        while j < len(days) - 1 and sign * (vals[j+1] - vals[j]) > -tol:
            j += 1
        if j > i:
            span_d = (days[j] - days[i]).days
            delta = sign * (vals[j] - vals[i])
            slope = delta / max(span_d, 1)
            if span_d >= min_run_d and delta >= total_thr and \
               (max_slope is None or slope <= max_slope):
                out.append((days[i], days[j], delta))
        i = max(j, i + 1)
    return out


def _rpl_model_decline(ctx, nur_iv=()):
    """Снижение Рпл по монотонному спаду Рпр приёма (telemetry_intake_pressure, вне НУР)
    в НЕПРЕРЫВНОЙ работе (мало стоп-переходов) при СТАБИЛЬНОЙ частоте — истощение
    пласта внутри длинного рабочего сегмента (Vt_605 авг-ноя). Периодич. скважины
    отсекаются гейтом непрерывности (их спад Рпр — операционные циклы)."""
    P = ctx.P
    _rpser = ctx.tele.get(IP)                          # Рпр приёма (ТЕЛЕМЕТРИЯ), без TR
    if _rpser is None:
        return []
    rp = pd.to_numeric(_rpser, errors='coerce').dropna()
    rp = rp[rp > 0].resample('1D').median().rolling(7, min_periods=2).median().dropna()
    rp = rp[~rp.index.to_series().apply(lambda t: in_any(t, nur_iv))]
    if len(rp) < 2:
        return []
    f = ctx.wd[F]
    fv = pd.to_numeric(ctx.tele[F], errors='coerce').dropna()
    on = (fv >= P['stop_freq_hz']).astype(int); cross = (on.diff() == -1)
    onsets = pd.DatetimeIndex(fv.index[cross.values])
    stops = getattr(ctx, 'stops', [])
    days = list(rp.index); vals = list(rp.values); out = []; i = 0
    while i < len(days) - 1:
        if vals[i + 1] - vals[i] > P['rpl_model_tol']:
            i += 1; continue
        j = i
        while j < len(days) - 1:
            g = (days[j + 1] - days[j]).days
            if g < 1 or g > P['rpl_model_max_gap_d']:
                break
            if vals[j + 1] - vals[j] > P['rpl_model_tol']:
                break
            j += 1
        net = vals[i] - vals[j]; dur = (days[j] - days[i]).days
        if j > i and net >= P['rpl_model_min_bar'] and dur >= P['rpl_model_min_d']:
            seg = f[(f.index >= days[i]) & (f.index <= days[j])].dropna()
            dfr = (seg.iloc[-max(1, len(seg)//3):].median() - seg.iloc[:max(1, len(seg)//3)].median()) if len(seg) >= 3 else 0.0
            cyc = ((onsets >= days[i]) & (onsets <= days[j])).sum() / max(dur, 1) * 14
            # v10.13: гейт непрерывности проходит по ЛЮБОМУ из двух признаков —
            # (а) редкие стоп-переходы (как раньше), ЛИБО (б) стоп-переходы частые,
            # но КОРОТКИЕ, так что суммарный простой за run — малая доля времени
            # (насос фактически работает непрерывно, рестарты не создают операционный
            # цикл в Рпр). Различает Ic_367 (рестарты 1-9ч, простой ~5%) от истинно
            # периодических скважин (Vt_419/Ya_289, где офф-периоды формируют режим).
            run_s, run_e = days[i], days[j] + pd.Timedelta(hours=23)
            run_h = max((run_e - run_s).total_seconds() / 3600, 1.0)
            down_h = sum((min(b, run_e) - max(a, run_s)).total_seconds() / 3600
                         for a, b in stops if b > run_s and a < run_e)
            down_frac = down_h / run_h
            continuous = (cyc < P['rpl_model_cyc_max']) or (down_frac <= P['rpl_model_down_frac_max'])
            if abs(dfr) <= P['rpl_model_fstab_hz'] and continuous:
                out.append((run_s, run_e))
        i = max(j, i + 1)
    return merge_iv(out)


def _q_daily_pref_agzu(ctx):
    """Суточный Qж: приоритет замеров АГЗУ (telemetry_qliq), при отсутствии свежих —
    виртуальный расходомер (tr_liquid_rate).
    Замер АГЗУ в телеметрии held/ffill-ится источником, поэтому дата ЗАМЕРА
    определяется по СМЕНЕ значения: если суточное значение не изменилось — нового
    замера не было. Свежесть (rplq_agzu_fresh_d) считается от последнего дня смены
    значения (первый день данных = замер). Допущение: два подряд идентичных
    реальных замера неотличимы от held — принимаем как устаревание (уходим на ВР)."""
    P = ctx.P
    agzu = pd.Series(dtype=float)
    if QL in ctx.tele:
        agzu = pd.to_numeric(ctx.tele[QL], errors='coerce').dropna()
        agzu = agzu[agzu > 0].resample('1D').median()
    vfm = pd.Series(dtype=float)
    if 'tr_liquid_rate' in ctx.tele:
        vfm = pd.to_numeric(ctx.tele['tr_liquid_rate'], errors='coerce').dropna()
        vfm = vfm[vfm > 0].resample('1D').median()
    days = pd.date_range(ctx.t0.normalize(), ctx.t1.normalize(), freq='D')
    a = agzu.dropna()
    if a.empty:
        return vfm.reindex(days).dropna() if not vfm.dropna().empty else pd.Series(dtype=float)
    # дни ЗАМЕРОВ: первое значение и каждая смена суточного значения
    is_meas = a.ne(a.shift())
    meas_days = a.index[is_meas]
    last_meas = pd.Series(meas_days, index=meas_days).reindex(days).ffill()
    age_d = (pd.Series(days, index=days) - last_meas).dt.days
    q = a.reindex(days).ffill().where(age_d <= P['rplq_agzu_fresh_d'])   # АГЗУ свеж от даты замера
    if not vfm.dropna().empty:
        q = q.fillna(vfm.reindex(days))                                   # устарел -> ВР
    return q.dropna()


def _ip_env_daily(ctx):
    """Суточная огибающая Рпр: циклич. — межцикловая огибающая (медианы сегментов,
    интерполяция на сутки); прочие — rolling-медиана 7 сут рабочего Рпр (>0)."""
    days = pd.date_range(ctx.t0.normalize(), ctx.t1.normalize(), freq='D')
    if getattr(ctx, 'cyclic', False):
        env = ctx.rpr_envelope()
        if len(env) >= 3:
            e = env.copy(); e.index = e.index.normalize()
            e = e[~e.index.duplicated(keep='last')]
            return e.reindex(days).interpolate(limit=30).dropna()
    ip = ctx.wd[IP].dropna(); ip = ip[ip > 0]
    return ip.rolling(7, min_periods=3).median().reindex(days).dropna()


def _kprod_stable_after_opz(ctx, opz_iv, t):
    """True: последнее ОПЗ до t есть, и Кпрод в окне после него стабилен
    ((q90-q10)/медиана <= rplq_kprod_stab_frac) — тогда приоритет отдаётся Рпл."""
    P = ctx.P
    ends = [e for _, e in (opz_iv or []) if e < t]
    if not ends or ctx.kprod.dropna().empty:
        return False
    oe = max(ends)
    k = ctx.kprod[(ctx.kprod.index > oe) &
                  (ctx.kprod.index <= min(t, oe + pd.Timedelta(days=P['rplq_kprod_stab_win'])))].dropna()
    if len(k) < 5 or k.median() <= 0:
        return False
    return float((k.quantile(0.9) - k.quantile(0.1)) / k.median()) <= P['rplq_kprod_stab_frac']


def _q_meas_days(q):
    """Дни НЕЗАВИСИМЫХ значений Qж: первый день и каждая смена суточного значения.
    Между сменами ряд held/ffill — это ТО ЖЕ измерение, а не новая информация.
    Тренд, опирающийся на 1-2 таких дня, — ступенька, а не тренд."""
    if q is None or len(q) == 0:
        return []
    return list(q.index[q.ne(q.shift())])


def det_rpl_vogel(ctx, nur_iv=()):
    """Вогель-критерий Рпл (v10.5, гейты v10.9): изменение Qж при ПОСТОЯННОЙ огибающей
    Рпр (допуск rplq_ip_tol_frac). Обратный пересчёт Рпл по Вогелю при постоянном Кпрод J:
        Q = J/1.8 * (Рпл - 0.2·Рзаб - 0.8·Рзаб²/Рпл),  Рзаб ~ огибающая Рпр
        => Рпл = (b + sqrt(b² + 3.2·Рзаб²)) / 2,  b = 0.2·Рзаб + 1.8·Q/J.
    Флаг: |dРпл|/Рпл > rplq_chg15_frac за 15 сут ЛИБО > rplq_chg30_frac за 30 сут.

    v10.9 — окно засчитывается ТОЛЬКО если оно описывает тренд, а не разрыв данных:
      1. огибающая Рпр постоянна по всему окну (как и было);
      2. окно не задевает длинную остановку / смену ЭЦН (буфер rplq_edge_guard_d) —
         Qж и Рпр там рвутся по режимным причинам;
      3. в окне >= rplq_min_meas НЕЗАВИСИМЫХ значений Qж (held-замер АГЗУ не в счёт);
      4. фильтр «единого скачка»: max одиночный шаг Рпл <= rplq_step_ratio × |нетто|
         (зеркало критерия Б Снижения Рпл) + доля однонаправленных шагов >= rplq_mono_frac;
      5. режим стабилен: размах частоты по эпизоду (+буфер до него) <= rplq_fstab_hz —
         иначе изменение Qж объясняется УВЧ/УМЧ, а не пластовым давлением.
    Интервал красится ПО ОКНУ тренда [t-W, t], а не по дню оглядки: раньше одиночная
    ступенька Qж давала эпизод ровно в ширину окна, сдвинутый вперёд относительно события.
    Рост требует rplq_up_min_trend_d (репрессуризация медленнее истощения).
    Возвращает (снижение, рост) — сырые интервалы; приоритет Кпрод/ОПЗ — в label_well."""
    P = ctx.P
    q = _q_daily_pref_agzu(ctx); ipe = _ip_env_daily(ctx)
    if q.empty or ipe.empty:
        return [], []
    J = float(ctx.kprod.dropna().median()) if len(ctx.kprod.dropna()) else np.nan
    if not (np.isfinite(J) and J > 0) and 'tr_productivity' in ctx.tele:
        trp = pd.to_numeric(ctx.tele['tr_productivity'], errors='coerce').dropna()
        J = float(trp.median()) if len(trp) else np.nan
    if not (np.isfinite(J) and J > 0):
        return [], []
    df = pd.concat([q.rename('q'), ipe.rename('ip')], axis=1).dropna()
    if len(df) < P['rplq_min_trend_d'] + 1:
        return [], []
    b = 0.2 * df['ip'] + 1.8 * df['q'] / J
    pr = (b + np.sqrt(b * b + 3.2 * df['ip'] ** 2)) / 2.0

    meas = set(_q_meas_days(df['q']))
    guard = pd.Timedelta(days=P['rplq_edge_guard_d'])
    bad_iv = [(s - guard, e + guard) for s, e in getattr(ctx, 'long_stops', [])]
    bad_iv += [(t - guard, t + guard) for t in getattr(ctx, 'esp_breaks', [])]
    fr = ctx.wd[F].dropna() if F in ctx.wd else pd.Series(dtype=float)

    def _win_ok(a, e, sign):
        seg = df[(df.index >= a) & (df.index <= e)]
        if len(seg) < 3:
            return False
        # 1) огибающая Рпр постоянна по всему окну
        if not (seg['ip'].min() > 0 and
                (seg['ip'].max() / seg['ip'].min() - 1) <= P['rplq_ip_tol_frac']):
            return False
        # 2) окно не задевает длинную остановку / смену ЭЦН
        if any(min(e, _b) >= max(a, _a) for _a, _b in bad_iv):
            return False
        # 3) тренд опирается на независимые замеры Qж, а не на held-значение
        pts = [d for d in seg.index if d in meas]
        if len(pts) < P['rplq_min_meas']:
            return False
        # 4) «единый скачок» и монотонность — по замерным точкам
        v = pr.reindex(pts).dropna()
        if len(v) < 2:
            return False
        d = v.diff().dropna()
        net = float(v.iloc[-1] - v.iloc[0])
        if sign * net <= 0 or float(d.abs().max()) > P['rplq_step_ratio'] * abs(net):
            return False
        if float((sign * d > 0).sum()) / len(d) < P['rplq_mono_frac']:
            return False
        return True

    def _f_stable(a, e):
        """Режим неизменен на эпизоде и на подходе к нему: рост/спад Qж после смены
        частоты — это УВЧ/УМЧ, а не пластовое давление."""
        f = fr[(fr.index >= a - guard) & (fr.index <= e)].dropna()
        f = f[f > 0]
        if len(f) < 4:
            return True
        return float(f.max() - f.min()) <= P['rplq_fstab_hz']

    fdn = pd.Series(False, index=df.index); fup = fdn.copy()
    idx = list(pr.index)
    for W, thr in ((15, P['rplq_chg15_frac']), (30, P['rplq_chg30_frac'])):
        for k in range(W, len(idx)):
            t = idx[k]; a = idx[k - W]
            p0 = float(pr.iloc[k - W])
            if not (p0 > 0):
                continue
            rel = float(pr.iloc[k] - p0) / p0
            sign = 1 if rel >= thr else (-1 if rel <= -thr else 0)
            if sign == 0 or not _win_ok(a, t, sign):
                continue
            # красим ОКНО тренда (не день оглядки), обрезав плоские хвосты:
            # начало = последний день на «полке» до движения, конец = первый день на новой полке
            seg = pr[(pr.index >= a) & (pr.index <= t)]
            band = P['rplq_edge_trim_frac'] * abs(float(seg.max() - seg.min()))
            lo = seg[seg <= seg.min() + band]; hi = seg[seg >= seg.max() - band]
            a2, t2 = (lo.index[-1], hi.index[0]) if sign > 0 else (hi.index[-1], lo.index[0])
            if t2 <= a2:
                a2, t2 = a, t
            win = (df.index >= a2) & (df.index <= t2)
            if sign > 0:
                fup[win] = True
            else:
                fdn[win] = True
    for d in df.index:
        if in_any(d, nur_iv):
            fdn.loc[d] = False; fup.loc[d] = False

    def _ip_const(a, e):
        # постоянство огибающей Рпр по ВСЕМУ интервалу тренда (не только в окне)
        seg = df['ip'][(df.index >= a) & (df.index <= e)]
        return len(seg) > 0 and seg.min() > 0 and (seg.max() / seg.min() - 1) <= P['rplq_ip_tol_frac']
    dn = [(a, e) for a, e in _flag_to_iv(fdn)
          if (e - a).days + 1 >= P['rplq_min_trend_d'] and _ip_const(a, e) and _f_stable(a, e)]
    up = [(a, e) for a, e in _flag_to_iv(fup)
          if (e - a).days + 1 >= P['rplq_up_min_trend_d'] and _ip_const(a, e) and _f_stable(a, e)]
    return dn, up


def det_snizh_rpl(ctx, nur_iv, gdi_iv, rptch_iv=()):
    """Снижение Рпл — объединение трёх критериев (вне НУР/ГДИ/РПТЧ):
    А) непрерывный trend-run ≥2 сут, ≥2 бар, скорость ≤2 бар/сут;
    Б) скользящее окно 14 сут: падение сглаж. Рпр ≥3 бар при |Δчастоты|≤2 Гц;
    В) долгосрочный тренд в рамках одного рабочего сегмента:
       падение сглаж. Рпр (MA15) ≥4 бар за 45-суточное окно."""
    P = ctx.P
    if getattr(ctx, 'cyclic', False):
        env = ctx.rpr_envelope()
        _env = ([(s, e + pd.Timedelta(hours=23))
                 for s, e in _env_runs(env, -1, P['rpl_env_min_bar'], P['rpl_env_tol'])]
                if len(env) >= 3 else [])
        # v9.9: + спад МОДЕЛИ Рпл в НЕПРЕРЫВНОЙ работе при стабильной частоте —
        # истощение внутри длинного сегмента, невидимое межцикловой огибающей (Vt_605).
        _cont = _rpl_model_decline(ctx, nur_iv)
        return merge_iv(_env + _cont)
    # v10.15: нули/отрицательные суточные средние Рпр = мёртвый датчик / нет
    # данных (насос работает, частота стабильна), а НЕ реальное падение до нуля.
    # Без фильтра такой провал даёт огромный фиктивный "тренд" (Ic_368, апр-май
    # 2025: частота ~50 Гц весь период, датчик Рпр отвалился на 75->0 на 2 недели).
    ip = ctx.wd[IP].where(ctx.wd[IP] > 0).rolling(3, min_periods=2).mean()
    f  = ctx.wd[F]
    out = []

    # А: trend-runs
    runs = _trend_runs(ip, P['snizh_run_d'], P['snizh_total_bar'],
                       max_slope=P['snizh_max_slope'], sign=-1, tol=P['snizh_tol'])
    for s, e, d in runs:
        if in_any(s, nur_iv) or in_any(e, nur_iv): continue
        if in_any(s, gdi_iv): continue
        fseg = f[(f.index >= s) & (f.index <= e)].dropna()
        # v10.13: сравниваем МЕДИАНУ первых/последних дней окна, а не одну крайнюю
        # точку — суточное среднее частоты на дне с частичным стопом/рестартом может
        # быть искажено (напр. 59->48 Гц за один день из-за короткой остановки внутри
        # суток), давая ложный «скачок режима» на границе устойчивого тренда (Ic_368).
        if len(fseg) >= 2:
            k = min(3, len(fseg))
            dfreq = abs(fseg.iloc[-k:].median() - fseg.iloc[:k].median())
            if dfreq > P['snizh_max_dfreq']:
                continue
        out.append((s, e + pd.Timedelta(hours=23)))

    # Б: скользящее окно
    W = P['snizh_win_d']
    dip = ip - ip.shift(W); dfr = f - f.shift(W)
    flag = pd.Series(False, index=ctx.days)
    for d in ctx.days:
        if pd.isna(dip.get(d)) or dip[d] > -P['snizh_win_drop']: continue
        if pd.isna(dfr.get(d)) or abs(dfr[d]) > P['snizh_max_dfreq']: continue
        if in_any(d, nur_iv) or in_any(d, rptch_iv): continue
        # Фильтр «единого скачка»: если одно суточное изменение Рпр
        # составляет > snizh_step_ratio доли всего падения за окно —
        # это скорее артефакт остановки, а не плавный тренд Рпл
        win_start = d - pd.Timedelta(days=W)
        ip_win = ip[(ip.index >= win_start) & (ip.index <= d)].dropna()
        if len(ip_win) >= P['snizh_step_min_pts']:
            total_drop = ip_win.iloc[0] - ip_win.iloc[-1]
            if total_drop > 0:
                max_step = ip_win.diff().abs().dropna().max()
                if max_step / total_drop > P['snizh_step_ratio']:
                    continue   # единый скачок — пропускаем
        flag[d] = True
    out += _flag_to_iv(flag)

    # В: долгосрочный тренд в ESP-сегменте (ловит медленный многомесячный тренд)
    W_seg = P['snizh_seg_win_d']
    drop_seg = P['snizh_seg_drop_bar']
    W_near = P['snizh_seg_near_win_d']
    for seg_s, seg_e in ctx.work_segments():
        seg_ip = ip[(ip.index >= seg_s.normalize()) & (ip.index <= seg_e.normalize())].dropna()
        if len(seg_ip) < P['snizh_seg_min_pts']: continue
        # MA15 для шумоподавления, затем 45-суточное изменение
        sm = seg_ip.rolling(15, min_periods=7).mean()
        sm_drop = sm - sm.shift(W_seg)
        # v10.15: подтверждение БЛИЖНИМ трендом (15 сут) — 45-суточное окно
        # тянет "хвост" уже закончившегося спада: если якорная точка 45 сут
        # назад ещё лежит на склоне предыдущего эпизода, критерий продолжает
        # сигналить недели после того, как Рпр реально вышел на полку (Ic_368,
        # фев-мар 2025: спад Jan-Feb уже кончился, а C светит до 8 мар).
        # Без confirmation, что и ПОСЛЕДНИЕ 15 сут тоже снижались (с допуском),
        # такие "хвосты" ложно продлевают эпизод.
        sm_near = sm - sm.shift(W_near)
        flag_c = pd.Series(False, index=ctx.days)
        for d, v in sm_drop.dropna().items():
            if v > -drop_seg: continue
            nv = sm_near.get(d)
            if pd.isna(nv) or nv > P['snizh_seg_near_tol']: continue
            # Критерий C — долгосрочный тренд: РПТЧ не фильтруем
            # (медленный спад Рпл виден поверх осцилляций частоты)
            if in_any(d, nur_iv): continue
            if d in flag_c.index:
                flag_c[d] = True
        # v10.15: отсекаем короткие "хвостики" (< snizh_seg_min_run_d сут) —
        # даже после near-подтверждения остаток лага сглаживания может дать
        # короткий (неск. суток) остаточный флаг сразу после разворота тренда.
        c_ivs = [(a, e) for a, e in _flag_to_iv(flag_c)
                 if (e - a).days + 1 >= P['snizh_seg_min_run_d']]
        out += c_ivs

    res = merge_iv(out, gap=pd.Timedelta(days=3))
    res = subtract_iv(res, nur_iv)   # НУР и Снижение Рпл не должны накладываться
    return res


def det_rost_rpl(ctx, uvch_iv, nur_iv):
    if getattr(ctx, 'cyclic', False):
        # Рост Рпл ТОЛЬКО ВНУТРИ рабочих сегментов (не через остановки): устойчивый
        # рост Рпр в пределах одного непрерывного интервала работы. Соединять
        # медианы сегментов через остановки (огибающая) для РОСТА нельзя —
        # это даёт ложный рост (напр. Ya_357, где внутри сегментов Рпр только падает).
        ip = ctx.wd[IP].dropna()
        P = ctx.P; out = []
        for s2, e2 in ctx.work_segments():
            seg = ip[(ip.index >= s2.normalize()) & (ip.index <= e2.normalize())]
            seg = seg[~seg.index.to_series().apply(lambda t: in_any(t, nur_iv))]  # вне НУР (восстановление != рост Рпл)
            seg = seg.rolling(3, min_periods=1).mean().dropna()
            if len(seg) < P['rost_seg_min_d']:
                continue
            k = max(1, len(seg) // 3)
            # НЕТТО рост сегмента (конец выше начала), а не локальные подъёмы хвоста
            # восстановления -> реальный рост Рпл при работе (Ya_357/Ya_289 -> 0)
            if seg.iloc[-k:].median() - seg.iloc[:k].median() >= P['rost_seg_rise_bar']:
                out.append((seg.index[0], seg.index[-1] + pd.Timedelta(hours=23)))
        # v12.5: финальная защита — как и в det_snizh_rpl. Убор точек НУР из ряда не
        # гарантирует, что итоговые границы (первая/последняя точка ПОСЛЕ фильтрации)
        # не охватят сам НУР целиком: если разрыв дат по обе стороны НУР <= допуска
        # склейки, прогон «перескакивает» через исключённые дни. Жёстко обрезаем.
        return subtract_iv(merge_iv(out), nur_iv)
    """Рост Рпл — МОНОТОННЫЙ рост пластового давления. v7:
      • Вместо прежнего фильтра «не начинать в первые N сут после крупной
        остановки» применяется критерий монотонности: ищем максимальные
        монотонно-возрастающие прогоны точек Рпл (каждый шаг не падает больше
        rost_mono_tol; интервал между точками <= rost_max_gap_d).
      • Прогон засчитывается, если содержит >= rost_min_steps восходящих шагов
        (>=3 точки) И суммарный рост >= rost_rise_bar. Одиночный скачок
        (напр. возврат давления после остановки) монотонным прогоном не является.
      • Доп. фильтры сохранены: Рпр (интейк) не должен сильно падать; начало вне НУР."""
    P = ctx.P
    # v10.3: тренд Рпл измеряем ТОЛЬКО по РАБОЧИМ точкам (ctx.wd — остановки и
    # рестарт-переходы уже исключены). Сырая телеметрия включает накопление Рпр во
    # время частых остановок -> ложный «рост» из восстановления между остановками на
    # нециклических скважинах (Ic_370/Ic_349/Ic_359). Реальный рост Рпл виден в работе.
    if IP not in ctx.wd:
        return []
    rp = ctx.wd[IP].dropna()
    rp = rp[rp > 0].rolling(7, min_periods=2).median().dropna()
    # исключаем точки внутри НУР — восстановление давления после остановки/НУР не рост.
    rp = rp[~rp.index.to_series().apply(lambda t: in_any(t, nur_iv))]
    if len(rp) < 2:
        return []
    ip = ctx.wd[IP].rolling(3, min_periods=2).mean()
    days = list(rp.index); vals = list(rp.values)
    out = []
    i = 0
    while i < len(days) - 1:
        # Прогон начинается только с восходящего шага
        if vals[i + 1] - vals[i] < P['rost_mono_tol']:
            i += 1; continue
        j = i; steps = 0
        while j < len(days) - 1:
            gap = (days[j + 1] - days[j]).days
            if gap < 1 or gap > P['rost_max_gap_d']:
                break
            if vals[j + 1] - vals[j] < -P['rost_mono_tol']:
                break                      # просадка > tol → конец монотонного прогона
            if vals[j + 1] - vals[j] > P['rost_max_step_bar']:
                break                      # нефизичный скачок (мусор датчика) → конец прогона
            if vals[j + 1] - vals[j] >= P['rost_mono_tol']:
                steps += 1                 # явный восходящий шаг
            j += 1
        net = vals[j] - vals[i]
        if j > i and steps >= P['rost_min_steps'] and net >= P['rost_rise_bar']:
            s_ep, e_ep = days[i], days[j]
            # Критерий = монотонность Рпл. Прежний veto по падению Рпр снят:
            # рост Рпл при снижении Рпр (интейка) физически согласован.
            if not in_any(s_ep, nur_iv):
                out.append((s_ep, e_ep))
        i = max(j, i + 1)
    # v12.5: та же финальная защита, что и в циклической ветке выше / в det_snizh_rpl:
    # проверка `in_any(s_ep, nur_iv)` смотрела только на НАЧАЛО прогона — конец (e_ep)
    # мог оказаться уже ПОСЛЕ НУР, а сам интервал (s_ep, e_ep) — охватывать НУР целиком,
    # т.к. точки внутри НУР исключены из ряда `rp`, а не оставляют в нём разрыв,
    # который алгоритм монотонного прогона обязан был бы уважать.
    return subtract_iv(merge_iv(out), nur_iv)


def _wcut_series(ctx):
    """Суточный ряд Обв_алгоритма (water_cut_algo) для классификации тренда обводнённости.
    Между сутками без новых данных (внутри остановки, до wct_src_max_gap_d суток) уровень
    интерполируется по ВРЕМЕНИ — иначе позиционные окна (v13.3/episode_rules_v12_8) давали
    разный результат в зависимости от плотности данных (частые дни в работе / редкие
    после долгих остановок), см. episode_rules_v12_9."""
    P = ctx.P
    w = ctx.tele.get('water_cut_algo')
    if w is None:
        return pd.Series(dtype=float)
    w = pd.to_numeric(w, errors='coerce')
    w = w.where(w.between(P['wct_valid_lo'], P['wct_valid_hi'])).dropna()
    if len(w) < 4:
        return pd.Series(dtype=float)
    d = w.resample('1D').median()
    lim = int(P['wct_src_max_gap_d'])
    return d.interpolate('time', limit=lim, limit_area='inside').dropna()


def det_wcut(ctx):
    """Рост/Снижение обводнённости — правило эксперта, буквально в два шага (v12).

    ШАГ 1. Изменение Обв_алгоритма >= wct_trend_pp (3 пп) в скользящем окне
           wct_step_win_d (5 сут)? Нет — колебания пробоотбора, дальше не идём.
    ШАГ 2. Тренд длится >= wct_min_d (7 сут) при откате <= wct_tol_pp (1 пп) и
           новый уровень УДЕРЖИВАЕТСЯ следующие wct_hold_win_d (7 сут)? Нет — пик
           с возвратом. Да — эпизод.

    ТОЧНЫЕ ГРАНИЦЫ. Тренд РАСТЁТ от точки-кандидата в обе стороны, а не красится целым
    окном [t-wd, t], как в v13.4/v13.5: оконная покраска смещала начало эпизода и
    склеивала соседние однонаправленные окна в длинный прогон (Ic_349: снижение
    09-22.04.2025 выходило как 10.04-31.07). Рост останавливают ДВА условия:
      * разворот — откат от достигнутого экстремума больше wct_tol_pp;
      * ВЫПОЛАЖИВАНИЕ — движение за последние wct_flat_win_d суток меньше wct_flat_pp.
    Второе и даёт точный конец: на полке после спада ряд не разворачивается, и без
    проверки выполаживания прогон уезжал на месяцы вперёд.
    """
    P = ctx.P
    sm = _wcut_series(ctx)
    if len(sm) < P['wct_min_d'] + P['wct_hold_win_d']:
        return [], []
    sm = sm.rolling(f"{P['wct_smooth_d']}D", min_periods=1).mean()
    idx = list(sm.index)
    v = sm.to_numpy(dtype=float)
    n = len(v)
    tol = P['wct_tol_pp']
    thr = P['wct_trend_pp']
    flat_w = int(P['wct_flat_win_d'])
    flat_pp = P['wct_flat_pp']
    hold = int(P['wct_hold_win_d'])
    min_d = pd.Timedelta(days=P['wct_min_d'])

    # ШАГ 1 — кандидаты по скользящему окну wct_step_win_d
    step = pd.Timedelta(days=P['wct_step_win_d'])
    past = sm.reindex(sm.index - step, method='nearest', tolerance=step)
    delta = v - past.to_numpy(dtype=float)

    def _runs(sign):
        out, used = [], np.zeros(n, dtype=bool)
        order = sorted(range(n), key=lambda k: -abs(delta[k]) if np.isfinite(delta[k]) else 0)
        for k in order:
            if used[k] or not np.isfinite(delta[k]) or sign * delta[k] < thr:
                continue
            # --- рост вперёд ---
            j, ext = k, v[k]
            while j < n - 1:
                nv = v[j + 1]
                if sign * (ext - nv) > tol:
                    break                                   # разворот
                if sign * (nv - ext) > 0:
                    ext = nv
                m = max(k, j + 1 - flat_w)
                if j + 1 - m >= flat_w - 1 and sign * (nv - v[m]) < flat_pp:
                    break                                   # выполаживание -> точный конец
                j += 1
            # --- рост назад ---
            i, ext = k, v[k]
            while i > 0:
                pv = v[i - 1]
                if sign * (pv - ext) > tol:
                    break                                   # за пиком начинается чужой тренд
                if sign * (ext - pv) > 0:
                    ext = pv
                m = min(k, i - 1 + flat_w)
                if m - (i - 1) >= flat_w - 1 and sign * (v[m] - pv) < flat_pp:
                    break                                   # выполаживание -> точное начало
                i -= 1
            if idx[j] - idx[i] < min_d or sign * (v[j] - v[i]) < thr:
                continue
            # ШАГ 2 — удержание нового уровня
            tail = v[j:min(n, j + hold + 1)]
            if len(tail) >= 2:
                back = sign * (v[j] - (float(np.min(tail)) if sign > 0 else float(np.max(tail))))
                if back > max(tol, 0.25 * abs(v[j] - v[i])):
                    continue                                # пик с возвратом
            if used[i:j + 1].any():
                continue
            used[i:j + 1] = True
            out.append((idx[i], idx[j] + pd.Timedelta(hours=23)))
        return merge_iv(sorted(out), gap=pd.Timedelta(days=P['wct_merge_gap_d']))

    return _runs(1), _runs(-1)


def _env_runs(env, sign, min_bar, tol):
    """Монотонные прогоны огибающей Рпр (sign=+1 рост / -1 снижение)."""
    vals = list(env.values); idx = list(env.index); out = []; i = 0
    while i < len(vals) - 1:
        j = i
        while j < len(vals) - 1 and sign * (vals[j + 1] - vals[j]) >= -tol:
            j += 1
        if j > i and sign * (vals[j] - vals[i]) >= min_bar:
            out.append((idx[i], idx[j]))
        i = max(j, i + 1)
    return out


def _is_complicated(ctx):
    """Осложнённый фонд = есть кластеры ОПЗ (повторные обработки/отказы). На таком
    фонде эксперт метит Кпрод per-провал (частые короткие спады с восстановлением
    между обработками), поэтому и детекция, и метрика эффекта — по ПРОВАЛУ, а не
    по нетто конец-минус-начало. Признак берётся из данных (vsp), не из списка скважин."""
    c = getattr(ctx, '_complicated', None)
    if c is None:
        c = len(det_opz_clusters(ctx)) > 0
        ctx._complicated = c
    return c


def kprod_drawdown_frac(ctx, s, e):
    """Максимальная ПРОСАДКА расч. Кпрод внутри эпизода (доля от стартового уровня).
    Для осложнённого фонда: провал с последующим восстановлением — реальное событие,
    нетто конец-минус-начало его маскирует."""
    K = _xseg(getattr(ctx, 'kprod', None), s, e)
    if K is None or len(K) < 4:
        return None
    Ks = K.rolling(3, min_periods=1).mean()
    k = max(1, len(Ks) // 3)
    a = float(Ks.iloc[:k].median())
    if not (a > 0):
        return None
    return float(Ks.min() - a) / a       # <= 0: глубина провала


def kprod_q_net_frac(ctx, s, e):
    """НЕТТО изменение ОГИБАЮЩЕЙ дебита жидкости за эпизод (доля от уровня в начале).
    Qж — прямое свидетельство продуктивности; расчётный Кпрод = Q/dP производен от него
    и от депрессии, поэтому при расхождении верить надо дебиту."""
    q = _q_any_daily(ctx)
    if q is None:
        return None
    w = int(ctx.P['kprod_q_env_win_d'])
    qe = q.rolling(w, min_periods=max(2, w // 2), center=True).median()
    seg = qe[(qe.index >= s.normalize()) & (qe.index <= e.normalize())].dropna()
    if len(seg) < 4:
        return None
    k = max(1, len(seg) // 3)
    a = float(seg.iloc[:k].median())
    if not (a > 0):
        return None
    return float(seg.iloc[-k:].median() - a) / a


def kprod_net_frac(ctx, s, e):
    """НЕТТО изменение расч. Кпрод по эпизоду (доля от уровня в начале): медиана
    последней трети против первой. Единственная метрика, которой пользуются И фильтр,
    И текст пояснения — иначе они расходятся и эпизод отчитывается о том, чего нет."""
    K = _xseg(getattr(ctx, 'kprod', None), s, e)
    if K is None or len(K) < 4:
        return None
    k = max(1, len(K) // 3)
    a = float(K.iloc[:k].median())
    if not (a > 0):
        return None
    return float(K.iloc[-k:].median() - a) / a


def det_kprod_rise(ctx, opz_iv=(), nur_iv=()):
    """Рост Кпрод — устойчивый РОСТ расч. Кпрод (зеркально Снижению). Реже и
    обычно крупнее, поэтому порог импульса выше (kprod_rise_pulse)."""
    P = ctx.P
    K = getattr(ctx, 'kprod', pd.Series(dtype=float))
    if getattr(ctx, 'cyclic', False):
        opz_iv = [(ctx.t0, ctx.t1)]
    if len(K) < 5 or not opz_iv:
        return []
    out = []
    # Рост Кпрод ТОЛЬКО ВНУТРИ рабочих сегментов (рост на восстановлении после
    # стопа через границу остановки — не считается).
    for s2, e2 in ctx.work_segments():
        Ks = K[(K.index >= s2.normalize()) & (K.index <= e2.normalize())]
        Ks = Ks[~Ks.index.to_series().apply(lambda t: in_any(t, nur_iv))]  # вне НУР (восстановление != рост Кпрод)
        Ks = Ks.rolling(3, min_periods=1).mean().dropna()
        if len(Ks) < P['kprod_min_d']:
            continue
        k = max(1, len(Ks) // 3)
        a = Ks.iloc[:k].median(); b = Ks.iloc[-k:].median()
        # НЕТТО рост расч. Кпрод в сегменте (вне восстановления)
        if a > 0 and (b - a) / a >= P['kprod_rise_pulse']:
            out.append((Ks.index[0], Ks.index[-1]))
    return merge_iv(out, gap=pd.Timedelta(days=P['kprod_merge_gap_d']))


def _kprod_env_decl(ctx):
    """Нетто-изменение огибающей расч.Кпрод (медиана по рабочим сегментам) за жизнь.
    < 0 -> снижение продуктивности; ~0 / > 0 -> продуктивность не снижается."""
    K = getattr(ctx, 'kprod', pd.Series(dtype=float))
    seg = []
    for s, e in ctx.work_segments():
        v = K[(K.index >= s) & (K.index <= e)]
        if len(v) >= 3:
            seg.append(v.median())
    if len(seg) < 3 or seg[0] <= 0:
        return 0.0
    return (seg[-1] - seg[0]) / seg[0]


def det_kprod_drop(ctx, opz_iv=(), nur_iv=()):
    """v9.3: Снижение Кпрод = импульсы падения РАСЧЁТНОГО Кпрод ВНУТРИ кластеров ОПЗ
    (opz_iv, независимый сигнал). Эксперт метит Кпрод как частые короткие спады именно в период
    повторных обработок/отказов (Ic_805, Ic_914). Вне осложнённого фонда отдельные
    дипы Кпрод эксперт не выделяет -> не флагаем (убирает фантомы на нормальных
    скважинах: Mc_1003, Vt_606, Vt_655-вне CF и т.д.)."""
    P = ctx.P
    K = getattr(ctx, 'kprod', pd.Series(dtype=float))
    # НЕциклическая: Снижение Кпрод = ТЕРМИНАЛЬНЫЙ монотонный спад расч.Кпрод
    # (падает и НЕ восстанавливается). Отличает реальное снижение продуктивности (Vt_3311,
    # Ic_370, Da_515) от шумовых отскоков; ОПЗ не требуется.
    # v10.17: импульсная ветка — для циклических И для осложнённого фонда (кластеры
    # ОПЗ): эксперт метит там Кпрод per-провал независимо от частоты остановок (Ya_289:
    # редкие стопы, но ОПЗ-кластер и 24 ручных коротких спада).
    if not (getattr(ctx, 'cyclic', False) or _is_complicated(ctx)):
        if len(K) < P['kprod_term_win']:
            return []
        Ks = K.rolling(7, min_periods=3).mean().dropna()
        win = P['kprod_term_win']; out = []; i = win
        while i < len(Ks):
            seg = Ks.iloc[i - win:i + 1]; d = seg.diff().dropna()
            fr = (d < 0).mean()
            tot = (seg.iloc[0] - seg.iloc[-1]) / seg.iloc[0] if seg.iloc[0] > 0 else 0
            if fr >= P['kprod_term_mono'] and tot >= P['kprod_term_drop']:
                endv = seg.iloc[-1]; after = Ks.iloc[i + 1:]
                if len(after) == 0 or after.max() <= endv + P['kprod_term_rec'] * (seg.iloc[0] - endv):
                    out.append((seg.index[0], seg.index[-1])); i += win; continue
            i += 1
        return merge_iv(out, gap=pd.Timedelta(days=P['kprod_merge_gap_d']))
    # Циклическая (Вариант B): детектируем по ВСЕЙ жизни. ОПЗ — НЕ определяющий, а
    # ПОДТВЕРЖДАЮЩИЙ фактор (учитывается в уверенности score_episode). Скважина может
    # деградировать без ОПЗ; задача — найти Снижение Кпрод из сигнала.
    if len(K) < 5:
        return []
    # v10.3: осложнённый/периодический фонд = есть кластеры ОПЗ. На таком фонде Кпрод
    # детектируем ЧУВСТВИТЕЛЬНЕЕ обычного: длиннее окно (ловим плавные спады, Ic_914 апр)
    # и без шумовых гейтов (персистентность/tr_productivity — они для ОБЫЧНЫХ скважин,
    # чтобы убрать дрейф Рпр у Ic_367). Обычная скважина без ОПЗ -> строгий путь.
    _opzc = det_opz_clusters(ctx)
    _complicated = len(_opzc) > 0
    span = P['kprod_pulse_span']
    drop = P['kprod_pulse_drop_cyclic'] if _complicated else P['kprod_pulse_drop']
    Ks = K.rolling(3, min_periods=1).mean().dropna()
    idx = list(Ks.index); v = list(Ks.values)
    flag = pd.Series(False, index=Ks.index)
    for i in range(len(v)):
        for j in range(max(0, i - span), i):
            if v[j] > 0 and (v[j] - v[i]) / v[j] >= drop:
                flag[idx[i]] = True; break
    out = merge_iv(_flag_to_iv(flag), gap=pd.Timedelta(days=P['kprod_pulse_gap']))
    _Kd = K.rolling(3, min_periods=1).mean()
    # v10.3: модельная продуктивность tr_productivity (независимый сигнал, корректно
    # учитывает связь давление-дебит) — суточная медиана для подтверждения не-ОПЗ эпизодов.
    _trp = pd.Series(dtype=float)
    if 'tr_productivity' in getattr(ctx, 'tele', {}):
        _trp = pd.to_numeric(ctx.tele['tr_productivity'], errors='coerce').dropna()
        if len(_trp):
            _trp = _trp.resample('1D').median().dropna()

    def _trprod_confirms(_s, _e):
        """True, если ЕСТЬ данные tr_productivity и они подтверждают РЕАЛЬНЫЙ спад
        (>= kprod_trprod_min_decl). None — если данных нет (тогда гейт не применяем)."""
        if len(_trp) == 0:
            return None
        _w = pd.Timedelta(days=P['kprod_trprod_win'])
        _pre = _trp[(_trp.index >= _s - _w) & (_trp.index < _s)].median()
        _post = _trp[(_trp.index >= _e - pd.Timedelta(days=3)) & (_trp.index <= _e + _w)].median()
        if pd.isna(_pre) or pd.isna(_post) or _pre <= 0:
            return None
        return bool(((_pre - _post) / _pre) >= P['kprod_trprod_min_decl'])

    _kept = []
    for _s, _e in out:
        if in_any(_s, _opzc) or in_any(_e, _opzc):
            _kept.append((_s, _e)); continue
        # v10.3: осложнённый фонд — чувствительный режим: импульс падения (>=drop за span)
        # принимаем без шумовых гейтов (характер работы стабильно осложнён; Ic_914 апр).
        if _complicated:
            _kept.append((_s, _e)); continue
        _pre = _Kd[(_Kd.index >= _s - pd.Timedelta(days=P['kprod_hold_d'])) & (_Kd.index < _s)].median()
        _post = _Kd[(_Kd.index > _e) & (_Kd.index <= _e + pd.Timedelta(days=P['kprod_hold_d']))].median()
        if pd.isna(_pre) or pd.isna(_post) or _pre <= 0:
            _kept.append((_s, _e)); continue
        if not (_post <= _pre * (1.0 - P['kprod_hold_frac'])):
            continue
        # v10.3: спад расч.Кпрод удержался, но без ОПЗ требуем подтверждения модельной
        # продуктивностью. Если tr_productivity НЕ падает -> это дрейф Рпр (Ic_367), убираем.
        _conf = _trprod_confirms(_s, _e)
        if _conf is False:
            continue
        _kept.append((_s, _e))
    return merge_iv(_kept, gap=pd.Timedelta(days=P['kprod_pulse_gap']))


def _wd_daily(ctx, col, lim=3):
    """Рабочая дневная серия столбца (ctx.wd) с интерполяцией мелких дыр."""
    s = ctx.wd.get(col) if (hasattr(ctx, 'wd') and col in ctx.wd) else None
    if s is None:
        return None
    s = s.dropna()
    if len(s) < 4:
        return None
    grid = pd.date_range(s.index.min(), s.index.max(), freq='D')
    return s.reindex(grid).interpolate(limit=lim), grid


def _clear_stops(eps, ctx, buf_d):
    """Отбросить эпизоды (УВЧ/УМЧ), пересекающие длинную остановку (с буфером):
    изменение частоты при остановке самоочевидно и не является УВЧ/УМЧ."""
    if not eps:
        return eps
    ls = ctx.long_stops
    out = []
    for s, e in eps:
        lo = s - pd.Timedelta(days=buf_d)
        if any((ss <= e and ee >= lo) for ss, ee in ls):
            continue
        out.append((s, e))
    return out


def _bool_runs(flag, min_d):
    """Непрерывные прогоны True длиной >= min_d суток."""
    out = []; st = None; last = None
    for d, v in flag.items():
        if v:
            if st is None: st = d
            last = d
        elif st is not None:
            if (last - st).days + 1 >= min_d:
                out.append((st, last))
            st = None
    if st is not None and (last - st).days + 1 >= min_d:
        out.append((st, last))
    return out


def _degr_eligible(ctx, grid, nur_iv):
    """Маска пригодных суток для Деградации/Деоптимизации: вне окрестности длинных
    остановок (+-degr_stop_clear_d), вне НУР, без шероховатости Рпр (волатильность)."""
    P = ctx.P
    elig = pd.Series(True, index=grid)
    for ss, ee in ctx.long_stops:
        lo = ss.normalize() - pd.Timedelta(days=P['degr_stop_clear_d'])
        hi = ee.normalize() + pd.Timedelta(days=P['degr_stop_clear_d'])
        elig[(grid >= lo) & (grid <= hi)] = False
    if nur_iv:
        nm = np.array([in_any(d, nur_iv) for d in grid])
        elig[nm] = False
    ip = ctx.wd.get(IP)
    if ip is not None:
        ipd = ip.reindex(grid).interpolate(limit=3)
        m = ipd.rolling(7, min_periods=3).mean().abs().replace(0, np.nan)
        vol = (ipd.rolling(7, min_periods=3).std() / m)
        elig[(vol > P['degr_ip_rough']).fillna(False).values] = False
    return elig


def _q_sources_daily(ctx):
    """(замер АГЗУ, виртуальный расходомер) посуточно — РАЗДЕЛЬНО, не смешивая.
    Смешивание опасно: у Ic_370 замер АГЗУ растёт +10%, а виртуальный расходомер за
    тот же период падает -9% («виртуальный расходомер врёт»). Заполнение дыр редкого
    замера виртуальным рядом подменяло факт моделью и порождало ложную деградацию."""
    def _pick(col):
        s = ctx.wd.get(col) if col in ctx.wd else None
        if s is None:
            return None
        s = pd.to_numeric(s, errors='coerce')
        return s.where(s > 0)
    return _pick(QL), _pick('tr_liquid_rate')


def _q_any_daily(ctx):
    """Единый ряд Qж для ТРЕНДА: замер АГЗУ, дыры закрываются виртуальным расходомером."""
    meas, vfm = _q_sources_daily(ctx)
    if meas is None:
        return vfm
    return meas if vfm is None else meas.fillna(vfm)


def det_degr(ctx, nur_iv=()):
    """Деградация ЭЦН (v12) — устойчивый рост ОГИБАЮЩЕЙ загрузки при неувеличивающемся
    дебите. Переписано с точечного критерия на трендовый:
      * загрузка и Qж сглаживаются скользящей медианой degr_env_win_d (огибающая) —
        точечные скачки канала больше не создают эпизод;
      * сравнивается окно degr_trend_win_d (2 недели), а не концы 5-дневки;
      * рост огибающей Qж за окно -> ВЕТО: растущий дебит исключает деградацию;
      * рост частоты за окно -> ВЕТО: это УВЧ, загрузка растёт от режима, а не от износа.
    Эпизод обязан быть не короче окна тренда."""
    P = ctx.P
    r = _wd_daily(ctx, LD)
    if r is None:
        return []
    ldd, grid = r
    env = int(P['degr_env_win_d']); W = int(P['degr_trend_win_d'])
    lde = ldd.rolling(env, min_periods=max(2, env // 2), center=True).median()
    qd = _q_any_daily(ctx)
    q_meas, _ = _q_sources_daily(ctx)             # фактический замер отдельно (см. вето ниже)
    qe = (qd.reindex(grid).interpolate(limit=env)
            .rolling(env, min_periods=max(2, env // 2), center=True).median()) if qd is not None else None
    fr = ctx.wd.get(F)
    fe = (fr.reindex(grid).interpolate(limit=env)
            .rolling(env, min_periods=max(2, env // 2), center=True).median()) if fr is not None else None
    ipd = ctx.wd.get(IP)
    ipe = (ipd.reindex(grid).interpolate(limit=env)
             .rolling(env, min_periods=max(2, env // 2), center=True).median()) if ipd is not None else None
    elig = _degr_eligible(ctx, grid, nur_iv)

    out = []
    for k in range(W, len(grid)):
        win = grid[k - W:k + 1]
        if not bool(elig.reindex(win).all()):
            continue
        lw = lde.reindex(win)
        if lw.isna().any() or lw.iloc[0] <= 0:
            continue
        # ОСНОВНОЙ ПРИЗНАК — УДЕЛЬНАЯ загрузка на единицу подачи (load/Qж). Именно её
        # рост объединяет оба типа деградации в ручной разметке: Mc_010 (загрузка
        # 73->88% при том же Qж) и Vt_3311 (загрузка держит 89% при падении Qж 367->329).
        # Побочный эффект нужного знака: УВЧ, поднимающее и загрузку, и подачу, отношение
        # почти не двигает и эпизода не создаёт.
        sw = None
        if qe is not None:
            qw = qe.reindex(win)
            if not qw.isna().any() and float(qw.min()) > 0:
                sw = lw / qw
        if sw is None:
            sw = lw                                   # резерв: нет Qж -> сама загрузка
        if sw.iloc[0] <= 0 or (sw.iloc[-1] - sw.iloc[0]) / sw.iloc[0] < P['degr_trend_load_frac']:
            continue
        # ВЕТО: сама загрузка не должна падать. Деградация — это когда насос работает
        # ТЯЖЕЛЕЕ; падающая загрузка при падающем дебите означает ограничение притока.
        if (lw.iloc[-1] - lw.iloc[0]) / lw.iloc[0] < P['degr_load_nonfall_frac']:
            continue
        if int((sw.diff().dropna() < 0).sum()) > 2 * len(win) // 3:
            continue                                  # рост должен быть устойчивым, а не пилой
        if fe is not None:                            # ВЕТО: резкая переуставка частоты
            fw = fe.reindex(win).dropna()
            if len(fw) >= 2 and (fw.iloc[-1] - fw.iloc[0]) > P['degr_uvch_veto_hz']:
                continue
        ok = True
        # ВЕТО по росту подачи. ПРИОРИТЕТ ФАКТИЧЕСКОГО ЗАМЕРА: если в окне есть хотя бы
        # два замера АГЗУ, судим по ним и виртуальный расходомер игнорируем — он может
        # показывать обратный знак (Ic_370: замер +10%, модель -9%).
        _qv = None
        if q_meas is not None:
            mw = q_meas[(q_meas.index >= win[0]) & (q_meas.index <= win[-1])].dropna()
            if len(mw) >= 2 and mw.iloc[0] > 0:
                _qv = (mw.iloc[-1] - mw.iloc[0]) / mw.iloc[0]
        if _qv is None and qe is not None:
            qw = qe.reindex(win).dropna()
            if len(qw) >= 2 and qw.iloc[0] > 0:
                _qv = (qw.iloc[-1] - qw.iloc[0]) / qw.iloc[0]
        if _qv is not None and _qv > P['degr_q_rise_frac']:
            ok = False
        elif ipe is not None:                         # резерв: рост Рпр при отсутствии Qж
            iw = ipe.reindex(win).dropna()
            ok = len(iw) >= 2 and (iw.iloc[-1] - iw.iloc[0]) > 0
        if ok:
            out.append((win[0], win[-1]))
    out = merge_iv(out, gap=pd.Timedelta(days=P['degr_merge_gap_d']))
    return [(a, b) for a, b in out if (b - a) >= pd.Timedelta(days=W)]


def det_deopt(ctx, nur_iv=()):
    """Неопт. режим (v10; быв. Деоптимизация) — рост Рпр приёма при стабильном дебите (скрытое ограничение).
      Рпр(тек)/ср.Рпр(3дн) - 1 > deopt_pzab_pct  И  |Σ ΔQж за окно| <= deopt_qstable.
      Рпр = telemetry_intake_pressure (ТЕЛЕМЕТРИЯ, без TR)."""
    P = ctx.P
    r = _wd_daily(ctx, IP)   # Рзаб -> Рпр приёма (ТЕЛЕМЕТРИЯ), без TR
    if r is None:
        return []
    pbd, grid = r
    qs = ctx.wd.get(QL); qd = qs.reindex(grid).interpolate(limit=3) if qs is not None else None
    elig = _degr_eligible(ctx, grid, nur_iv)
    W = P['deopt_run_d']; out = []
    for k in range(W, len(grid)):
        win = grid[k - W:k + 1]
        if not bool(elig.reindex(win).all()):
            continue
        pw = pbd.reindex(win)
        if pw.isna().any():
            continue
        base = pw.iloc[:3].mean()
        if base <= 0 or pw.iloc[-1] / base - 1 <= P['deopt_pzab_pct']:   # Рзаб вырос > 3% к началу окна
            continue
        if int((pw.diff().dropna() < 0).sum()) > 1:     # непрерывный рост Рзаб
            continue
        if qd is None:
            continue
        qw = qd.reindex(win)
        if qw.isna().any():
            continue
        if abs(qw.iloc[-1] - qw.iloc[0]) <= P['deopt_qstable']:         # дебит стабилен
            out.append((win[0], win[-1]))
    return merge_iv(out, gap=pd.Timedelta(days=P['deopt_merge_gap_d']))


def det_neopt_cyclic(ctx, periodic_iv=()):
    """Неопт. режим — критерий периодического фонда (v10.4; ужесточён в v10.7).
    Гейт: скважина РАЗМЕЧЕНА категорией «Периодическая работа»; признак проверяется
    ТОЛЬКО внутри этих интервалов (сначала — периодический режим, затем — неоптимальность).
    Признак суток (ИЛИ):
      A. сильное накопление: за цикл остановки рост Рпр > neopt_accum_rise_bar
         (скважина стоит, а приёмное давление активно набирается — потенциал не отбирается);
      B. повторяющиеся длинные простои: >= neopt_idle_n простоев длительностью > neopt_idle_min_d сут
         за скользящие neopt_idle_win_d сут (цикл стоит больше, чем работает).
    Критерий «Рпр > Рзатр + порог» удалён (v10.7c).
    Интервалы отдаёт сырыми; финальная склейка (<2 сут) и фильтр длительности (>5 сут)
    применяются к категории целиком в label_well."""
    P = ctx.P
    periodic_iv = list(periodic_iv or [])
    if not periodic_iv:
        return []                                   # v10.7: без Периодической работы ветка выключена
    ip = pd.to_numeric(ctx.tele.get(IP), errors='coerce').dropna() if IP in ctx.tele else pd.Series(dtype=float)
    if ip.empty:
        return []
    ip = ip[ip > 0]
    days = pd.date_range(ctx.t0.normalize(), ctx.t1.normalize(), freq='D')
    gate = pd.Series(False, index=days)
    for _ps, _pe in periodic_iv:
        gate[(gate.index >= _ps.normalize()) & (gate.index <= _pe.normalize())] = True
    if not gate.any():
        return []
    flag = pd.Series(False, index=days)
    # ── A: слабое накопление Рпр в остановках ──
    for ss, se in ctx.stops:
        seg = ip[(ip.index >= ss) & (ip.index <= se)]
        if len(seg) < P['neopt_accum_min_pts']:
            continue
        rise = float(seg.max() - seg.min())
        if rise > P['neopt_accum_rise_bar']:
            dd = ss.normalize()
            while dd <= se.normalize():
                if dd in flag.index:
                    flag.loc[dd] = True
                dd += pd.Timedelta(days=1)
    # ── B: повторяющиеся длинные простои (v10.7; критерий «Рпр > Рзатр» удалён в v10.7c) ──
    long_idle = [s0 for s0, e0 in ctx.stops if (e0 - s0) > pd.Timedelta(days=P['neopt_idle_min_d'])]
    if long_idle:
        onsets = pd.Series(1, index=pd.DatetimeIndex([t.normalize() for t in long_idle])).groupby(level=0).sum()
        cnt = onsets.reindex(days, fill_value=0).rolling(P['neopt_idle_win_d'], min_periods=1).sum()
        flag |= (cnt >= P['neopt_idle_n'])
    flag &= gate.reindex(days, fill_value=False)
    return _flag_to_iv(flag)


def det_umch(ctx, rptch_iv=None, periodic_iv=None):
    """УМЧ — зеркало УВЧ: устойчивое СНИЖЕНИЕ частоты на новый (более низкий) уровень.
    v10.3 (приоритетная категория: снижение частоты => снижение дебита):
      - быстрая ветка ослаблена до umch_min_run_d=1 сут: снижение МЕДИАНЫ частоты за сутки
        с удержанием нового уровня; база = медиана umch_base_med_d предыдущих рабочих суток (Ic_914 09-11.03.2026);
      - осцилляции РПТЧ НЕ считаются УМЧ: быстрые прогоны внутри интервалов РПТЧ отбрасываются;
      - на периодическом/РПТЧ/циклическом фонде анализируется ОГИБАЮЩАЯ частоты: устойчивое
        снижение верхней огибающей (q=umch_env_q, окно umch_env_win) = УМЧ
        (Ic_370 июл-сен 2025, Ic_805 ноя-дек 2025)."""
    P = ctx.P; out = []
    _rptch = list(rptch_iv or [])
    def _in_rptch(s_, e_):
        # прогон целиком внутри РПТЧ — осцилляция уставок, не УМЧ
        return any(s_ >= ms and e_ <= me for ms, me in _rptch)
    f0 = ctx.wd[F].dropna()
    if len(f0) < 3:
        return out
    stop_days = set()
    for ss, se in ctx.stops:
        dd = ss.normalize()
        while dd <= se.normalize():
            stop_days.add(dd); dd += pd.Timedelta(days=1)
    f = f0[~f0.index.normalize().isin(stop_days)]
    # v10.6: НЕ выходим при пустом f — на периодике 12/12 КАЖДЫЙ день содержит стоп,
    # фильтр стоп-дней опустошает ряд; ветка огибающей работает по рабочей суточной
    # частоте (ctx.wd — стоп-точки уже исключены маской) и должна выполняться всегда.
    fs = f.rolling(P['uvch_smooth_d'], min_periods=1).mean()
    days = list(fs.index); vs = list(fs.values); n = len(days); fraw = f
    i = 0 if len(f) >= 3 else max(n - 1, 0)   # мало межстоповых дней -> быстрая ветка пропускается
    while i < n - 1:
        if vs[i + 1] - vs[i] > -P['uvch_start_step']:        # старт со снижения
            i += 1; continue
        j = i + 1
        while j < n - 1 and (vs[j + 1] - vs[j]) <= P['uvch_end_flat_hz']:
            j += 1
        s_run, e_run = days[i], days[j]
        dur_d = (e_run - s_run).days
        trough = float(fraw[(fraw.index >= s_run) & (fraw.index <= e_run)].min())
        pr = fraw[fraw.index < s_run]
        # база = МЕДИАНА последних рабочих суток (не единичная точка): «снижение частоты в медиане»
        base = float(pr.tail(P['umch_base_med_d']).median()) if len(pr) else float(vs[i])
        net = base - trough
        end_low = trough < P['uvch_min_start_hz']            # снижение до срыва/останова != УМЧ
        # удержание: после спада частота должна ОСТАТЬСЯ на новом низком уровне
        # (провал, вернувшийся к базе, — не УМЧ; Ic_359 27.06/08.07)
        _post = fraw[(fraw.index > e_run) & (fraw.index <= e_run + pd.Timedelta(days=P['uvch_hold_d']))]
        # v10.6: удержание = медиана поста НЕ ВЕРНУЛАСЬ к базе (допуск umch_hold_hz),
        # а не «удержала весь спад»: после реальных УМЧ частота может пилить (Ic_914 март),
        # оставаясь ниже базы. Полный возврат к базе по-прежнему отсекается.
        _held = (len(_post) == 0) or (float(_post.median()) <= base - P['umch_hold_hz'])
        if (dur_d >= P['umch_min_run_d'] and net >= P['umch_drop_hz'] and not end_low and _held
                and not _in_rptch(s_run, e_run)):
            out.append((s_run, e_run + pd.Timedelta(hours=23)))
        i = max(j, i + 1)
    # v10.6: отброс у длинных остановок — ТОЛЬКО для быстрой ветки. Медленная/огибающая
    # ветки на периодическом фонде неизбежно пересекают стопы циклов (Ic_805) — их не режем.
    out_fast = _clear_stops(merge_iv(out), ctx, P['uvch_stop_clear_d'])
    out_env = []
    if getattr(ctx, 'cyclic', False):
        fd = ctx.wd[F].dropna()
        if len(fd) > P['uvch_slow_win']:
            full = fd.reindex(pd.date_range(fd.index.min(), fd.index.max(), freq='D')).interpolate(limit=5)
            sm = full.rolling(7, min_periods=3).mean()
            drop = sm.shift(P['uvch_slow_win']) - sm
            flag = pd.Series((drop >= P['uvch_slow_net']).fillna(False), index=sm.index)
            out_env += [(_s, _e) for _s, _e in merge_iv(_flag_to_iv(flag), gap=pd.Timedelta(days=10)) if (_e - _s).days >= P['uvch_slow_min_d']]
    # v10.3/v10.6: ОГИБАЮЩАЯ частоты на периодическом/РПТЧ/циклическом фонде — осцилляции не УМЧ,
    # но устойчивое снижение верхней огибающей = УМЧ. Два окна: 30 сут (Ic_805 ноя-дек 2025)
    # и 60 сут — медленное многомесячное сползание (Ic_370 июл-сен 2025).
    # База — только РАБОЧИЕ сутки (стоп-дни исключены выше -> нули циклов не тянут огибающую вниз).
    if getattr(ctx, 'cyclic', False) or _rptch or (periodic_iv or []):
        fe = ctx.wd[F].dropna()                      # рабочая суточная частота (стоп-точки вне маски)
        fe = fe[fe > P['stop_freq_hz']]
        if len(fe) > P['umch_env_win']:
            fullw = fe.reindex(pd.date_range(fe.index.min(), fe.index.max(), freq='D')).interpolate(limit=10)
            env = fullw.rolling(7, min_periods=3).quantile(P['umch_env_q'])
            eflag = pd.Series(False, index=env.index)
            for _w, _n in ((P['umch_env_win'], P['umch_env_net']), (P['umch_env_win2'], P['umch_env_net2'])):
                edrop = env.shift(_w) - env
                eflag |= (edrop >= _n).fillna(False)
            # чистое снижение за ЭПИЗОД: колебания огибающей без суммарного спада не склеиваются
            def _env_net_drop(_s, _e):
                seg_ = env[(env.index >= _s) & (env.index <= _e)].dropna()
                if len(seg_) < 2:
                    return False
                h_ = max(1, len(seg_) // 5)
                return float(seg_.iloc[:h_].median() - seg_.iloc[-h_:].median()) >= P['umch_env_net']
            out_env += [(_s, _e) for _s, _e in merge_iv(_flag_to_iv(eflag), gap=pd.Timedelta(days=10))
                        if (_e - _s).days >= P['uvch_slow_min_d'] and _env_net_drop(_s, _e)]
    return merge_iv(out_fast + out_env, gap=pd.Timedelta(days=P['umch_merge_gap_d']))


def det_sppv(ctx):
    P = ctx.P
    bd = ctx.tele.get(BD)
    if bd is None: return []
    bd = bd.dropna()
    daily = bd[bd > 0].resample('1D').sum()
    days = daily[daily > P['sppv_bdpv_min']].index
    if not len(days): return []
    out, st, prev = [], days[0], days[0]
    for d in days[1:]:
        if (d - prev).days > P['sppv_gap_d']:
            out.append((st, prev + pd.Timedelta(hours=23))); st = d
        prev = d
    out.append((st, prev + pd.Timedelta(hours=23)))
    # v9.8.1: продлить каждый СППВ-интервал до ближайших ДЛИТЕЛЬНЫХ остановок
    # (>= 1 сут) — заполнить рабочий участок между такими остановками.
    lstops = [(ss, ee) for ss, ee in ctx.stops if (ee - ss) >= pd.Timedelta(days=1)]
    bounds = [ctx.t0] + [ee for _, ee in lstops] + [ss for ss, _ in lstops] + [ctx.t1]
    ext = []
    for s0, e0 in out:
        lo = max([b for b in bounds if b <= s0], default=ctx.t0)
        hi = min([b for b in bounds if b >= e0], default=ctx.t1)
        ext.append((lo, hi))
    return merge_iv(ext)


def det_water_supply_up(ctx):
    """Увеличение подачи воды (v10.2): суточная подача воды (СППВ/bdpv) выросла более чем
    на water_supply_up_frac (20%) относительно ПРЕДЫДУЩИХ суток. Нули не учитываются
    (сравнение только между сутками с ненулевой подачей)."""
    P = ctx.P
    bd = ctx.tele.get(BD)
    if bd is None:
        return []
    bd = pd.to_numeric(bd, errors='coerce')
    daily = bd[bd > 0].resample('1D').sum()
    daily = daily[daily > 0]
    if len(daily) < 2:
        return []
    idx = list(daily.index); vals = list(daily.values); out = []
    for k in range(1, len(idx)):
        if vals[k - 1] > 0 and (vals[k] - vals[k - 1]) / vals[k - 1] > P['water_supply_up_frac']:
            out.append((idx[k - 1], idx[k]))
    return merge_iv(out, gap=pd.Timedelta(days=P['new_cat_merge_d']))


def _flag_to_iv(flag):
    f = flag.fillna(False)
    out, st, prev = [], None, None
    for d, v in f.items():
        if v:
            if st is None: st = d
            prev = d
        else:
            if st is not None and prev is not None and (d - prev).days > 1:
                out.append((st, prev + pd.Timedelta(hours=23))); st = None
    if st is not None:
        out.append((st, prev + pd.Timedelta(hours=23)))
    return out


# ──────────────────────────────────────────────────────────────────────────
# ══════════════════════════════════════════════════════════════════════════
# Сигнатурный разделитель НУР <-> Снижение Рпл (используется для УВЕРЕННОСТИ
# и совещательной метки; детекторы не меняет).
# ══════════════════════════════════════════════════════════════════════════
def _sig_clip01(x):
    return float(max(0.0, min(1.0, x)))


def sig_features(ctx, start, end):
    """Признаки интервала (0..1, ближе к 1 = больше похоже на НУР)."""
    S = SIG
    ipd = ctx.wd[IP].dropna()
    s_n, e_n = start.normalize(), end.normalize()
    seg = ipd[(ipd.index >= s_n) & (ipd.index <= e_n)]
    seg = seg[seg > 0]
    f = {}
    # 1) близость старта к концу недавней остановки
    gap = np.inf
    for ss, se in ctx.stops:
        if se <= start:
            gap = min(gap, (start - se).total_seconds() / 86400.0)
    f['poststop'] = _sig_clip01(np.exp(-gap / S['tau_gap_d'])) if np.isfinite(gap) else 0.0
    # 2) пик Рпр после пуска выше доостановочного уровня
    pre = ctx.pre_stop_ip_mean(start)
    if len(seg) >= 3:
        head = seg[seg.index <= seg.index[0] + pd.Timedelta(days=S['peak_search'])]
        peak = head.max(); peak_pos = int(np.argmax(head.values))
        rose_above = (pd.notna(pre) and peak >= pre - 1.0)
        f['peak'] = _sig_clip01(0.6 * float(rose_above) + 0.4 * float(peak_pos >= 1))
    else:
        f['peak'] = 0.0
    # 3) скорость падения (быстро=НУР)
    if len(seg) >= 3:
        dur = max((seg.index[-1] - seg.index[0]).days, 1)
        drop = seg.iloc[:3].mean() - seg.iloc[-3:].mean()
        f['speed'] = _sig_clip01((drop / dur) / (2 * S['fast_barday']))
    else:
        f['speed'] = 0.5
    # 4) длительность (короче=НУР)
    dur_d = max((e_n - s_n).days, 1)
    f['dur'] = _sig_clip01(1.0 - (dur_d - S['short_d']) / (3 * S['short_d']))
    # 5) тренд Qж: растёт=НУР, падает=Снижение Рпл
    ql = ctx.wd[QL].dropna() if QL in ctx.wd else pd.Series(dtype=float)
    qseg = ql[(ql.index >= s_n) & (ql.index <= e_n)]; qseg = qseg[qseg > 0]
    if len(qseg) >= 4:
        sl = np.polyfit(np.arange(len(qseg)), qseg.values, 1)[0]
        f['qliq'] = _sig_clip01(0.5 + (sl / (qseg.mean() or 1.0)) * 30.0)
    else:
        f['qliq'] = 0.5
    return f


def sig_score(ctx, start, end):
    S = SIG; f = sig_features(ctx, start, end)
    wmap = dict(poststop=S['w_poststop'], peak=S['w_peak'], speed=S['w_speed'],
               dur=S['w_dur'], qliq=S['w_qliq'])
    wsum = sum(wmap.values())
    nur = sum(wmap[k] * f[k] for k in wmap) / wsum
    sniz = sum(wmap[k] * (1.0 - f[k]) for k in wmap) / wsum
    label = 'НУР' if nur >= sniz else 'Снижение Рпл'
    margin = abs(nur - sniz)
    tier = 'high' if margin >= S['margin_high'] else ('medium' if margin >= S['margin_low'] else 'low')
    return dict(label=label, margin=round(margin, 3), tier=tier,
                nur=round(nur, 3), sniz=round(sniz, 3))


def _degr_freq_influenced(ctx, start, end):
    """True, если рост загрузки в эпизоде Деградации ЭЦН объясним НЕ износом, а
    частотой: (A) частота выросла ВНУТРИ окна эпизода (>= degr_freq_rise_hz), либо
    (B) недавняя смена ЭЦН со ступенью частоты вверх (новый режим, загрузка ещё
    устаканивается). Тогда уверенность понижается до low (Ic_349 окт, Ic_368)."""
    P = ctx.P
    fd = ctx.wd.get(F)
    if fd is None:
        return False
    fd = fd.dropna()
    s_n, e_n = start.normalize(), end.normalize()
    win = fd[(fd.index >= s_n) & (fd.index <= e_n)]
    # (A) рост частоты внутри окна
    if len(win) >= 2 and (win.iloc[-1] - win.iloc[0]) >= P['degr_freq_rise_hz']:
        return True
    # (B) ступень частоты после недавней смены ЭЦН
    brks = [b for b in getattr(ctx, 'esp_breaks', []) if b <= start]
    if brks and len(win):
        last = max(brks)
        if (start - last).days <= P['degr_regime_days']:
            prev = [b for b in ctx.esp_breaks if b < last]
            seg_start = max(prev) if prev else ctx.t0
            seg = fd[(fd.index >= seg_start) & (fd.index < last)]
            if len(seg) and (win.median() - seg.median()) >= P['degr_regime_step_hz']:
                return True
    return False


# ══════════════════════════════════════════════════════════════════════════
# v10.8. Антагонистичные пары: снижение и прирост одной величины не могут
# действовать одновременно. Коллеги ведут раздельные треки для снижений и
# приростов, поэтому одновременная разметка видна как противоречие.
# (сторона A, сторона B, НЕГАТИВНАЯ сторона — последний уровень защиты)
ANTAGONIST_PAIRS = (
    ('Снижение Рпл',       'Рост Рпл',               'Снижение Рпл'),
    ('Снижение Кпрод',     'Рост Кпрод',             'Снижение Кпрод'),
    ('УМЧ',                'УВЧ',                    'УМЧ'),
    ('Рост ГФ',            'Снижение ГФ',            'Рост ГФ'),
    ('Рост обводненности', 'Снижение обводненности', 'Рост обводненности'),
)


def _antag_series(ctx, label):
    """Ключевой сигнал пары и режим сравнения силы тренда.
    Возвращает (series, mode): mode='abs' — нетто в единицах сигнала,
    'rel' — нетто как доля от уровня в начале эпизода."""
    if label in ('Снижение Рпл', 'Рост Рпл'):
        s = ctx.wd[IP].dropna() if IP in ctx.wd else pd.Series(dtype=float)
        return s[s > 0], 'abs'                      # бар
    if label in ('Снижение Кпрод', 'Рост Кпрод'):
        return getattr(ctx, 'kprod', pd.Series(dtype=float)).dropna(), 'rel'
    if label in ('УМЧ', 'УВЧ'):
        s = ctx.wd[F].dropna() if F in ctx.wd else pd.Series(dtype=float)
        return s[s > ctx.P['stop_freq_hz']], 'abs'  # Гц
    if label in ('Рост ГФ', 'Снижение ГФ'):
        s = ctx.wd[GLF].dropna() if GLF in ctx.wd else pd.Series(dtype=float)
        return s[s > 0], 'rel'
    if label in ('Рост обводненности', 'Снижение обводненности'):
        daily = getattr(ctx, 'water_cut_algo_daily', None)
        if daily is None or daily.empty or 'water_cut_algo' not in daily:
            return pd.Series(dtype=float), 'abs'
        return daily['water_cut_algo'].dropna(), 'abs'   # процентные пункты
    return pd.Series(dtype=float), 'abs'


def _antag_strength(ctx, label, iv):
    """|нетто-изменение| сигнала за эпизод. None — сигнала нет."""
    ser, mode = _antag_series(ctx, label)
    if ser is None or len(ser) == 0:
        return None
    seg = ser[(ser.index >= iv[0].normalize()) & (ser.index <= iv[1].normalize())]
    if len(seg) < 2:
        return None
    h = max(1, len(seg) // 5)
    a = float(seg.iloc[:h].median()); b = float(seg.iloc[-h:].median())
    if mode == 'rel':
        return abs(b - a) / a if a > 0 else None
    return abs(b - a)


def _antag_winner(ctx, A, B, a_iv, b_iv, neg):
    """Кто выигрывает конфликт: 'A' или 'B'. Три уровня — длительность,
    уверенность/сила, приоритет негативного фактора. Возвращает (сторона, причина)."""
    P = ctx.P
    da = (a_iv[1] - a_iv[0]).days + 1
    db = (b_iv[1] - b_iv[0]).days + 1
    # ── уровень 1: более длительный тренд ──
    lo = max(1, min(da, db))
    if max(da, db) >= P['antag_dur_ratio'] * lo and abs(da - db) >= P['antag_dur_min_gap_d']:
        return ('A' if da > db else 'B'), 'длительность'
    # ── уровень 2: более уверенный, затем более сильный тренд ──
    try:
        sa = float(score_episode(ctx, A, a_iv[0], a_iv[1]).get('score', 0.0))
        sb = float(score_episode(ctx, B, b_iv[0], b_iv[1]).get('score', 0.0))
    except Exception:
        sa = sb = 0.0
    if abs(sa - sb) >= P['antag_score_margin']:
        return ('A' if sa > sb else 'B'), 'уверенность'
    ga = _antag_strength(ctx, A, a_iv); gb = _antag_strength(ctx, B, b_iv)
    if ga is not None and gb is not None:
        lo_g = max(1e-9, min(ga, gb))
        if max(ga, gb) >= P['antag_strength_ratio'] * lo_g:
            return ('A' if ga > gb else 'B'), 'сила тренда'
    # ── уровень 3: приоритет негативному фактору ──
    return ('A' if neg == A else 'B'), 'негативный фактор'


def resolve_antagonists(res, ctx, log=None):
    """Убирает одновременную разметку снижения и прироста одной величины.
    Проигравший теряет зону пересечения; если она покрывает больше
    antag_drop_frac эпизода или остаток короче antag_min_keep_d — снимается целиком."""
    P = ctx.P
    min_keep = pd.Timedelta(days=P['antag_min_keep_d'])
    for A, B, neg in ANTAGONIST_PAIRS:
        ivA = merge_iv(list(res.get(A, []) or []))
        ivB = merge_iv(list(res.get(B, []) or []))
        if not ivA or not ivB:
            continue
        for _ in range(200):                      # страховка от зацикливания
            hit = None
            for a in ivA:
                for b in ivB:
                    if min(a[1], b[1]) > max(a[0], b[0]):
                        hit = (a, b); break
                if hit: break
            if hit is None:
                break
            a_iv, b_iv = hit
            side, why = _antag_winner(ctx, A, B, a_iv, b_iv, neg)
            loser_lbl, loser_iv = (B, b_iv) if side == 'A' else (A, a_iv)
            win_iv = a_iv if side == 'A' else b_iv
            ov = (max(a_iv[0], b_iv[0]), min(a_iv[1], b_iv[1]))
            ov_len = ov[1] - ov[0]
            loser_len = loser_iv[1] - loser_iv[0]
            if loser_len <= pd.Timedelta(0) or ov_len >= P['antag_drop_frac'] * loser_len:
                pieces = []                        # пересечение съело эпизод — снимаем целиком
            else:
                pieces = [(x, y) for x, y in subtract_iv([loser_iv], [win_iv])
                          if (y - x) >= min_keep]
            if loser_lbl == A:
                ivA = merge_iv([iv for iv in ivA if iv != loser_iv] + pieces)
            else:
                ivB = merge_iv([iv for iv in ivB if iv != loser_iv] + pieces)
            if log is not None:
                log.append({'pair': (A, B), 'winner': A if side == 'A' else B,
                            'loser': loser_lbl, 'reason': why,
                            'overlap': (ov[0], ov[1]), 'kept': pieces})
        res[A] = ivA
        res[B] = ivB
    return res


def score_episode(ctx, ep_type, start, end):
    """
    Сигнальная модель confidence.

    Правило уже сработало — значит базовые условия (gate, drop, slope) пройдены.
    score_episode проверяет ТОЛЬКО дополнительные подтверждающие сигналы:
      • «shape» — чистота паттерна Рпр/частоты (монотонность, отсутствие скачков, тренд)
      • «ql_*»  — подтверждение через дебит жидкости (Qж)

    Уровни:
      high   — shape-сигналы не противоречат И Qж подтверждает
      medium — shape ОК, но Qж недоступен / нейтрален
      low    — хотя бы один shape-сигнал ПРОТИВОРЕЧИТ (подозрение на артефакт)

    Возвращает:
      score  : float 0–1
      tier   : 'high' | 'medium' | 'low'
      signals: dict[str, bool | None]  (None = нет данных)
    """
    P = ctx.P
    s_n, e_n = start.normalize(), end.normalize()

    def _w(col):
        if col not in ctx.wd: return pd.Series(dtype=float)
        return ctx.wd[col][(ctx.wd.index >= s_n) & (ctx.wd.index <= e_n)].dropna()

    def _fw():
        fw = ctx.tele[F][ctx.wmask.values]
        return fw[(fw.index >= start) & (fw.index <= end)].resample('1D').mean().dropna()

    def _lin_slope(s):
        s = s.dropna()
        if len(s) < 3: return None
        return float(np.polyfit(np.arange(len(s)), s.values, 1)[0])

    signals = {}   # signal_name → bool | None

    # ─── НУР ─────────────────────────────────────────────────────────────
    if ep_type == 'НУР':
        ip = _w(IP)
        # shape: Рпр снижается плавно (не резкими скачками)
        if len(ip) >= 3:
            diffs = [ip.iloc[k] - ip.iloc[k+1] for k in range(len(ip)-1)]
            mono = sum(1 for d in diffs if d >= -P['nur_end_slope']) / len(diffs)
            # smooth = монотонная доля высокая, но не обязательно 100%
            signals['ip_smooth']   = mono >= 0.55   # смягчён vs nur_monotone_ratio
            total_drop = ip.iloc[0] - ip.iloc[-1]
            max_step = ip.diff().abs().dropna().max() if len(ip) > 1 else 0
            # step_ok = нет единого скачка съедающего >70% снижения
            signals['ip_no_spike'] = (max_step / total_drop <= 0.70) if total_drop > 0.5 else True
        else:
            signals['ip_smooth']   = None
            signals['ip_no_spike'] = None
        # Qж: дебит растёт при восстановлении скважины после останова
        ql = _w(QL)
        slope = _lin_slope(ql)
        signals['ql_recovers'] = None if slope is None else slope > 0

    # ─── РПТЧ ────────────────────────────────────────────────────────────
    elif ep_type == 'РПТЧ':
        fd = _fw()
        if len(fd) < 5:
            signals['freq_data'] = None
        else:
            # round_hz: хотя бы половина суток — целые (или полуцелые) уставки Гц
            remainder = fd.apply(lambda x: min(x % 1, 1 - x % 1))
            signals['round_hz'] = (remainder < P['rptch_round_tol']).mean() >= 0.40  # смягчён
            # Qж осциллирует вместе с частотой (CV Qж > 3%)
        ql = _w(QL)
        if len(ql) >= 5 and ql.mean() > 0:
            signals['ql_oscillates'] = ql.std() / ql.mean() > 0.03
        else:
            signals['ql_oscillates'] = None

    # ─── УВЧ ─────────────────────────────────────────────────────────────
    elif ep_type == 'УВЧ':
        f = _w(F)
        if len(f) >= 2:
            slope = _lin_slope(f)
            # shape: устойчивый рост (не разовый скачок вниз-вверх)
            signals['freq_trend_up'] = None if slope is None else slope > 0
            net = f.iloc[-1] - f.iloc[0]
            signals['freq_net_ok']   = net >= P['uvch_rise_hz']
        else:
            signals['freq_trend_up'] = None
            signals['freq_net_ok']   = None
        # Qж растёт — производство увеличивается при росте частоты
        ql = _w(QL)
        slope_ql = _lin_slope(ql)
        signals['ql_rises'] = None if slope_ql is None else slope_ql > 0

    # ─── Снижение Рпл ────────────────────────────────────────────────────
    elif ep_type == 'Снижение Рпл':
        ip = _w(IP)
        f  = _w(F)
        # shape: частота стабильна (не снижение нагрузки оператором)
        if len(f) >= 2:
            signals['freq_stable'] = abs(f.iloc[-1] - f.iloc[0]) <= P['snizh_max_dfreq']
        else:
            signals['freq_stable'] = None
        # not_step: падение распределено во времени, не единый скачок
        if len(ip) >= P['snizh_step_min_pts']:
            total_drop = ip.iloc[0] - ip.iloc[-1]
            if total_drop > 0:
                max_step = ip.diff().abs().dropna().max()
                signals['ip_gradual'] = max_step / total_drop <= P['snizh_step_ratio']
            else:
                signals['ip_gradual'] = None
        else:
            signals['ip_gradual'] = None
        # Qж тоже снижается — главное подтверждение истощения пласта
        ql = _w(QL)
        if len(ql) >= 5 and ql.mean() > 0:
            ql_drop_frac = (ql.iloc[:max(1,len(ql)//3)].mean() -
                            ql.iloc[-max(1,len(ql)//3):].mean()) / ql.mean()
            signals['ql_declining'] = ql_drop_frac > 0.04
        else:
            signals['ql_declining'] = None

    # ─── ГДИ ─────────────────────────────────────────────────────────────
    elif ep_type == 'ГДИ':
        ip_stop = ctx.tele[IP][(ctx.tele.index >= start) & (ctx.tele.index <= end)].dropna()
        # shape: Рпр растёт во время остановки (КВД)
        if len(ip_stop) >= 2:
            signals['ip_kvd_rising'] = ip_stop.iloc[-1] > ip_stop.iloc[0]
        else:
            signals['ip_kvd_rising'] = None
        # Qж = 0 во время остановки
        ql_raw = ctx.tele.get(QL)
        if ql_raw is not None:
            ql_seg = ql_raw[(ql_raw.index >= start) & (ql_raw.index <= end)].dropna()
            signals['ql_zero'] = len(ql_seg) == 0 or ql_seg.mean() < 0.5
        else:
            signals['ql_zero'] = None

    # ─── Периодическая работа ────────────────────────────────────────────
    elif ep_type == 'Периодическая работа':
        stop_times = [ss for ss, _ in ctx.stops if start <= ss <= end]
        if len(stop_times) >= 3:
            ivls = [(stop_times[k+1]-stop_times[k]).total_seconds()/3600
                    for k in range(len(stop_times)-1)]
            mean_i = float(np.mean(ivls))
            cv = float(np.std(ivls)) / mean_i if mean_i > 0 else 1
            signals['rhythm_ok'] = cv <= 0.6   # интервалы относительно регулярны
        else:
            signals['rhythm_ok'] = None
        ql = _w(QL)
        if len(ql) >= 7 and ql.mean() > 0:
            signals['ql_cyclic'] = ql.std() / ql.mean() > 0.06
        else:
            signals['ql_cyclic'] = None

    # ─── Снижение Кпрод ──────────────────────────────────────────────────
    elif ep_type == 'Снижение Кпрод':
        # высокая уверенность ТОЛЬКО при подтверждении падением дебита жидкости
        # (Ic_367 «шум Рпр» без падения Qж -> medium; Ic_914 реальный спад -> high)
        ql = _w(QL)
        if len(ql) >= 4 and ql.mean() > 0:
            t = max(1, len(ql) // 3)
            drop = (ql.iloc[:t].mean() - ql.iloc[-t:].mean()) / ql.mean()
            signals['ql_confirms'] = drop > 0.05
        else:
            signals['ql_confirms'] = None
        # ОПЗ — ПОДТВЕРЖДАЮЩИЙ фактор (не определяющий): эпизод в кластере ОПЗ -> выше
        # уверенность; отсутствие ОПЗ не понижает (подтверждающая группа ql_*).
        try:
            _opzc = det_opz_clusters(ctx)
            signals['ql_opz'] = (bool(in_any(start, _opzc) or in_any(end, _opzc)) if _opzc else None)
        except Exception:
            signals['ql_opz'] = None

    elif ep_type == 'Деградация ЭЦН':
        # high — если есть замеры Qж и он падает в эпизоде; medium — fallback по Рпр
        s_n, e_n = start.normalize(), end.normalize()
        ql = ctx.wd.get(QL); ql = ql[(ql.index >= s_n) & (ql.index <= e_n)].dropna() if ql is not None else pd.Series(dtype=float)
        if len(ql) >= 3:
            tier = 'high' if (ql.iloc[-1] - ql.iloc[0]) <= 0 else 'medium'
        else:
            tier = 'medium'   # нет дебита -> по Рпр, ниже уверенность
        _finfl = _degr_freq_influenced(ctx, start, end)
        if _finfl:
            tier = 'low'   # v10.3: рост загрузки объясним частотой/сменой режима, не износом
        return dict(score=(0.8 if tier == 'high' else 0.3 if tier == 'low' else 0.55),
                    tier=tier, signals={'ql_pts': int(len(ql)), 'freq_influenced': bool(_finfl)})
    elif ep_type == 'Неопт. режим':
        # v10.9: было score=0.6/medium безусловно — «средняя уверенность» выдавалась
        # даже когда цифры на интервале противоречат заявленному росту Рпр.
        _tags = _neopt_tags(ctx, start, end)
        _a, _b = _xfl(_xseg(ctx.wd.get(IP) if hasattr(ctx, 'wd') else None, start, end))
        _rise = bool(_a is not None and _a > 0 and _b > _a)
        _sig = {'src': sorted(_tags), 'ip_rise_confirmed': _rise}
        if 'deopt' in _tags and not _rise:
            return dict(score=0.3, tier='low', signals=_sig)   # рост Рпр на интервале не подтверждён
        if 'deopt' in _tags and 'cyclic' in _tags and _rise:
            return dict(score=0.75, tier='high', signals=_sig)
        return dict(score=0.6, tier='medium', signals=_sig)
    elif ep_type == 'Увеличение подачи воды':
        return dict(score=0.7, tier='medium', signals={})
    elif ep_type in ('Рост обводненности', 'Снижение обводненности'):
        return dict(score=0.6, tier='medium', signals={})
    elif ep_type == 'ВГФ':
        return _score_vgf(ctx, start, end)
    elif ep_type in ('Рост ГФ', 'Снижение ГФ'):
        return _score_gf_trend(ctx, start, end)

    else:
        return dict(score=1.0, tier='high', signals={})

    # ─── Tiering ─────────────────────────────────────────────────────────
    # Философия: правило уже сработало. Ищем противоречия (→ LOW)
    # или подтверждение Qж (→ HIGH).
    ql_keys   = {k for k in signals if k.startswith('ql_')}
    main_keys = {k for k in signals if k not in ql_keys}

    # np.bool_ совместимость: используем == вместо is
    def _is_false(v): return v is not None and v == False
    def _is_true(v):  return v is not None and v == True

    main_false   = sum(1 for k in main_keys if _is_false(signals[k]))
    ql_confirmed = any(_is_true(signals.get(k)) for k in ql_keys)

    if main_false > 0:
        tier = 'low'      # хотя бы один shape-сигнал ПРОТИВОРЕЧИТ
    elif ql_confirmed:
        tier = 'high'     # shape ОК + Qж подтверждает
    else:
        tier = 'medium'   # shape ОК, Qж недоступен или нейтрален

    def _b(v): return 1.0 if _is_true(v) else (0.0 if _is_false(v) else 0.5)
    score = round(float(np.mean([_b(v) for v in signals.values()])) if signals else 0.5, 3)
    return dict(score=score, tier=tier, signals={k: signals[k] for k in sorted(signals)})


# ─────────────────────────────────────────────────────────────────────────
def det_opz_clusters(ctx):
    """Кластеры ОПЗ (НЕзависимый событийный сигнал «скважину повторно обрабатывают»): >= cf_min_opz ОПЗ в окне
    cf_win_d суток. Кластер обработок = «остановка-обработка-запуск» повторяется
    (экспертный признак осложнённого фонда). Одиночные/редкие ОПЗ (рутинные) не в счёт.
    Калибровка: точно ловит ручные CF (Ic_805/Ic_914/Vt_4401)."""
    P = ctx.P
    if 'opz_ids' not in ctx.tele:
        return []
    sub = ctx.tele['opz_ids'].dropna()
    seen = {}
    for t, o in sub.items():
        for pid in str(o).replace('|', ',').split(','):
            pid = pid.strip()
            if pid and pid != 'nan':
                seen.setdefault(pid, t)
    dts = sorted(set(pd.Timestamp(x).normalize() for x in seen.values()))
    if len(dts) < P['cf_min_opz']:
        return []
    win = pd.Timedelta(days=P['cf_win_d']); ext = pd.Timedelta(days=P['cf_ext_d'])
    mg = pd.Timedelta(days=P['cf_merge_gap_d'])
    out = []
    for t in dts:
        cnt = sum(1 for x in dts if (t - win) <= x <= t)
        if cnt >= P['cf_min_opz']:
            s_, e_ = t - ext, t + ext
            if out and s_ <= out[-1][1] + mg:   # объединяем кластеры через разрывы
                out[-1] = (out[-1][0], max(out[-1][1], e_))
            else:
                out.append((s_, e_))
    # ограничить рамками телеметрии
    out = [(max(s_, ctx.t0), min(e_, ctx.t1)) for s_, e_ in out]
    return merge_iv(out)


def det_complicated_fund(ctx, kprod_iv):
    """Осложнённый фонд ВЫВОДИТСЯ из Кпрод: период, где Снижение Кпрод случается
    ПОВТОРНО (>= cf_min_kprod эпизодов в скользящем окне cf_kprod_win сут).
    Соответствует словам эксперта: «Кпрод снижался несколько раз за месяц»."""
    P = ctx.P
    iv = list(kprod_iv)
    if len(iv) < P['cf_min_kprod']:
        return []
    starts = pd.DatetimeIndex(sorted(s for s, _ in iv))
    win = pd.Timedelta(days=P['cf_kprod_win']); ext = pd.Timedelta(days=P['cf_ext_d'])
    out = []
    for t in starts:
        cnt = sum(1 for x in starts if (t - win) <= x <= t)
        if cnt >= P['cf_min_kprod']:
            # охватить кластер Кпрод-эпизодов
            grp = [(s_, e_) for s_, e_ in iv if (t - win) <= s_ <= t]
            s0 = min(s_ for s_, _ in grp) - ext; e0 = max(e_ for _, e_ in grp) + ext
            if out and s0 <= out[-1][1]:
                out[-1] = (out[-1][0], max(out[-1][1], e0))
            else:
                out.append((s0, e0))
    return merge_iv([(max(s_, ctx.t0), min(e_, ctx.t1)) for s_, e_ in out])


def _glf_daily(ctx, win=7):
    """Сглаженный ГЖФ: обрезка нижних/верхних 10% (p10..p90), дневная медиана,
    НЕДЕЛЬНОЕ среднее (rolling-7 mean). Возвращает (series, n_сырых_точек)."""
    s = ctx.tele.get(GLF)
    if s is None:
        return pd.Series(dtype=float), 0
    s = pd.to_numeric(s, errors='coerce').dropna(); s = s[s > 0]
    npts = len(s)
    if npts < 5:
        return pd.Series(dtype=float), npts
    lo, hi = s.quantile(0.10), s.quantile(0.90)
    s = s[(s >= lo) & (s <= hi)]
    return s.resample('1D').median().rolling(win, min_periods=3).mean(), npts


def _bridge_runs(flag, bridge, min_d):
    out = []; st = None; last = None
    for d, v in flag.items():
        if v:
            if st is None: st = d
            last = d
        elif st is not None and (d - last).days > bridge:
            out.append((st, last)); st = None
    if st is not None:
        out.append((st, last))
    return [(s, e + pd.Timedelta(hours=23)) for s, e in out if (e - s).days >= min_d]


def _glf_trend_runs(g, sign, frac, min_d, tol_frac=0.15):
    g = g.dropna()
    if len(g) < 3:
        return []
    vals = list(g.values); idx = list(g.index); out = []; i = 0
    while i < len(vals) - 1:
        j = i
        while j < len(vals) - 1:
            base = vals[i] if vals[i] > 0 else 1.0
            if sign * (vals[j + 1] - vals[j]) / base >= -tol_frac:
                j += 1
            else:
                break
        if j > i and vals[i] > 0:
            net = sign * (vals[j] - vals[i]) / vals[i]
            if net >= frac and (idx[j] - idx[i]).days >= min_d:
                out.append((idx[i], idx[j] + pd.Timedelta(hours=23)))
        i = max(j, i + 1)
    return merge_iv(out)


# =====================================================================================
# ВЫСОКИЙ ГЖФ (ВГФ) — физический расчёт v11
# =====================================================================================
# Полная замена прежнего эвристического правила (порог недельного среднего ГЖФ).
# Логика перенесена из эталонной спецификации high_glf_detector.py и адаптирована
# к архитектуре проекта: расчёт живёт в ctx, пороги — в PARAMS, PVT загружается один
# раз на прогон и передаётся через set_pvt_curves(), путь к файлу не хардкодится.
#
# ЕДИНИЦЫ: поле telemetry_gas_liquid_factor трактуется как ГАЗОВЫЙ ФАКТОР в
# стандартных м3 газа на ТОННУ товарной нефти, несмотря на название поля.
# Трактовка зафиксирована здесь намеренно; менять её молча нельзя.
#
# ПРИВЯЗКА PVT: спецификация задаёт приоритет intersection_id -> объект -> префикс.
# В экспорте телеметрии колонки intersection_id нет, поэтому фактически работает
# только префикс скважины (Az нормализуется в AZ). Это задокументированное
# ограничение, а не упрощение по выбору.

PVT_CURVES = {}          # {'Ic': DataFrame(pressure_bar, Rs, Bg, Bo, rho_o_p, rho_g_p)}

PVT_COLUMNS = {
    'pressure':    'Давление, бар',
    'oil_density': 'Плотность нефти при давлении, кг/м3',
    'rs':          'Газосодержание, м3/м3',
    'bg':          'Объемный коэффициент газа, безр',
    'gas_density': 'Плотность газа при давлении, кг/м3',
    'bo':          'Объемный коэффициент нефти, безр',
}


def _pvt_key(value):
    prefix = str(value).strip()
    return 'AZ' if prefix == 'Az' else prefix


def load_pvt_curves(pvt_path, sheet_name=None):
    """PVT-кривые по объектам из книги Excel. Дубликаты по давлению сводятся медианой."""
    from openpyxl import load_workbook
    wb = load_workbook(pvt_path, read_only=True, data_only=True)
    ws = wb[sheet_name] if sheet_name else wb[wb.sheetnames[0]]
    rows = list(ws.iter_rows(values_only=True))
    if not rows:
        raise ValueError(f'PVT: пустая книга {pvt_path}')
    pvt = pd.DataFrame(rows[1:], columns=rows[0])
    missing = sorted({'Field short', *PVT_COLUMNS.values()} - set(pvt.columns))
    if missing:
        raise ValueError(f'PVT: нет обязательных колонок: {missing}')
    for col in PVT_COLUMNS.values():
        pvt[col] = pd.to_numeric(pvt[col], errors='coerce')
    pvt['pvt_key'] = pvt['Field short'].map(_pvt_key)

    curves = {}
    for key, grp in pvt[pvt['pvt_key'].ne('')].groupby('pvt_key', sort=True):
        curve = (grp.groupby(PVT_COLUMNS['pressure'], as_index=False)
                    .agg(Rs=(PVT_COLUMNS['rs'], 'median'), Bg=(PVT_COLUMNS['bg'], 'median'),
                         Bo=(PVT_COLUMNS['bo'], 'median'),
                         rho_o_p=(PVT_COLUMNS['oil_density'], 'median'),
                         rho_g_p=(PVT_COLUMNS['gas_density'], 'median'))
                    .rename(columns={PVT_COLUMNS['pressure']: 'pressure_bar'})
                    .sort_values('pressure_bar'))
        curve = curve.replace([np.inf, -np.inf], np.nan).dropna()
        if len(curve) >= 2:
            curves[str(key)] = curve.reset_index(drop=True)
    if not curves:
        raise ValueError('PVT: пригодных кривых не найдено')
    return curves


def set_pvt_curves(curves):
    global PVT_CURVES
    PVT_CURVES = curves or {}


def _q80_lower(s):
    """P80 ВНУТРИ скважино-суток с выбором нижнего наблюдаемого значения.
    Именно 'lower', а не линейная интерполяция: при 3-5 замерах в сутки линейный
    P80 утащил бы наверх часть единичного экстремума. Глобальный P80 по фонду
    применять нельзя — он срежет реальные газовые режимы."""
    s = pd.to_numeric(s, errors='coerce').replace([np.inf, -np.inf], np.nan).dropna()
    s = s[s >= 0]
    return float(s.quantile(0.80, interpolation='lower')) if len(s) else np.nan


def _med_pos(s):
    s = pd.to_numeric(s, errors='coerce').replace([np.inf, -np.inf], np.nan).dropna()
    s = s[s > 0]
    return float(s.median()) if len(s) else np.nan


def _med_wc(s):
    s = pd.to_numeric(s, errors='coerce').replace([np.inf, -np.inf], np.nan).dropna()
    s = s[s.between(0, 100)]
    return float(s.median()) if len(s) else np.nan


def _weighted_median(values, weights):
    v = np.asarray(list(values), dtype=float); w = np.asarray(list(weights), dtype=float)
    m = np.isfinite(v) & np.isfinite(w) & (w > 0)
    if not m.any():
        return np.nan
    v, w = v[m], w[m]
    o = np.argsort(v, kind='mergesort'); v, w = v[o], w[o]
    return float(v[np.searchsorted(np.cumsum(w), w.sum() / 2.0, side='left')])


def hglf_daily(ctx):
    """Суточный ряд для расчёта ВГФ: одна строка на КАЖДЫЕ календарные сутки,
    включая остановки и пропуски — иначе окно в 5 строк перестанет означать
    5 календарных суток."""
    P = ctx.P
    t = ctx.tele
    if GLF not in t or F not in t:
        return pd.DataFrame()
    d = pd.DataFrame(index=t.index)
    for c in (F, IP, QL, GLF, WC):
        d[c] = pd.to_numeric(t[c], errors='coerce') if c in t else np.nan
    d['water_cut_algo'] = pd.to_numeric(t['water_cut_algo'], errors='coerce') if 'water_cut_algo' in t else np.nan
    d['date'] = d.index.normalize()
    g = d.groupby('date')

    hz = P['hglf_stop_frequency_hz']
    daily = pd.DataFrame({
        'work_fraction': g[F].apply(lambda s: float((s.dropna() >= hz).mean()) if s.notna().any() else np.nan),
        'frequency_running_median': g[F].apply(lambda s: float(s[s >= hz].median()) if (s >= hz).any() else np.nan),
        'gf_measured_m3t': g[GLF].apply(_q80_lower),
        'gf_measurement_count': g[GLF].count(),
        'qliq_m3d': g[QL].apply(_med_pos),
        'p_intake_bar': g[IP].apply(_med_pos),
        'water_cut_telemetry_pct': g[WC].apply(_med_wc),
        'water_cut_pred_pct': g['water_cut_algo'].apply(_med_wc),
    })
    grid = pd.date_range(daily.index.min(), daily.index.max(), freq='D')
    daily = daily.reindex(grid)
    daily.index.name = 'date'
    daily['gf_measurement_day'] = daily['gf_measurement_count'].fillna(0).gt(0)
    daily['work_fraction'] = daily['work_fraction'].clip(0, 1)
    # обводнённость: сначала прогноз, телеметрия — резерв
    daily['water_cut_pct'] = daily['water_cut_pred_pct'].where(
        daily['water_cut_pred_pct'].between(0, 100), daily['water_cut_telemetry_pct'])
    daily.loc[~daily['water_cut_pct'].between(0, 100), 'water_cut_pct'] = np.nan
    # стабильность режима: размах рабочей частоты в окне огибающей. При стабильном режиме
    # замер ГФ дольше остаётся представительным, поэтому ниже он получает больший вес.
    w = int(P['hglf_env_win_d'])
    f = daily['frequency_running_median']
    rng = (f.rolling(w, min_periods=2, center=True).max()
           - f.rolling(w, min_periods=2, center=True).min())
    daily['freq_range_env'] = rng
    daily['regime_stable'] = rng.le(P['hglf_regime_stable_hz']).fillna(False)
    return daily


def hglf_carry_gf(daily, P):
    """Перенос последнего ГФ максимум на hglf_max_gf_age_days суток.
    Перенесённое значение поддерживает непрерывность расчёта, но НЕ является
    новым подтверждающим замером (см. hglf_confirm)."""
    m = daily['gf_measured_m3t'].where(daily['gf_measured_m3t'].ge(0))
    last_date = pd.Series(daily.index, index=daily.index).where(m.notna()).ffill()
    age = (pd.Series(daily.index, index=daily.index) - last_date).dt.days.astype(float)
    allowed = np.where(daily.get('regime_stable', pd.Series(False, index=daily.index)).to_numpy(dtype=bool),
                       P['hglf_max_gf_age_stable_d'], P['hglf_max_gf_age_days'])
    used = m.ffill().where((age >= 0) & (age <= allowed))
    daily['gf_age_allowed_d'] = allowed
    daily['gf_used_m3t'] = used
    daily['gf_age_days'] = age
    return daily


def hglf_baseline(daily, P):
    """База Qж — взвешенная медиана за предыдущие 30 ЭКВИВАЛЕНТНЫХ РАБОЧИХ суток.
    Полная остановка даёт 0 рабочих суток и сама удлиняет календарное окно назад;
    день с работой 50% даёт 0.5 рабочего дня. Текущий день в свою базу не входит."""
    q = daily['qliq_m3d'].to_numpy(dtype=float)
    wf = daily['work_fraction'].fillna(0).clip(0, 1).to_numpy(dtype=float)
    n = len(daily)
    base = np.full(n, np.nan); cov = np.zeros(n)
    need = float(P['hglf_baseline_operating_days'])
    for i in range(n):
        remaining = need; vals = []; wts = []; j = i - 1
        while j >= 0 and remaining > 1e-12:
            if np.isfinite(q[j]) and q[j] > 0 and wf[j] > 0:
                take = min(float(wf[j]), remaining)
                vals.append(float(q[j])); wts.append(take); remaining -= take
            j -= 1
        cov[i] = need - remaining
        if cov[i] >= P['hglf_baseline_min_operating_days']:
            base[i] = _weighted_median(vals, wts)
    daily['qliq_baseline_median_30opd'] = base
    daily['qliq_baseline_operating_days'] = cov
    daily['qliq_required_m3d'] = np.maximum(P['hglf_min_qliq_m3d'],
                                            P['hglf_min_qliq_share_of_baseline'] * base)
    daily['qliq_valid'] = (daily['qliq_baseline_median_30opd'].notna()
                           & daily['qliq_m3d'].gt(P['hglf_min_qliq_m3d'])
                           & daily['qliq_m3d'].ge(daily['qliq_required_m3d']))
    return daily


def hglf_pvt(daily, well_id):
    """Линейная интерполяция PVT по текущему Рпр. За диапазон кривой НЕ
    экстраполируем — такой день невалиден."""
    key = _pvt_key(str(well_id).split('_')[0])
    for c in ('Rs', 'Bg', 'Bo', 'rho_o_p', 'rho_g_p'):
        daily[c] = np.nan
    daily['pvt_valid'] = False
    daily['pvt_key'] = key
    curve = PVT_CURVES.get(key)
    if curve is None:
        return daily
    p = daily['p_intake_bar'].to_numpy(dtype=float)
    x = curve['pressure_bar'].to_numpy(dtype=float)
    in_range = np.isfinite(p) & (p >= np.nanmin(x)) & (p <= np.nanmax(x))
    ok = in_range.copy()
    for c in ('Rs', 'Bg', 'Bo', 'rho_o_p', 'rho_g_p'):
        y = curve[c].to_numpy(dtype=float)
        v = np.full(len(daily), np.nan)
        v[in_range] = np.interp(p[in_range], x, y)
        ok &= np.isfinite(v)
        daily[c] = v
    daily['pvt_valid'] = ok
    return daily


def hglf_physics(daily, P):
    """Переход ГФ -> свободный газ на приёме -> GVF.
        rho_g_std = rho_g(P) * Bg
        rho_o_std = rho_o(P) * Bo - Rs * rho_g_std      (баланс массы живой нефти)
        R_total   = ГФ[м3/т] * rho_o_std / 1000
        R_free    = max(R_total - Rs - допуск, 0)
        GVF       = газ / (газ + жидкость) на приёме
    Используется плотность нефти ПРИ ТЕКУЩЕМ ДАВЛЕНИИ, а не одно значение при
    низком давлении."""
    d = daily
    d['oil_fraction'] = 1.0 - d['water_cut_pct'] / 100.0
    d['rho_g_standard_kgm3'] = d['rho_g_p'] * d['Bg']
    d['rho_o_standard_kgm3'] = d['rho_o_p'] * d['Bo'] - d['Rs'] * d['rho_g_standard_kgm3']
    # ЕДИНИЦЫ (v12.2): telemetry_gas_liquid_factor — газожидкостный фактор, т.е. ст. м3 газа
    # на м3 ЖИДКОСТИ, как и называется поле. Прежняя трактовка «на тонну товарной нефти»
    # (R = ГЖФ * rho_o_std / 1000) занижала газ на обводнённых скважинах в 1/(1-обв.) раз и
    # давала жёсткий ноль там, где эксперт видит ВГФ: Ic_368 (83% воды), Ic_370, Ic_914,
    # Vt_4401. Пересчёт на м3 нефти — делением на долю нефти.
    d['R_total_m3m3_oil'] = d['gf_used_m3t'] / d['oil_fraction'].clip(lower=0.02)
    d['R_tolerance_m3m3'] = np.maximum(P['hglf_rs_tolerance_abs_m3m3'],
                                       P['hglf_rs_tolerance_rel'] * d['R_total_m3m3_oil'])
    d['R_free_m3m3_oil'] = (d['R_total_m3m3_oil'] - d['Rs'] - d['R_tolerance_m3m3']).clip(lower=0)
    d['glr_surface_m3m3_liq'] = d['R_total_m3m3_oil'] * d['oil_fraction']
    d['gas_intake'] = d['R_free_m3m3_oil'] * d['oil_fraction'] * d['Bg']
    d['liquid_intake'] = d['oil_fraction'] * d['Bo'] + (1.0 - d['oil_fraction']) * P['hglf_water_fvf']
    d['glr_free_intake_m3m3'] = d['gas_intake'] / d['liquid_intake']
    d['gvf_intake'] = d['gas_intake'] / (d['gas_intake'] + d['liquid_intake'])
    d['physical_inputs_valid'] = (
        d['pvt_valid'] & d['gf_used_m3t'].ge(0)
        & (d['gf_age_days'] >= 0) & (d['gf_age_days'] <= d['gf_age_allowed_d'])
        & d['water_cut_pct'].between(0, 100)
        & d['rho_o_standard_kgm3'].between(650, 1000)
        & d['rho_g_standard_kgm3'].between(0.3, 2.0)
        & d['gvf_intake'].between(0, 1))
    return d


def hglf_confirm(daily, P):
    """Подтверждение ОГИБАЮЩЕЙ и плотностью замеров (v12.2).

    Прежнее правило было жёстким счётчиком: 4 календарных дня из 5 обязаны нести
    фактический замер, и 70% из них — быть высокими. На реальном фонде 47% суток внутри
    экспертных эпизодов ВГФ вообще не имеют замера, поэтому счётчик резал половину.

    Теперь решает не счёт дней, а УРОВЕНЬ ОГИБАЮЩЕЙ: скользящая медиана GVF по зачтённым
    суткам в окне hglf_env_win_d. Медиана устойчива к одиночным выбросам замера и не
    требует, чтобы замеры стояли подряд. Требование к данным осталось, но переехало
    с календаря на ПЛОТНОСТЬ: в окне должно быть не меньше hglf_env_min_meas фактических
    замеров, а при СТАБИЛЬНОМ режиме — hglf_env_min_meas_stable, потому что при неизменной
    частоте каждый замер описывает больший кусок времени.
    """
    d = daily
    d['work_valid'] = (d['work_fraction'].ge(P['hglf_min_work_fraction'])
                       & d['frequency_running_median'].ge(P['hglf_stop_frequency_hz']))
    d['valid_day'] = d['work_valid'] & d['qliq_valid'] & d['physical_inputs_valid']
    d['raw_high_day'] = d['valid_day'] & d['gvf_intake'].ge(P['hglf_gvf_enter'])
    d['valid_measurement_day'] = d['valid_day'] & d['gf_measurement_day'] & d['gf_age_days'].eq(0)
    d['high_measurement_day'] = d['valid_measurement_day'] & d['gvf_intake'].ge(P['hglf_gvf_enter'])

    w = int(P['hglf_env_win_d'])
    if w < 1:
        raise ValueError('hglf_env_win_d должно быть положительным')

    # огибающая GVF: медиана ТОЛЬКО по зачтённым суткам, окно центрированное
    gvf_valid = d['gvf_intake'].where(d['valid_day'])
    env = gvf_valid.rolling(w, min_periods=2, center=True).median()
    d['gvf_envelope'] = env

    # плотность фактических замеров в том же окне
    meas = d['valid_measurement_day'].astype(int)
    n_meas = meas.rolling(w, min_periods=1, center=True).sum().fillna(0)
    need = np.where(d['regime_stable'].to_numpy(dtype=bool),
                    P['hglf_env_min_meas_stable'], P['hglf_env_min_meas'])
    d['env_measurement_days'] = n_meas
    d['env_measurements_required'] = need
    d['density_ok'] = n_meas.to_numpy(dtype=float) >= need

    d['confirmation_window_ok'] = (env.ge(P['hglf_gvf_enter']).fillna(False)
                                   & d['density_ok'])
    # день входит в эпизод, если он сам зачтён и его огибающая подтверждена
    d['confirmed_high_day'] = (d['valid_day'].to_numpy(dtype=bool)
                               & d['confirmation_window_ok'].to_numpy(dtype=bool))
    return d


def hglf_spans(daily, P):
    """Сначала СКЛЕЙКА фрагментов с разрывом <= hglf_merge_gap_days, ПОТОМ фильтр
    длительности >= hglf_min_episode_days. Порядок обязателен: 3 дня + разрыв 3 +
    3 дня дают эпизод в 9 суток, который сохраняется."""
    dates = list(daily.index[daily['confirmed_high_day'].fillna(False).to_numpy(dtype=bool)])
    if not dates:
        return []
    spans = []; s0 = e0 = dates[0]
    for cur in dates[1:]:
        if (cur - e0).days - 1 <= P['hglf_merge_gap_days']:
            e0 = cur
        else:
            spans.append((s0, e0)); s0 = e0 = cur
    spans.append((s0, e0))
    return [(a, b) for a, b in spans if (b - a).days + 1 >= P['hglf_min_episode_days']]


def det_vgf(ctx):
    """ВГФ v11 — физический расчёт доли свободного газа на приёме (GVF).
    Полностью заменяет прежнее правило по порогу недельного среднего ГЖФ."""
    P = ctx.P
    if not PVT_CURVES:
        ctx.hglf_daily = pd.DataFrame()
        return []
    daily = hglf_daily(ctx)
    if daily.empty:
        ctx.hglf_daily = daily
        return []
    daily = hglf_carry_gf(daily, P)
    daily = hglf_baseline(daily, P)
    daily = hglf_pvt(daily, getattr(ctx, 'well_id', ''))
    daily = hglf_physics(daily, P)
    daily = hglf_confirm(daily, P)
    ctx.hglf_daily = daily
    spans = hglf_spans(daily, P)
    return [(a, b + pd.Timedelta(hours=23)) for a, b in spans]


def det_gf_rise(ctx):
    g, _ = _glf_daily(ctx)
    return _glf_trend_runs(g, +1, ctx.P['gf_trend_frac'], ctx.P['gf_trend_min_d'])


def det_gf_drop(ctx):
    g, _ = _glf_daily(ctx)
    return _glf_trend_runs(g, -1, ctx.P['gf_trend_frac'], ctx.P['gf_trend_min_d'])


def _glf_episode_pts(ctx, start, end):
    raw = ctx.tele.get(GLF)
    if raw is None:
        return pd.Series(dtype=float)
    raw = pd.to_numeric(raw, errors='coerce').dropna(); raw = raw[raw > 0]
    return raw[(raw.index >= start.normalize()) & (raw.index <= end.normalize())]


def _hglf_episode_slice(ctx, start, end):
    d = getattr(ctx, 'hglf_daily', None)
    if d is None or len(d) == 0:
        return None
    return d[(d.index >= start.normalize()) & (d.index <= end.normalize())]


def _score_vgf(ctx, start, end):
    """Уверенность ВГФ определяется ПОДТВЕРЖДЁННОСТЬЮ ЗАМЕРАМИ, а не величиной ГЖФ:
    high — фактическими замерами закрыто >= 70% суток эпизода И >= 70% этих замеров
    высокие; иначе medium. Косвенные признаки (падение Qж, рост Рпр) в v11 не участвуют:
    физический критерий самодостаточен."""
    seg = _hglf_episode_slice(ctx, start, end)
    if seg is None or seg.empty:
        return dict(score=0.4, tier='low', signals={})
    dur = int((end.normalize() - start.normalize()).days) + 1
    measured = int(seg['valid_measurement_day'].sum())
    high = int(seg['high_measurement_day'].sum())
    share = (high / measured) if measured else 0.0
    tier = ('high' if (measured >= math.ceil(dur * 0.70) and share >= 0.70) else 'medium')
    gvf_med = float(seg.loc[seg['raw_high_day'], 'gvf_intake'].median()) if seg['raw_high_day'].any() else np.nan
    return dict(score=round(min(0.5 + 0.5 * share, 1.0), 2), tier=tier,
                signals=dict(measured_days=measured, high_measurements=high,
                             high_share=round(share, 2),
                             gvf_median_pct=(round(gvf_med * 100, 1) if np.isfinite(gvf_med) else None),
                             critical_days=int((seg['gvf_intake'] >= ctx.P['hglf_gvf_critical']).sum())))


def _score_gf_trend(ctx, start, end):
    """v12: ВГФ больше не фильтрует тренды ГФ, но задаёт уверенность — тренд внутри
    периода высокого GVF подтверждён физическим расчётом свободного газа."""
    raw = _glf_episode_pts(ctx, start, end)
    inside = any(start <= b and a <= end for a, b in getattr(ctx, 'vgf_iv', []))
    if len(raw) < ctx.P['glf_min_pts']:
        tier, score = 'low', 0.3
    elif inside:
        tier, score = 'high', 0.8
    else:
        tier, score = 'medium', 0.6
    return dict(score=score, tier=tier,
                signals=dict(n_glf=int(len(raw)), inside_vgf=bool(inside)))


def label_well(tele, vsp, P=PARAMS, gdi_events=None, hal_raw=None):
    ctx = WellCtx(tele, vsp, P, hal_raw=hal_raw)
    res = {}
    res['Остановка'] = det_stop(ctx)
    res['Работа']    = det_work(ctx)
    res['ГДИ']       = det_gdi(ctx, gdi_events)
    res['РПТЧ']      = _rptch_clean(ctx, det_rptch(ctx))
    res['УВЧ']       = det_uvch(ctx, res['РПТЧ'])
    res['Периодическая работа'] = det_periodic(ctx)   # v10.3: до УМЧ — нужен для огибающей
    res['УМЧ']       = det_umch(ctx, res['РПТЧ'], res['Периодическая работа'])
    res['НУР']       = det_nur(ctx)
    res['Снижение Рпл']  = det_snizh_rpl(ctx, res['НУР'], res['ГДИ'], res['РПТЧ'])
    res['Рост Рпл']      = det_rost_rpl(ctx, res['УВЧ'], res['НУР'])
    _wcr, _wcs = det_wcut(ctx)
    res['Рост обводненности'] = _wcr
    res['Снижение обводненности'] = _wcs
    _opz = det_opz_clusters(ctx)
    res['Снижение Кпрод']    = det_kprod_drop(ctx, _opz, res['НУР'])
    # v9.9 (Вариант B): Снижение Кпрод только при СТАБИЛЬНОЙ частоте. Любое крупное
    # изменение частоты (рост ИЛИ падение) делает скачок расч.Кпрод операционным
    # (меняются отборы/депрессия), а не снижением продуктивности. Универсально (Vt_4401/Vt_605).
    if getattr(ctx, 'cyclic', False) and res['Снижение Кпрод']:
        _f = ctx.wd[F].dropna(); _kept = []
        for _s, _e in res['Снижение Кпрод']:
            _seg = _f[(_f.index >= _s.normalize()) & (_f.index <= _e.normalize())]
            _dfr = 0.0
            if len(_seg) >= 3:
                _k = max(1, len(_seg) // 3)
                _dfr = float(_seg.iloc[-_k:].median() - _seg.iloc[:_k].median())
            if abs(_dfr) < P['kprod_freq_stable_hz']:
                _kept.append((_s, _e))
        res['Снижение Кпрод'] = _kept
    # v12.4: «Осложнённый фонд» — реальная, ВЫВОДИМАЯ категория (>= cf_min_kprod эпизодов
    # Снижения Кпрод в скользящем окне cf_kprod_win — «Кпрод снижался несколько раз за
    # месяц»), а НЕ сырой прокси по количеству ОПЗ-событий (_is_complicated/
    # det_opz_clusters). Считаем её здесь же, на исходных (ещё не обрезанных НУРом)
    # эпизодах Кпрод — она нужна ниже как гейт исключения из приоритета НУР.
    res['Осложнённый фонд'] = det_complicated_fund(ctx, res['Снижение Кпрод'])
    # v11.1/v12.4: Снижение Кпрод НЕ пересекается с НУР — НУР приоритетнее, КРОМЕ
    # случая, когда сам эпизод Кпрод лежит в интервале «Осложнённый фонд»: там эксперт
    # метит Кпрод per-провал независимо от НУР (Ic_805, Ic_914, Ya_289).
    # v12.4: гейт исключения — фактическая, интервальная категория «Осложнённый фонд»
    # (по ПОВТОРЯЕМОСТИ эпизодов Кпрод), а не прежний well-level флаг _is_complicated
    # по сырым ОПЗ-событиям: тот на Ic_349 включал исключение из-за одиночного
    # ГТМ/ОПЗ без реального кластера Кпрод, отсюда и лишнее пересечение с НУР.
    if res.get('НУР') and res.get('Снижение Кпрод'):
        _cf_iv = res['Осложнённый фонд']
        _min_kp_d = pd.Timedelta(days=P['kprod_min_d'])
        _kept_np2 = []
        for _s0, _e0 in res['Снижение Кпрод']:
            if any(min(_e0, _b) > max(_s0, _a) for _a, _b in _cf_iv):
                _kept_np2.append((_s0, _e0)); continue   # внутри Осложнённого фонда — исключение
            _trim = subtract_iv([(_s0, _e0)], res['НУР'])
            _kept_np2 += [(a, b) for a, b in _trim if (b - a) >= _min_kp_d]
        res['Снижение Кпрод'] = _kept_np2
    res['Рост Кпрод']        = det_kprod_rise(ctx, _opz, res['НУР'])
    res['Деградация ЭЦН']    = det_degr(ctx, res['НУР'])
    # v10.4: Неопт. режим = det_deopt (рост Рпр при стаб. Qж) + критерий периодич. фонда.
    # Не частить: разрывы < neopt_merge_gap_d объединяем, интервалы короче neopt_min_d убираем.
    # v10.9: склейка ТОЛЬКО внутри критерия. Раньше merge_iv с зазором 2 сут сливал
    # окно det_deopt («рост Рпр при стаб. Qж») с интервалом периодического фонда
    # («простои/накопление в остановках») в один эпизод, после чего объяснение
    # рассказывало физику чужого критерия. Провенанс кладём в ctx.neopt_src —
    # по нему объяснение и уверенность описывают ИМЕННО сработавший признак.
    _gap = pd.Timedelta(days=P['neopt_merge_gap_d'])
    _np_dp = merge_iv(list(det_deopt(ctx, res['НУР'])), gap=_gap)
    _np_cy = merge_iv(list(det_neopt_cyclic(ctx, res['Периодическая работа'])), gap=_gap)
    ctx.neopt_src = ([(a0, b0, 'deopt') for a0, b0 in _np_dp]
                     + [(a0, b0, 'cyclic') for a0, b0 in _np_cy])
    _neopt = merge_iv(list(_np_dp) + list(_np_cy), gap=pd.Timedelta(0))  # только фактические перекрытия
    res['Неопт. режим']      = [(s0, e0) for s0, e0 in _neopt
                                if (e0 - s0) >= pd.Timedelta(days=P['neopt_min_d'])]
    # v10.10: ВЕТО по физике категории — скрытое ограничение проявляется РОСТОМ Рпр приёма.
    # Если за эпизод рабочий интейк не вырос, это не Неопт. режим, каким бы критерием
    # он ни был найден. Тренд берём робастно (медианы крайних третей), а не по концам.
    _ipn = ctx.wd[IP].dropna() if IP in ctx.wd else pd.Series(dtype=float)
    _ipn = _ipn[_ipn > 0]
    _kept_np = []
    for _s0, _e0 in res['Неопт. режим']:
        _sg = _ipn[(_ipn.index >= _s0) & (_ipn.index <= _e0)]
        if len(_sg) < 3:
            continue                                  # нечем подтвердить рост -> не выдаём
        _k = max(1, len(_sg) // 3)
        if (_sg.iloc[-_k:].median() - _sg.iloc[:_k].median()) <= P['neopt_rise_veto_bar']:
            continue                                  # Рпр не растёт -> категория неприменима
        _kept_np.append((_s0, _e0))
    res['Неопт. режим'] = _kept_np
    # v9.9: циклич. — Рост Рпл, целиком в Снижении Кпрод, есть снижение продуктивности (Qж падает ->
    # депрессия падает -> интейк растёт), не пластовый рост. Перекрытие>=порога -> убрать.
    if getattr(ctx, 'cyclic', False) and res['Рост Рпл'] and res['Снижение Кпрод']:
        _kept = []
        for _rs, _re in res['Рост Рпл']:
            _span = (_re - _rs).total_seconds(); _ov = 0.0
            for _ks, _ke in res['Снижение Кпрод']:
                _d = (min(_re, _ke) - max(_rs, _ks)).total_seconds()
                if _d > 0: _ov += _d
            if _span <= 0 or _ov / _span < P['rost_kprod_overlap_max']:
                _kept.append((_rs, _re))
        res['Рост Рпл'] = _kept
    res['СППВ']      = det_sppv(ctx)
    res['Увеличение подачи воды'] = det_water_supply_up(ctx)
    res['ВГФ']       = det_vgf(ctx)
    # v11: прежняя стоп-управляемая ветка ВГФ (циклич. скв. + >=3 Снижения Кпрод ->
    # весь диапазон Кпрод помечался как ВГФ) УДАЛЕНА: это было второе конкурирующее
    # правило на ту же метку. Признак теперь один — физический GVF на приёме.
    res['Рост ГФ']   = det_gf_rise(ctx)
    res['Снижение ГФ'] = det_gf_drop(ctx)
    # v10: объединяем близкие эпизоды новых категорий (в пределах недели) в длинные
    _wk = pd.Timedelta(days=P['new_cat_merge_d'])
    # v11: ВГФ ИСКЛЮЧЁН из общей склейки. Его порядок постобработки задан жёстко:
    # склейка разрывов <= hglf_merge_gap_days (3 сут) -> фильтр длительности >= 7 сут,
    # и он уже выполнен внутри det_vgf. Общий зазор 7 сут переклеил бы эпизоды заново.
    for _k in ('Рост ГФ', 'Снижение ГФ', 'Деградация ЭЦН'):   # v10.4: Неопт. режим — своя склейка (2 сут)
        if res.get(_k):
            res[_k] = merge_iv(res[_k], gap=_wk)
    # v9: Снижение Рпл и Снижение Кпрод не пересекаются (только нециклич.; на
    # циклич. огибающая Рпл — фоновый межцикловый тренд, его не дробим Кпродом)
    if not getattr(ctx, 'cyclic', False):
        res['Снижение Рпл'] = subtract_iv(res['Снижение Рпл'], res['Снижение Кпрод'])
    # v10.5: Вогель-критерий Рпл — изменение Qж при постоянной огибающей Рпр.
    # Приоритет: пересечение со Снижением/Ростом Кпрод -> Кпрод (вычитаем);
    # НО если после последнего ОПЗ Кпрод стабилен -> приоритет Рпл (не вычитаем).
    _vg_dn, _vg_up = det_rpl_vogel(ctx, res['НУР'])
    _kp_all = list(res.get('Снижение Кпрод', [])) + list(res.get('Рост Кпрод', []))
    def _vogel_priority(vg, mind):
        kept = []
        for _s0, _e0 in vg:
            _ovl = any(min(_e0, _b) > max(_s0, _a) for _a, _b in _kp_all)
            if _ovl and not _kprod_stable_after_opz(ctx, _opz, _s0):
                _pieces = subtract_iv([(_s0, _e0)], _kp_all)     # приоритет Кпрод
            else:
                _pieces = [(_s0, _e0)]                           # приоритет Рпл (Кпрод стабилен после ОПЗ)
            # v10.9: обрезок после вычитания Кпрод обязан САМ быть трендом нужной длины
            kept += [(_a, _b) for _a, _b in _pieces if (_b - _a).days + 1 >= mind]
        return kept
    if _vg_dn:
        res['Снижение Рпл'] = merge_iv(list(res['Снижение Рпл'])
                                       + _vogel_priority(_vg_dn, P['rplq_min_trend_d']))
    if _vg_up:
        res['Рост Рпл'] = merge_iv(list(res['Рост Рпл'])
                                   + _vogel_priority(_vg_up, P['rplq_up_min_trend_d']))
    # v12.5: финальная защита НУР-приоритета ПОСЛЕ подмешивания Вогель-сегментов —
    # тот же принцип, что и в det_snizh_rpl/det_rost_rpl: какой бы детектор ни добавил
    # интервал в Рпл, он не должен пересекать НУР. Дешёвая и безусловная подстраховка
    # на случай расхождения гранулярности времени между источниками (Ic_349-класс багов).
    if res.get('НУР'):
        res['Снижение Рпл'] = subtract_iv(res['Снижение Рпл'], res['НУР'])
        res['Рост Рпл']     = subtract_iv(res['Рост Рпл'], res['НУР'])
    # v9.9: нециклич. — Снижение Рпл, ПРИМЫКАЮЩЕЕ к Снижению Кпрод, есть продолжение
    # снижения продуктивности (не истощение), ЕСЛИ интейк не вернулся на доснижения уровень И до Кпрод
    # было стабильное плато интейка. Тогда переносим интервал в Снижение Кпрод (Vt_3311).
    if not getattr(ctx, 'cyclic', False) and res['Снижение Кпрод'] and res['Снижение Рпл']:
        _ip = ctx.wd[IP].dropna(); _ip = _ip[_ip > 0]
        _gap = pd.Timedelta(days=P['kprod_reclass_gap_d'])
        _moved, _keep = [], []
        for _rs, _re in res['Снижение Рпл']:
            _adj = [(a, b) for a, b in res['Снижение Кпрод'] if pd.Timedelta(0) <= (_rs - b) <= _gap]
            _ok = False
            if _adj:
                _ks, _ke = max(_adj, key=lambda x: x[1])
                _base = _ip[(_ip.index >= _ks - pd.Timedelta(days=30)) & (_ip.index < _ks)].median()
                _atr  = _ip[(_ip.index >= _rs) & (_ip.index <= _rs + pd.Timedelta(days=15))].median()
                _pre  = _ip[(_ip.index >= _ks - pd.Timedelta(days=120)) & (_ip.index < _ks)]
                if len(_pre) >= 5 and pd.notna(_base) and pd.notna(_atr) and _base > 0:
                    _x = (_pre.index - _pre.index[0]).days.values
                    _rel = abs(float(np.polyfit(_x, _pre.values, 1)[0]) / _pre.mean() * 30 * 100)
                    if _atr < _base - P['kprod_reclass_tol'] and _rel < P['kprod_reclass_stable_pct']:
                        _ok = True
            (_moved if _ok else _keep).append((_rs, _re))
        if _moved:
            res['Снижение Кпрод'] = merge_iv(list(res['Снижение Кпрод']) + _moved,
                                             gap=pd.Timedelta(days=P['kprod_reclass_gap_d'] + 1))
            res['Снижение Рпл'] = _keep
    # v12.7: УВЧ/УМЧ — событие смены частоты, а не длинный тренд. Хвост после выхода
    # на новую полку обрезаем потолком; сама ступень (начало эпизода) сохраняется.
    _cap = pd.Timedelta(days=P['uvch_max_d'])
    for _k in ('УВЧ', 'УМЧ'):
        res[_k] = [(a, min(b, a + _cap)) for a, b in res.get(_k, [])]

    # Рост/Снижение обводненности НЕ разрезаются по смене ЭЦН: тренд обводнённости —
    # свойство пласта/флюида, а не оборудования (в отличие от НУР/Кпрод/РПТЧ, которые
    # физически завязаны на конкретный насос).
    _split_keys = ['НУР','Снижение Кпрод','Деградация ЭЦН','РПТЧ']
    if not getattr(ctx, 'cyclic', False):
        _split_keys += ['Снижение Рпл','Рост Рпл']
    for k in _split_keys:
        res[k] = split_at(res[k], ctx.esp_breaks)
    # v10.16: тренд пластового давления короче rpl_frag_min_d — не тренд. Фильтр стоит
    # ПОСЛЕ разрезания и вычитаний, т.е. отсекает именно финальные осколки конвейера.
    for k in ('Снижение Рпл', 'Рост Рпл'):
        res[k] = [(s0, e0) for s0, e0 in res.get(k, [])
                  if (e0 - s0) >= pd.Timedelta(days=P['rpl_frag_min_d'])]
    # ВЕТО по данным (о Рпр = 0) применяется позже, на уровне run_all — см.
    # _rpl_ip_valid_mask там: антагонист-резолюция (Снижение Рпл vs Рост Рпл) ещё
    # впереди и может разрезать сейчас ЦЕЛЬНЫЙ интервал на осколки; проверка ЗДЕСЬ,
    # до разрезания, видела бы только цельный (в основном валидный) интервал и не
    # поймала бы плохой осколок, который появится уже после (Au_389, 11-20.12.2025).
    # Сигнатурный слой: опциональная мягкая переразметка пограничных эпизодов
    if SIG_RELABEL:
        nur, sniz = list(res.get('НУР', [])), list(res.get('Снижение Рпл', []))
        nn, ns = [], []
        for s_, e_ in nur:
            sg = sig_score(ctx, s_, e_)
            (ns if (sg['label'] == 'Снижение Рпл' and sg['margin'] >= SIG_RELABEL_MARGIN) else nn).append((s_, e_))
        for s_, e_ in sniz:
            sg = sig_score(ctx, s_, e_)
            (nn if (sg['label'] == 'НУР' and sg['margin'] >= SIG_RELABEL_MARGIN) else ns).append((s_, e_))
        res['НУР'] = merge_iv(nn)
        res['Снижение Рпл'] = subtract_iv(merge_iv(ns), res['НУР'])

    # v9.8: в ДЛИННЫХ остановках (>12ч) допустима ТОЛЬКО ГДИ — вычитаем длинные
    # стопы из всех прочих диагностических категорий. Короткие стопы НЕ дробим.
    # ГДИ — событие простоя (оставляем); РПТЧ/Периодическая/СППВ — РЕЖИМЫ,
    # охватывают остановки (не дробим). Точечные/трендовые категории вычищаем
    # из длинных остановок (там должна быть только ГДИ).
    # На ЦИКЛИЧЕСКИХ скважинах >=12ч стопы — часть цикла (не дробим тренды/НУР).
    # Вычищаем длинные простои только на НЕциклических (там >=12ч = реальный idle);
    # РПТЧ/Периодическая/СППВ — режимы, охватывают остановки (всегда не дробим).
    # v10: при остановках > 3 СУТ допустимы ТОЛЬКО Остановка и ГДИ — все прочие
    # категории (режимы, тренды, газовые) ПРЕРЫВАЮТСЯ на таких остановках (все скважины).
    # Рост/Снижение обводненности — ИСКЛЮЧЕНИЕ: water_cut_algo сам обнуляется (NaN) на
    # остановках (adaptive_water_cut.py), так что det_wcut уже не видит эти дни при
    # сглаживании, а его собственная склейка (wct_merge_gap_d суток) объединяет разрывы
    # внутри одного направления; повторное вычитание здесь дробило бы один длинный
    # трендовый интервал на серию мелких осколков вокруг каждой остановки — ровно то,
    # что новая модель обязана НЕ делать (см. adaptive_water_cut.py).
    _stops3 = [(s, e) for s, e in ctx.stops if (e - s) > pd.Timedelta(days=3)]
    if _stops3:
        for _k in list(res.keys()):
            if _k in ('Остановка', 'ГДИ', 'Рост обводненности', 'Снижение обводненности'):
                continue
            res[_k] = subtract_iv(res[_k], _stops3)
    # На НЕциклических также вычищаем прочие длинные простои (>=12ч) из точечных/
    # трендовых категорий; режимы и газовые на коротких остановках не дробим.
    if not getattr(ctx, 'cyclic', False):
        _keep_span = ('ГДИ', 'Работа', 'Остановка', 'РПТЧ', 'Периодическая работа', 'СППВ',
                      'ВГФ', 'Рост ГФ', 'Снижение ГФ', 'Деградация ЭЦН', 'Неопт. режим', 'УМЧ', 'УВЧ',
                      'Рост обводненности', 'Снижение обводненности')
        for _k in list(res.keys()):
            if _k in _keep_span:
                continue
            res[_k] = subtract_iv(res[_k], ctx.long_stops)

    # v10.3: вето ложного Снижения Рпл — если за ИНТЕРВАЛ эпизода рабочий интейк (Рпр)
    # не падает, а РАСТЁТ, это не снижение пластового давления. Межцикловая огибающая по
    # разреженным сегментам может дать ложное «снижение» при реальном росте Рпр внутри
    # сегмента (Au_389 ноя-дек 2025: огибающая 95->61, но интейк в окне рос 95->118).
    if getattr(ctx, 'cyclic', False) and res.get('Снижение Рпл'):
        _ipv = ctx.wd[IP].dropna(); _ipv = _ipv[_ipv > 0].rolling(5, min_periods=2).median()
        _kept = []
        for _s, _e in res['Снижение Рпл']:
            _seg = _ipv[(_ipv.index >= _s) & (_ipv.index <= _e)].dropna()
            if len(_seg) >= 3:
                _k = max(1, len(_seg) // 3)
                if (_seg.iloc[-_k:].median() - _seg.iloc[:_k].median()) >= P['snizh_rise_veto_bar']:
                    continue   # интейк за интервал растёт -> не Снижение Рпл
            _kept.append((_s, _e))
        res['Снижение Рпл'] = _kept

    # v12: гейт «Рост/Снижение ГФ только внутри ВГФ» СНЯТ. Тренд газового фактора —
    # самостоятельное явление: он существует и на скважинах без высокого GVF, и до его
    # наступления (Ic_914: сырой Рост ГФ 09.12-13.01 совпадал с ручным 18.12-19.01, но
    # ВГФ там нет и эпизод выбрасывался; Mc_014: из 3 сырых Снижений ГФ гейт оставлял 1).
    # Связь с ВГФ осталась в УВЕРЕННОСТИ: тренд внутри ВГФ подтверждён физикой.
    _vgf = res.get('ВГФ', [])
    ctx.vgf_iv = list(_vgf)

    # v10.8: снижение и прирост одной величины не могут действовать одновременно.
    # Приоритет: длительность -> уверенность и сила -> негативный фактор.
    res = resolve_antagonists(res, ctx)
    # v10.11: самосогласованность Кпрод — ПОСЛЕ всех обрезок и разрешения антагонистов.
    # Раньше фильтр стоял до subtract_iv, и обрезанный интервал успевал «похудеть» до 1-3%:
    # эпизод отчитывался о величине, которой сам не соответствует. Метрика та же, что в
    # пояснении (kprod_net_frac), поэтому разойтись они больше не могут.
    # ОГРАНИЧЕНИЕ (Ic_805): ручные эпизоды Снижения Кпрод на осложнённом фонде длятся
    # 0.1-1.2 суток (медиана 0.65), а ctx.kprod — СУТОЧНЫЙ ряд. Субсуточные провалы на нём
    # непредставимы в принципе: дробление блоба по суточным данным пробовалось и дало
    # 8 интервалов вместо 42 при потере 12 совпадений на фонде. Нужен переход расчёта
    # Кпрод на исходную частоту телеметрии — это структурная правка, не порог.
    # v12.6: ПРЯМОЕ СВИДЕТЕЛЬСТВО ПЕРЕВЕШИВАЕТ ПРОИЗВОДНУЮ ВЕЛИЧИНУ.
    # Эпизод «Рост Кпрод», внутри которого огибающая Qж значимо УПАЛА, — не рост
    # продуктивности: расчётный Кпрод = Q/dP мог вырасти из-за схлопывания депрессии.
    # Такой эпизод переразмечается в «Снижение Кпрод» (Au_389, S4000N: Qж -70% при
    # плоском Рпр давал «Рост Кпрод +26%», а эксперт ждёт снижения).
    _moved = []
    _keep_rise = []
    for _s0, _e0 in res.get('Рост Кпрод', []):
        _qf = kprod_q_net_frac(ctx, _s0, _e0)
        if _qf is not None and _qf <= -P['kprod_q_drop_override']:
            _moved.append((_s0, _e0))
        else:
            _keep_rise.append((_s0, _e0))
    if _moved:
        res['Рост Кпрод'] = _keep_rise
        res['Снижение Кпрод'] = merge_iv(list(res.get('Снижение Кпрод', [])) + _moved)

    _dd_mode = _is_complicated(ctx)      # v10.17: на осложнённом фонде эффект = провал
    for _lbl, _sgn in (('Снижение Кпрод', -1), ('Рост Кпрод', 1)):
        _kept_k = []
        for _s0, _e0 in res.get(_lbl, []):
            if _dd_mode and _lbl == 'Снижение Кпрод':
                _f = kprod_drawdown_frac(ctx, _s0, _e0)
            else:
                _f = kprod_net_frac(ctx, _s0, _e0)
            _ok = _f is not None and _sgn * _f >= P['kprod_report_min']
            if not _ok and _lbl == 'Снижение Кпрод':
                # переразмеченный по дебиту эпизод: подтверждаем его падением Qж
                _qf = kprod_q_net_frac(ctx, _s0, _e0)
                _ok = _qf is not None and _qf <= -P['kprod_q_drop_override']
            if _ok:
                _kept_k.append((_s0, _e0))
        res[_lbl] = _kept_k

    conf = {}
    for lbl, ivs in res.items():
        lst = []
        for s_, e_ in ivs:
            sc = score_episode(ctx, lbl, s_, e_)
            if lbl in ('НУР', 'Снижение Рпл'):
                sg = sig_score(ctx, s_, e_)
                sc['sig_label'] = sg['label']; sc['sig_margin'] = sg['margin']
                # сигнатура уверенно противоречит правилу -> понизить уверенность (флаг ревью)
                if sg['label'] != lbl and sg['margin'] >= SIG['margin_high']:
                    sc['tier'] = 'low'
            lst.append(sc)
        conf[lbl] = lst
    return res, ctx, conf



def _neopt_tags(ctx, s, e):
    """Какие критерии Неопт. режима перекрывают итоговый интервал. Ищем ПО ПЕРЕКРЫТИЮ,
    а не по ключу: интервал после subtract_iv обрезается по границам остановок и
    перестаёт совпадать с окном, на котором признак был вычислен."""
    return {t for a, b, t in getattr(ctx, 'neopt_src', []) if min(e, b) > max(s, a)}


def _fmt_delta(a, b, unit='бар', flat_frac=0.01):
    """Знак-корректное описание изменения: глагол выбирается ПО ЦИФРАМ.
    Делает невозможным «вырос ... (на ~-4%)» — источник рассинхрона текста и данных."""
    if a is None or b is None or not (a > 0):
        return None, 0.0
    pct = (b - a) / a * 100.0
    if abs(pct) < flat_frac * 100:
        return f"практически не изменился (~{a:.0f} {unit})", pct
    return f"{'вырос' if pct > 0 else 'снизился'} {a:.0f}->{b:.0f} {unit} ({pct:+.0f}%)", pct


def _xseg(series, s, e):
    if series is None or len(series) == 0:
        return pd.Series(dtype=float)
    x = pd.to_numeric(series, errors="coerce").dropna()
    return x[(x.index >= s.normalize()) & (x.index <= e.normalize())]


def _xfl(seg):
    if len(seg) < 1:
        return None, None
    return float(seg.iloc[0]), float(seg.iloc[-1])


def _xintake_trend(ctx, s, e):
    ipser = ctx.tele.get(IP)
    if ipser is None:
        return None, None
    ip = pd.to_numeric(ipser, errors="coerce").dropna()
    if ip.empty:
        return None, None
    ip = ip[ip > 0].resample("1D").median().rolling(7, min_periods=2).median().dropna()
    seg = ip[(ip.index >= s.normalize()) & (ip.index <= e.normalize())]
    if len(seg) < 2:
        return None, None
    k = max(1, len(seg) // 3)
    return float(seg.iloc[:k].median()), float(seg.iloc[-k:].median())


def explain_episode(ctx, label, s, e, tier=""):
    """Краткое (1 предложение) объяснение, почему эпизод так классифицирован."""
    dur = (e - s).days + 1
    wd = ctx.wd
    if label == "Работа":
        f = _xseg(wd.get(F), s, e)
        return (f"Скважина в работе: частота ЭЦН ~{f.median():.0f} Гц на протяжении {dur} сут."
                if len(f) else f"Скважина в работе {dur} сут (частота выше порога остановки).")
    if label == "Остановка":
        return f"Остановка {dur} сут: частота ЭЦН ниже порога запуска (насос не качает)."
    if label == "ГДИ":
        return "Гидродинамическое исследование: остановка с регистрацией восстановления давления."
    if label == "РПТЧ":
        f = _xseg(wd.get(F), s, e)
        return (f"Работа на постоянно меняющейся частоте: частые развороты частоты (размах ~{(f.max()-f.min()):.0f} Гц) без стабильной уставки."
                if len(f) else "Работа на постоянно меняющейся частоте: частые развороты частоты без стабильной уставки.")
    if label == "УВЧ":
        f = _xseg(wd.get(F), s, e)
        if len(f) >= 2:
            return f"Устойчивое увеличение частоты ЭЦН с {f.iloc[0]:.1f} до {f.max():.1f} Гц с удержанием на новом уровне."
        return "Устойчивое увеличение частоты ЭЦН на новый уровень."
    if label == "УМЧ":
        f = _xseg(wd.get(F), s, e)
        if len(f) >= 2:
            return f"Устойчивое уменьшение частоты ЭЦН с {f.iloc[0]:.1f} до {f.min():.1f} Гц с удержанием на новом уровне."
        return "Устойчивое уменьшение частоты ЭЦН на новый уровень."
    if label == "НУР":
        return f"Неустановившийся режим после остановки: переходный процесс ~{dur} сут (Рпр приёма восстанавливается и снижается)."
    if label == "Периодическая работа":
        return f"Периодический режим: частые циклы стоп-старт на протяжении {dur} сут."
    if label == "Снижение Рпл":
        a, b = _xintake_trend(ctx, s, e)
        if a is not None and b < a:
            return f"Снижение пластового давления: Рпр приёма снизился с {a:.0f} до {b:.0f} бар при стабильной частоте."
        return "Снижение пластового давления: спад Рпр при стабильной частоте либо снижение Qж при постоянной огибающей Рпр (пересчёт Рпл по Вогелю)."
    if label == "Рост Рпл":
        a, b = _xintake_trend(ctx, s, e)
        if a is not None and b > a:
            return f"Рост пластового давления: Рпр приёма вырос с {a:.0f} до {b:.0f} бар."
        return "Рост пластового давления: рост Рпр либо рост Qж при постоянной огибающей Рпр (пересчёт Рпл по Вогелю)."
    if label == "Снижение Кпрод":
        extra = " (подтверждено падением дебита/ОПЗ)" if tier == "high" else ""
        if _is_complicated(ctx):
            f = kprod_drawdown_frac(ctx, s, e)
            n = kprod_net_frac(ctx, s, e)
            if f is not None and f < 0:
                rec = " с частичным восстановлением" if (n is not None and n > f + 0.02) else ""
                return f"Снижение продуктивности: провал расчётного Кпрод на ~{-f*100:.0f}%{rec}{extra}."
        else:
            f = kprod_net_frac(ctx, s, e)
            if f is not None and f < 0:
                return f"Снижение продуктивности: расчётный Кпрод упал на ~{-f*100:.0f}%{extra}."
        return f"Снижение продуктивности: устойчивое падение расчётного Кпрод{extra}."
    if label == "Рост Кпрод":
        f = kprod_net_frac(ctx, s, e)
        if f is not None and f > 0:
            return f"Рост продуктивности: расчётный Кпрод вырос на ~{f*100:.0f}%."
        return "Рост продуктивности: устойчивый рост расчётного Кпрод."
    if label == "Осложнённый фонд":
        return "Осложнённый фонд: высокая плотность эпизодов снижения продуктивности на участке."
    if label == "Деградация ЭЦН":
        # v13.2 (перенесено из fable-классификатора v12.8): пояснение считает УДЕЛЬНУЮ
        # загрузку — ту же величину, что и критерий. Раньше текст рапортовал сырую
        # загрузку и мог сказать «снизился 59->46%» под меткой «ухудшение характеристики»,
        # противореча сам себе.
        env = int(ctx.P['degr_env_win_d'])
        ld = _xseg(wd.get(LD), s, e)
        qd = _q_any_daily(ctx)
        qs_ = _xseg(qd, s, e) if qd is not None else None
        def _env(x):
            if x is None or len(x) < 2:
                return None
            r = x.rolling(env, min_periods=max(2, env // 2), center=True).median().dropna()
            return r if len(r) >= 2 else None
        le, qe = _env(ld), _env(qs_)
        if le is not None and qe is not None and float(qe.min()) > 0:
            sp_ = (le / qe.reindex(le.index)).dropna()
            if len(sp_) >= 2 and float(sp_.iloc[0]) > 0:
                d_sp = (sp_.iloc[-1] - sp_.iloc[0]) / sp_.iloc[0] * 100
                d_ld = (le.iloc[-1] - le.iloc[0]) / le.iloc[0] * 100
                d_q = (qe.iloc[-1] - qe.iloc[0]) / qe.iloc[0] * 100
                return (f"Ухудшение напорно-расходной характеристики ЭЦН: удельная загрузка "
                        f"(загрузка/Qж) выросла на ~{d_sp:.0f}% "
                        f"(загрузка {d_ld:+.0f}%, дебит {d_q:+.0f}%).")
        return "Ухудшение напорно-расходной характеристики ЭЦН: рост удельной загрузки на единицу подачи."
    if label == "Неопт. режим":
        tags = _neopt_tags(ctx, s, e)
        parts = []
        if "cyclic" in tags:
            parts.append("периодический фонд: накопление Рпр за циклы остановки либо "
                         "повторяющиеся длинные простои — потенциал не отбирается")
        if "deopt" in tags:
            a, b = _xfl(_xseg(wd.get(IP), s, e))
            chg, pct = _fmt_delta(a, b)
            if chg and pct > 0:
                parts.append(f"скрытое ограничение: Рпр приёма {chg} при стабильном дебите")
            else:
                # интервал обрезан остановками/склейкой — концы не отражают окно срабатывания
                parts.append("скрытое ограничение: рост Рпр приёма при стабильном дебите внутри интервала"
                             + (f" (по краям интервала Рпр {chg})" if chg else ""))
        if not parts:
            return "Неоптимальный режим: признак зафиксирован, детализация недоступна."
        return "Неоптимальный режим — " + "; ".join(parts) + "."
    if label == "ВГФ":
        seg = _hglf_episode_slice(ctx, s, e)
        if seg is not None and not seg.empty and seg['raw_high_day'].any():
            gvf_med = float(seg.loc[seg['raw_high_day'], 'gvf_intake'].median()) * 100
            gvf_max = float(seg['gvf_intake'].max()) * 100
            measured = int(seg['valid_measurement_day'].sum())
            high = int(seg['high_measurement_day'].sum())
            q_med = float(seg['qliq_m3d'].median())
            crit = int((seg['gvf_intake'] >= ctx.P['hglf_gvf_critical']).sum())
            tail = f"; критических суток (GVF>={ctx.P['hglf_gvf_critical']*100:.0f}%): {crit}" if crit else ""
            return (f"Высокий ГЖФ: доля свободного газа на приёме медиана {gvf_med:.1f}%, "
                    f"максимум {gvf_max:.1f}%; подтверждено замерами {high}/{measured}; "
                    f"Qж медиана {q_med:.1f} м3/сут{tail}.")
        return f"Высокий ГЖФ: доля свободного газа на приёме выше порога на протяжении {dur} сут."
    if label == "Рост ГФ":
        g = _xseg(_glf_daily(ctx)[0], s, e); a, b = _xfl(g)
        return (f"Рост газового фактора: ГЖФ вырос с {a:.0f} до {b:.0f} (в периоде высокого ГФ)."
                if a is not None else "Рост газового фактора (в периоде высокого ГФ).")
    if label == "Снижение ГФ":
        g = _xseg(_glf_daily(ctx)[0], s, e); a, b = _xfl(g)
        return (f"Снижение газового фактора: ГЖФ снизился с {a:.0f} до {b:.0f} (в периоде высокого ГФ)."
                if a is not None else "Снижение газового фактора (в периоде высокого ГФ).")
    if label in ("Рост обводненности", "Снижение обводненности"):
        # v13.5: классификация из episode_rules_v12_10 (экспертное правило в два шага
        # с точными границами тренда — рост от точки-кандидата до разворота/
        # выполаживания, см. det_wcut), применённая к Обв_алгоритму (water_cut_algo).
        w = _xseg(ctx.tele.get("water_cut_algo"), s, e)
        w = w.resample("1D").median().dropna() if len(w) else w
        a, b = _xfl(w)
        direction = "выросла" if "Рост" in label else "снизилась"
        trend_pp = ctx.P.get("wct_trend_pp", 3.0)
        min_d = int(ctx.P.get("wct_min_d", 7))
        if a is not None:
            return (f"Обводнённость (Обв_алгоритм) {direction} с {a:.0f} до {b:.0f}% "
                    f"(нетто >{trend_pp:.0f} пп, устойчиво держится не менее {min_d} сут) "
                    f"и удержалась на новом уровне.")
        return (f"Обводнённость (Обв_алгоритм) {direction} более чем на {trend_pp:.0f} пп "
                f"с удержанием не менее {min_d} сут.")
    if label == "СППВ":
        return f"Совместная подача/перепуск: объёмный расход (bdpv) выше порога на протяжении {dur} сут."
    if label == "Увеличение подачи воды":
        return "Увеличение подачи воды: суточная подача (СППВ/bdpv) выросла более чем на 20% относительно предыдущих суток."
    return f"Эпизод «{label}» ({dur} сут)."


# Правила ПРЕВОСХОДСТВА: подчинённая категория не имеет права пересекаться с главной.
# В отличие от антагонистов, победитель известен заранее и не зависит от уверенности:
# это не спор двух версий одного явления, а физическая иерархия объяснений.
PRECEDENCE_RULES = (
    ('НУР', 'Снижение Кпрод',
     'на транзиенте после пуска Рзаб ещё не установилось, расчётный Кпрод недостоверен'),
    ('НУР', 'Рост Кпрод',
     'на транзиенте после пуска Рзаб ещё не установилось, расчётный Кпрод недостоверен'),
    # v12.6: рост Рпр к пластовому схлопывает депрессию, и расчётный Кпрод = Q/dP взлетает
    # арифметически, а не физически (Au_389, ЭЦН-200: Рпр +33% -> «Кпрод +856%»). Настоящий
    # рост продуктивности выглядит иначе — Рпр СТУПЕНЬКОЙ выходит на новый уровень за 5-7
    # суток, а не ползёт вместе с Кпрод.
    # ВАЖНО: «Снижение Кпрод» в это правило НЕ входит — падение продуктивности при растущем
    # Рпр физически осмысленно (прорыв газа: давление копится, отобрать его нечем).
    ('Рост Рпл', 'Рост Кпрод',
     'рост Рпл схлопывает депрессию и раздувает расчётный Кпрод арифметически'),
)


def enforce_precedence_df(df, P=PARAMS, log=None):
    """ЖЁСТКАЯ ГАРАНТИЯ: подчинённая категория не пересекается с главной.
    Работает на выходной таблице рядом с enforce_antagonists_df, поэтому инвариант не
    зависит от порядка правок выше по конвейеру. Из подчинённого эпизода ВЫРЕЗАЕТСЯ зона
    пересечения; если он разрезан главным надвое — остаются оба куска. Куски короче
    antag_min_keep_d отбрасываются; не осталось ничего — эпизод снимается целиком."""
    if df is None or len(df) == 0:
        return df
    if not {'well_id', 'label', 'start', 'end'}.issubset(df.columns):
        return df
    min_keep = pd.Timedelta(days=P['antag_min_keep_d'])
    rows = df.to_dict('records')
    for win_lbl, lose_lbl, why in PRECEDENCE_RULES:
        by_well = {}
        for r in rows:
            if r['label'] == win_lbl:
                by_well.setdefault(r['well_id'], []).append((r['start'], r['end']))
        if not by_well:
            continue
        out = []
        for r in rows:
            if r['label'] != lose_lbl or r['well_id'] not in by_well:
                out.append(r); continue
            pieces = subtract_iv([(r['start'], r['end'])], merge_iv(by_well[r['well_id']]))
            pieces = [(a, b) for a, b in pieces if (b - a) >= min_keep]
            if not pieces:
                if log is not None:
                    log.append({'well_id': r['well_id'], 'rule': (win_lbl, lose_lbl),
                                'action': 'снят целиком', 'reason': why})
                continue
            if len(pieces) == 1 and pieces[0] == (r['start'], r['end']):
                out.append(r); continue
            for a, b in pieces:
                q = dict(r); q['start'], q['end'] = a, b
                if 'dur_d' in q:
                    q['dur_d'] = round((b - a).total_seconds() / 86400.0, 2)
                out.append(q)
            if log is not None:
                log.append({'well_id': r['well_id'], 'rule': (win_lbl, lose_lbl),
                            'action': 'обрезан', 'kept': pieces, 'reason': why})
        rows = out
    return pd.DataFrame(rows, columns=df.columns).reset_index(drop=True)


def check_precedence_df(df):
    """Диагностика: оставшиеся пересечения подчинённых категорий с главными."""
    bad = []
    if df is None or len(df) == 0:
        return pd.DataFrame(columns=['well_id', 'winner', 'loser', 'start', 'end', 'overlap_d'])
    for win_lbl, lose_lbl, _why in PRECEDENCE_RULES:
        for well, grp in df[df['label'].isin((win_lbl, lose_lbl))].groupby('well_id', sort=False):
            gw, gl = grp[grp['label'] == win_lbl], grp[grp['label'] == lose_lbl]
            for _, x in gw.iterrows():
                for _, y in gl.iterrows():
                    ov = (min(x['end'], y['end']) - max(x['start'], y['start'])).total_seconds()
                    if ov > 0:
                        bad.append(dict(well_id=well, winner=win_lbl, loser=lose_lbl,
                                        start=max(x['start'], y['start']),
                                        end=min(x['end'], y['end']),
                                        overlap_d=round(ov / 86400.0, 3)))
    return pd.DataFrame(bad)


def enforce_antagonists_df(df, P=PARAMS, log=None):
    """ЖЁСТКАЯ ГАРАНТИЯ на ВЫХОДНОЙ таблице: антагонистичные категории не пересекаются
    по времени ни на одной скважине.

    Зачем отдельно от resolve_antagonists. Тот работает внутри label_well и корректен,
    но его корректность держится ПОРЯДКОМ операций: любое слияние или добавление
    интервалов после него молча вернёт пересечение, и наружу уйдёт эпизод, где одна и
    та же величина одновременно растёт и падает. Эта функция — последний рубеж: она
    стоит в самом конце run_all, работает с готовой таблицей и потому не зависит от
    того, что и в каком порядке правили выше.

    Победитель определяется детерминированно и без ctx:
      1) выше уверенность (confidence),
      2) при равной — длиннее эпизод,
      3) при равной — негативная категория пары (истощение важнее не пропустить),
      4) при полном равенстве — более ранний старт (устойчивость к перестановке строк).
    Проигравший теряет зону пересечения; если остаток короче antag_min_keep_d или
    пересечение съело больше antag_drop_frac эпизода — снимается целиком.
    """
    if df is None or len(df) == 0:
        return df
    need = {'well_id', 'label', 'start', 'end'}
    if not need.issubset(df.columns):
        return df
    min_keep = pd.Timedelta(days=P['antag_min_keep_d'])
    drop_frac = P['antag_drop_frac']
    has_conf = 'confidence' in df.columns
    out = df.copy().reset_index(drop=True)
    out['_drop'] = False

    def _rank(row, neg):
        return (float(row['confidence']) if has_conf and pd.notna(row['confidence']) else 0.0,
                (row['end'] - row['start']).total_seconds(),
                1.0 if row['label'] == neg else 0.0,
                -row['start'].value)

    for A, B, neg in ANTAGONIST_PAIRS:
        for _well, grp in out[out['label'].isin((A, B))].groupby('well_id', sort=False):
            idx = list(grp.index)
            for _ in range(2000):                      # страховка от зацикливания
                hit = None
                for i in idx:
                    if out.at[i, '_drop']:
                        continue
                    for j in idx:
                        if j == i or out.at[j, '_drop'] or out.at[i, 'label'] == out.at[j, 'label']:
                            continue
                        if min(out.at[i, 'end'], out.at[j, 'end']) > max(out.at[i, 'start'], out.at[j, 'start']):
                            hit = (i, j); break
                    if hit:
                        break
                if hit is None:
                    break
                i, j = hit
                win, lose = (i, j) if _rank(out.loc[i], neg) >= _rank(out.loc[j], neg) else (j, i)
                ws, we = out.at[win, 'start'], out.at[win, 'end']
                ls, le = out.at[lose, 'start'], out.at[lose, 'end']
                ov = min(we, le) - max(ws, ls)
                span = le - ls
                left = (ls, min(ws, le))
                right = (max(we, ls), le)
                cands = [(a, b) for a, b in (left, right) if (b - a) >= min_keep]
                if span <= pd.Timedelta(0) or ov >= drop_frac * span or not cands:
                    out.at[lose, '_drop'] = True
                    kept = None
                else:
                    a, b = max(cands, key=lambda p: p[1] - p[0])   # оставляем больший обрезок
                    out.at[lose, 'start'], out.at[lose, 'end'] = a, b
                    if 'dur_d' in out.columns:
                        out.at[lose, 'dur_d'] = round((b - a).total_seconds() / 86400.0, 2)
                    kept = (a, b)
                if log is not None:
                    log.append({'well_id': out.at[win, 'well_id'], 'pair': (A, B),
                                'winner': out.at[win, 'label'], 'loser': out.at[lose, 'label'],
                                'overlap_d': round(ov.total_seconds() / 86400.0, 3), 'kept': kept})
    return out[~out['_drop']].drop(columns='_drop').reset_index(drop=True)


def check_antagonists_df(df):
    """Диагностика инварианта: список оставшихся пересечений. Пустой — инвариант держится.
    Годится и для проверки ЧУЖОЙ выгрузки эпизодов (well_id, label, start, end)."""
    bad = []
    if df is None or len(df) == 0:
        return pd.DataFrame(columns=['well_id', 'a', 'b', 'start', 'end', 'overlap_d'])
    for A, B, _neg in ANTAGONIST_PAIRS:
        for well, grp in df[df['label'].isin((A, B))].groupby('well_id', sort=False):
            ga, gb = grp[grp['label'] == A], grp[grp['label'] == B]
            for _, x in ga.iterrows():
                for _, y in gb.iterrows():
                    ov = (min(x['end'], y['end']) - max(x['start'], y['start'])).total_seconds()
                    if ov > 0:
                        bad.append(dict(well_id=well, a=A, b=B,
                                        start=max(x['start'], y['start']),
                                        end=min(x['end'], y['end']),
                                        overlap_d=round(ov / 86400.0, 3)))
    return pd.DataFrame(bad)


def run_all(tele_all, vsp_all, wells=None, P=PARAMS, events=None, hal_raw=None):
    rows = []
    _ip_daily_by_well = {}
    wells = wells if wells is not None else sorted(tele_all['well_id'].unique())
    for wid in wells:
        tw = tele_all[tele_all['well_id'] == wid].set_index('telemetry_time').sort_index()
        vw = vsp_all[vsp_all['well_id'] == wid]
        if tw.empty: continue
        gev = None
        if events is not None:
            g = events[(events['well_id'] == wid) & (events['kind'] == 'gdi')]
            gev = list(zip(g['start'], g['end']))
        hal_w = hal_raw[hal_raw['well_id'] == wid] if hal_raw is not None and len(hal_raw) else None
        res, ctx, conf = label_well(tw, vw, P, gdi_events=gev, hal_raw=hal_w)
        _ip_daily_by_well[wid] = ctx.wd[IP] if IP in ctx.wd else pd.Series(dtype=float)
        for lbl, ivs in res.items():
            dflt = [{'score': 1.0, 'tier': 'high', 'signals': {}}] * len(ivs)
            scores = conf.get(lbl, dflt)
            for (s, e), sc in zip(ivs, scores):
                rows.append((
                    wid, lbl, s, e,
                    round((e - s).total_seconds() / 86400, 2),
                    sc['score'],
                    sc['tier'],
                    sc.get('sig_label', ''),
                    sc.get('sig_margin', ''),
                    str(sc['signals']),
                    explain_episode(ctx, lbl, s, e, sc.get('tier', '')),
                ))
    df = pd.DataFrame(rows, columns=[
        'well_id', 'label', 'start', 'end', 'dur_d',
        'confidence', 'confidence_tier', 'sig_label', 'sig_margin', 'signals', 'explanation',
    ])
    # v10.16: страховка на ИТОГОВОЙ таблице — осколки Рпл могут родиться и ниже
    # фильтра в label_well (SIG-переразметка, финальная обрезка по границам данных).
    # Тренд пластового давления короче rpl_frag_min_d сут трендом не является.
    _short = df.label.isin(('Снижение Рпл', 'Рост Рпл')) & (df.dur_d < P['rpl_frag_min_d'])
    # v12.2: та же страховка для ВГФ — обрезка по остановкам может оставить огрызок короче
    # hglf_min_episode_days, а правило длительности задано в самом критерии.
    _short |= df.label.eq('ВГФ') & (df.dur_d < P['hglf_min_episode_days'] - 0.2)
    # v13.5: тот же рубеж для обводнённости. Минимум длительности задан в детекторе,
    # но разрезание по остановкам и сменам ЭЦН идёт ПОСЛЕ него и оставляет огрызки
    # по 0.3-2 сут — тренда обводнённости такой длины не бывает.
    _short |= df.label.isin(('Рост обводненности', 'Снижение обводненности')) & \
        (df.dur_d < P['wct_min_d'] - 0.2)
    df = df[~_short].reset_index(drop=True)
    # ПОСЛЕДНИЙ РУБЕЖ: антагонистичные категории не выходят наружу пересекающимися.
    # Стоит после ВСЕХ фильтров, поэтому инвариант не зависит от порядка правок выше.
    _alog = []
    df = enforce_antagonists_df(df, P, log=_alog)
    # ВЕТО по данным: о пластовом давлении нельзя судить там, где Рпр = 0 (насос стоит,
    # канал обнулён). Проверяется здесь, ПОСЛЕ enforce_antagonists_df (Снижение Рпл vs
    # Рост Рпл), потому что именно антагонист-резолюция режет исходный интервал на
    # финальные осколки — проверка ДО неё видела бы только целый, в основном валидный
    # интервал и пропускала бы плохой осколок (Au_389, 11-20.12.2025: 21/24 точки Рпр<=0
    # внутри осколка, но целый интервал до разрезания был в основном валиден).
    def _rpl_ip_valid(row):
        ipv = _ip_daily_by_well.get(row['well_id'])
        if ipv is None or ipv.empty:
            return False
        sg = ipv[(ipv.index >= row['start']) & (ipv.index <= row['end'])]
        if not len(sg):
            return False
        good = int((sg >= P['rpl_valid_ip_min_bar']).sum())
        return good >= P['rpl_valid_ip_min_d'] and good / len(sg) >= P['rpl_valid_ip_min_frac']

    _rpl_mask = df['label'].isin(('Снижение Рпл', 'Рост Рпл'))
    if _rpl_mask.any():
        _bad_rpl = _rpl_mask & ~df.apply(_rpl_ip_valid, axis=1)
        df = df[~_bad_rpl].reset_index(drop=True)
    _plog = []
    df = enforce_precedence_df(df, P, log=_plog)
    if _plog:
        logging.warning('enforce_precedence: снято/обрезано %d пересечений с главной категорией (%s)',
                        len(_plog), ', '.join(sorted({f"{e['rule'][0]}>{e['rule'][1]}" for e in _plog})))
    if _alog:
        logging.warning('enforce_antagonists: снято/обрезано %d пересечений антагонистов (%s)',
                        len(_alog), ', '.join(sorted({f"{e['pair'][0]}×{e['pair'][1]}" for e in _alog})))
    return df.reset_index(drop=True)


