import argparse, datetime as dt, logging, os, sys
_log = logging.getLogger("episodes")
   # сам алгоритм; интерфейс run_all(tele, vsp) -> DataFrame



OUT_COLUMNS = [
    "well_id", "label", "start", "end", "dur_d",
    "confidence", "confidence_tier", "sig_label", "sig_margin", "signals",
    "explanation", "computed_at", "model_version",
]

# Маппинг метки авторазметки -> построчная колонка auto_target_* (зеркало ручных target_*)
# Кодировка значений совпадает с ручной разметкой ('1.0' — признак; trend — falling/rising/...).
LABEL_TO_AUTO = {
    "Работа":                 ("auto_target_well_state", "work"),
    "Остановка":              ("auto_target_well_state", "stop"),
    "ГДИ":                    ("auto_target_gdi", "1.0"),
    "УВЧ":                    ("auto_target_uvch", "1.0"),
    "УМЧ":                    ("auto_target_umch", "1.0"),
    "РПТЧ":                   ("auto_target_rptch", "1.0"),
    "Периодическая работа":    ("auto_target_periodic", "1.0"),
    "НУР":                    ("auto_target_nur", "1.0"),
    "Снижение Рпл":           ("auto_target_rpl_trend", "falling"),
    "Рост Рпл":               ("auto_target_rpl_trend", "rising"),
    "Деградация ЭЦН":         ("auto_target_esp_degradation", "1.0"),
    "Рост обводненности":     ("auto_target_wct_trend", "growing"),
    "Снижение обводненности": ("auto_target_wct_trend", "falling"),
    "Снижение Кпрод":         ("auto_target_kprod_trend", "declining"),
    "Рост Кпрод":             ("auto_target_kprod_trend", "rising"),
    "Осложнённый фонд":       ("auto_target_complicated_fund", "1.0"),
    "СППВ":                   ("auto_target_sppv", "1.0"),
    "ВГФ":                    ("auto_target_vgf", "1.0"),
    "Рост ГФ":                ("auto_target_gas_factor_trend", "rising"),
    "Снижение ГФ":            ("auto_target_gas_factor_trend", "falling"),
    "Неопт. режим":           ("auto_target_deoptimization", "1.0"),   # быв. Деоптимизация; колонка сохранена
    "Увеличение подачи воды":  ("auto_target_water_supply_up", "1.0"),
}


def attach_auto_target(tele: pd.DataFrame, episodes: pd.DataFrame) -> pd.DataFrame:
    """Заполнить ПОСТРОЧНЫЕ колонки auto_target_* из эпизодов (зеркало ручных target_*).
    Строка получает значение, если её telemetry_time попадает в интервал эпизода
    соответствующей категории. Колонки создаются при отсутствии."""
    out = tele.copy()
    ts = pd.to_datetime(out["telemetry_time"], errors="coerce")
    for col in {c for c, _ in LABEL_TO_AUTO.values()}:
        if col not in out.columns:
            out[col] = pd.Series(pd.NA, index=out.index, dtype="object")
        elif out[col].dtype != "object":
            out[col] = out[col].astype("object")
    ep = episodes.copy()
    ep["start"] = pd.to_datetime(ep["start"]); ep["end"] = pd.to_datetime(ep["end"])
    for wid, g in ep.groupby("well_id"):
        mwell = (out["well_id"] == wid).values
        idxw = out.index[mwell]; tsw = ts[mwell]
        for _, r in g.iterrows():
            mp = LABEL_TO_AUTO.get(r["label"])
            if not mp:
                continue
            col, val = mp
            sel = idxw[((tsw >= r["start"]) & (tsw <= r["end"])).values]
            out.loc[sel, col] = val
    return out


def attach_auto_episode(tele: pd.DataFrame, episodes: pd.DataFrame) -> pd.DataFrame:
    """Заполнить ПОСТРОЧНЫЕ слоты auto_episode_* (поэпизодно, "|"-склейка эпизодов,
    перекрывающих сутки строки), ВКЛЮЧАЯ auto_episode_explanations. Все списки строятся
    в одном порядке -> labels/start/end/confidences/explanations согласованы.
    Это закрывает баг «объяснения = -»: слот объяснений теперь есть в выгрузке."""
    from collections import defaultdict
    out = tele.copy()
    day = pd.to_datetime(out["telemetry_time"], errors="coerce").dt.floor("D")
    cols = {"auto_episode_labels": "label", "auto_episode_start_dates": "start",
            "auto_episode_end_dates": "end", "auto_episode_confidences": "confidence_tier",
            "auto_episode_explanations": "explanation"}
    for c in cols:
        out[c] = ""
    ep = episodes.copy()
    ep["start"] = pd.to_datetime(ep["start"]); ep["end"] = pd.to_datetime(ep["end"])
    for wid, g in ep.groupby("well_id"):
        mwell = (out["well_id"] == wid).values
        idxw = out.index[mwell]; dayw = day[mwell]
        per_day = defaultdict(lambda: defaultdict(list))
        for _, r in g.iterrows():
            for d in pd.date_range(r["start"].normalize(), r["end"].normalize(), freq="D"):
                per_day[d]["label"].append(str(r.get("label", "")))
                per_day[d]["start"].append(str(r.get("start", "")))
                per_day[d]["end"].append(str(r.get("end", "")))
                per_day[d]["confidence_tier"].append(str(r.get("confidence_tier", "")))
                per_day[d]["explanation"].append(str(r.get("explanation", "")))
        for c, src in cols.items():
            out.loc[idxw, c] = dayw.map(lambda d: "|".join(per_day.get(d, {}).get(src, []))).values
    return out


def compute_kprod(tel: pd.DataFrame, wells=None) -> pd.DataFrame:
    """Суточный РАСЧЁТНЫЙ Кпрод по каждой скважине -> (well_id, date, kprod_calc).
    Расчётный Кпрод = ctx.kprod из episode_rules (Qж/(Рпл-Рзаб), единственное место с TR).
    Для отображения линией на графике ('Кпрод_алгоритм')."""
    wells = wells or sorted(tel["well_id"].dropna().unique())
    parts = []
    for wid in wells:
        a = tel[tel["well_id"] == wid]
        if a["telemetry_time"].notna().sum() < 20:
            continue
        try:
            ctx = WellCtx(a.set_index("telemetry_time").sort_index(), build_vsp(a, wid))
            k = getattr(ctx, "kprod", None)
            if k is None or len(k.dropna()) == 0:
                continue
            d = k.dropna().resample("1D").median().dropna()
            parts.append(pd.DataFrame({"well_id": wid,
                                       "date": d.index.normalize(),
                                       "kprod_calc": np.round(d.values, 3)}))
        except Exception as ex:
            _log.exception("расчётный Кпрод для %s упал: %s", wid, ex)
    return pd.concat(parts, ignore_index=True) if parts else pd.DataFrame(columns=["well_id", "date", "kprod_calc"])


def build_vsp(df: pd.DataFrame, wid: str) -> pd.DataFrame:
    """Распарсить '|'-разделённые VSP-режимы из строк телеметрии в таблицу интервалов."""
    rows = []
    for st, ss, se in zip(df["vsp_status"], df["vsp_start_time"], df["vsp_end_time"]):
        if pd.isna(st):
            continue
        a, b, c = str(st).split("|"), str(ss).split("|"), str(se).split("|")
        n = max(len(a), len(b), len(c))
        for i in range(n):
            rows.append((wid,
                         a[i].strip() if i < len(a) else "",
                         b[i].strip() if i < len(b) else "",
                         c[i].strip() if i < len(c) else ""))
    v = pd.DataFrame(rows, columns=["well_id", "status", "start", "end"]).drop_duplicates()
    v["start"] = pd.to_datetime(v["start"], errors="coerce")
    v["end"] = pd.to_datetime(v["end"], errors="coerce")
    return v.dropna(subset=["start"])


def daily_hal_median(raw: pd.DataFrame) -> pd.DataFrame:
    """One row per (well_id, calendar date) = median of VALID (0-100 inclusive)
    ХАЛ measurements that day. Values outside 0-100 are EXCLUDED, never clipped.
    Caller is responsible for the running-time gate (filter `raw` to running-time
    rows before calling this) - this function only does validity + aggregation."""
    df = raw.copy()
    df["well_id"] = df["well_id"].astype(str)
    df["date"] = pd.to_datetime(df["date"], errors="coerce").dt.floor("D")
    df["water_cut_hal"] = pd.to_numeric(df["water_cut_hal"], errors="coerce")
    df = df.dropna(subset=["well_id", "date", "water_cut_hal"])

    valid = df[df["water_cut_hal"].between(0.0, 100.0)]
    daily = (
        valid.groupby(["well_id", "date"], as_index=False)["water_cut_hal"]
        .median()
        .rename(columns={"water_cut_hal": "water_cut_hal_daily"})
        .sort_values(["well_id", "date"])
        .reset_index(drop=True)
    )
    if daily.duplicated(["well_id", "date"]).any():
        raise ValueError("daily_hal_median produced duplicate well_id+date rows")
    return daily


# ─────────────────────────────────────────────────────────────────────────────
# adaptive_water_cut_simple_v2.py, supplied as-is (user's ready-made module —
# do not rewrite the algorithm; mirrors backend/app/services/adaptive_water_cut.py
# byte-for-byte, since this script has no import path back into that package).
# Full replacement of the earlier rolling("5D") + fast/slow + hold-aware chain:
# one stateful filter, no rolling windows, no separate fast/slow blend.
# ─────────────────────────────────────────────────────────────────────────────
from dataclasses import dataclass as _wc_dataclass
from typing import Optional as _WcOptional


@_wc_dataclass(frozen=True)
class WaterCutParams:
    # Samples within this distance from the current level are ordinary updates.
    normal_delta_pp: float = 4.0
    # Larger changes require confirmation by another sample in the same direction.
    event_delta_pp: float = 5.0
    event_confirm_samples: int = 2
    event_max_span_days: int = 21

    # How strongly an accepted sample moves the target.
    stable_sample_gain: float = 0.35
    startup_sample_gain: float = 0.80

    # How quickly the daily displayed line moves toward the target.
    stable_daily_alpha: float = 0.18
    event_daily_alpha: float = 0.55
    startup_daily_alpha: float = 0.70
    event_reaction_days: int = 5

    # Post stop->run period.
    startup_days: int = 7
    startup_min_samples: int = 3


DEFAULT_PARAMS = WaterCutParams()


def _validate_daily(series: pd.Series, name: str) -> pd.Series:
    if not isinstance(series, pd.Series):
        raise TypeError(f"{name} must be a pandas Series")
    if not isinstance(series.index, pd.DatetimeIndex):
        raise TypeError(f"{name} must use a DatetimeIndex")
    out = series.copy()
    out.index = out.index.normalize()
    if not out.index.is_unique:
        raise ValueError(f"{name} must contain one value per calendar day")
    return out.sort_index()


def build_water_cut_line(
    hal_daily: pd.Series,
    running_daily: pd.Series,
    params: WaterCutParams = DEFAULT_PARAMS,
) -> pd.DataFrame:
    """Return a smooth daily line and sample-level diagnostics.

    Rules:
    - first sample after a real stop->run starts a new level immediately;
    - ordinary samples move the target gently;
    - one large sample becomes pending and does not move the line;
    - a second large sample in the same direction confirms the change;
    - after confirmation, the line approaches the new target quickly but smoothly;
    - between samples, the line remains continuous and uses no future data;
    - stop resets the state and produces NaN.
    """
    hal = _validate_daily(hal_daily, "hal_daily")
    running = _validate_daily(running_daily, "running_daily")

    if hal.empty and running.empty:
        return pd.DataFrame()

    starts = [s.index.min() for s in (hal, running) if not s.empty]
    ends = [s.index.max() for s in (hal, running) if not s.empty]
    index = pd.date_range(min(starts), max(ends), freq="D")

    hal = pd.to_numeric(hal.reindex(index), errors="coerce")
    hal = hal.where(hal.between(0.0, 100.0))
    running = running.reindex(index).fillna(False).astype(bool)

    accepted = pd.Series(np.nan, index=index, dtype=float)
    outlier = pd.Series(0, index=index, dtype="int8")
    pending = pd.Series(0, index=index, dtype="int8")
    event_confirmed = pd.Series(0, index=index, dtype="int8")
    signal_updated = pd.Series(0, index=index, dtype="int8")
    target_out = pd.Series(np.nan, index=index, dtype=float)
    line = pd.Series(np.nan, index=index, dtype=float)
    mode = pd.Series("no_data", index=index, dtype="object")
    sample_age = pd.Series(pd.NA, index=index, dtype="Int64")

    state: _WcOptional[float] = None
    target: _WcOptional[float] = None
    last_sample_date: _WcOptional[pd.Timestamp] = None

    previous_running = False
    have_previous_state = False
    startup_start: _WcOptional[pd.Timestamp] = None
    startup_sample_count = 0
    event_days_left = 0

    candidate: list[tuple[pd.Timestamp, float]] = []
    candidate_side: _WcOptional[int] = None
    candidate_baseline: _WcOptional[float] = None

    def clear_candidate(mark_outlier: bool) -> None:
        nonlocal candidate, candidate_side, candidate_baseline
        for pt, _ in candidate:
            pending.loc[pt] = 0
            if mark_outlier:
                outlier.loc[pt] = 1
                accepted.loc[pt] = np.nan
        candidate = []
        candidate_side = None
        candidate_baseline = None

    def accept_normal(t: pd.Timestamp, value: float, gain: float) -> None:
        nonlocal target
        accepted.loc[t] = value
        signal_updated.loc[t] = 1
        if target is None:
            target = value
        else:
            target = gain * value + (1.0 - gain) * target

    for t in index:
        is_running = bool(running.loc[t])

        if not is_running:
            clear_candidate(mark_outlier=True)
            state = None
            target = None
            last_sample_date = None
            startup_start = None
            startup_sample_count = 0
            event_days_left = 0
            mode.loc[t] = "stop"
            previous_running = False
            have_previous_state = True
            continue

        if have_previous_state and not previous_running:
            # Explicit stop -> run. Do not carry the pre-stop level.
            clear_candidate(mark_outlier=True)
            state = None
            target = None
            startup_start = t
            startup_sample_count = 0
            event_days_left = 0

        raw = hal.loc[t]
        has_sample = pd.notna(raw)

        if has_sample:
            value = float(raw)
            last_sample_date = t

            startup_active = startup_start is not None
            if startup_active:
                startup_sample_count += 1
                accepted.loc[t] = value
                signal_updated.loc[t] = 1
                if state is None or target is None:
                    # First sample after startup is the new initial level.
                    state = value
                    target = value
                else:
                    target = (
                        params.startup_sample_gain * value
                        + (1.0 - params.startup_sample_gain) * target
                    )
                clear_candidate(mark_outlier=True)
            elif state is None or target is None:
                # First sample in visible running history.
                state = value
                target = value
                accepted.loc[t] = value
                signal_updated.loc[t] = 1
            else:
                # If a large sample is already pending, decide it using this sample.
                if candidate:
                    assert candidate_baseline is not None
                    assert candidate_side is not None
                    delta_from_old = value - candidate_baseline
                    side = 1 if delta_from_old > 0 else -1
                    same_side_large = (
                        abs(delta_from_old) >= params.event_delta_pp
                        and side == candidate_side
                        and (t - candidate[0][0]).days <= params.event_max_span_days
                    )

                    if same_side_large:
                        candidate.append((t, value))
                        pending.loc[t] = 1
                        if len(candidate) >= params.event_confirm_samples:
                            # Confirm using a robust target from the confirming samples.
                            new_target = float(np.median([v for _, v in candidate]))
                            for pt, pv in candidate:
                                accepted.loc[pt] = pv
                                pending.loc[pt] = 0
                                outlier.loc[pt] = 0
                            target = new_target
                            signal_updated.loc[t] = 1
                            event_confirmed.loc[t] = 1
                            event_days_left = params.event_reaction_days
                            candidate = []
                            candidate_side = None
                            candidate_baseline = None
                    else:
                        # The previous large sample was not confirmed.
                        clear_candidate(mark_outlier=True)
                        # Process the current value afresh below.
                        delta = value - state
                        if abs(delta) >= params.event_delta_pp:
                            candidate = [(t, value)]
                            candidate_side = 1 if delta > 0 else -1
                            candidate_baseline = state
                            pending.loc[t] = 1
                        else:
                            accept_normal(t, value, params.stable_sample_gain)
                else:
                    delta = value - state
                    if abs(delta) >= params.event_delta_pp:
                        candidate = [(t, value)]
                        candidate_side = 1 if delta > 0 else -1
                        candidate_baseline = state
                        pending.loc[t] = 1
                    else:
                        accept_normal(t, value, params.stable_sample_gain)

        # End startup only after both time and sample requirements are satisfied.
        if startup_start is not None:
            elapsed = (t - startup_start).days
            if elapsed >= params.startup_days and startup_sample_count >= params.startup_min_samples:
                startup_start = None

        if state is not None and target is not None:
            if startup_start is not None:
                alpha = params.startup_daily_alpha
                mode.loc[t] = "startup"
            elif event_days_left > 0:
                alpha = params.event_daily_alpha
                mode.loc[t] = "event"
            else:
                alpha = params.stable_daily_alpha
                mode.loc[t] = "stable"

            state = state + alpha * (target - state)
            state = float(np.clip(state, 0.0, 100.0))
            line.loc[t] = state
            target_out.loc[t] = target
            if last_sample_date is not None:
                sample_age.loc[t] = (t - last_sample_date).days
            if event_days_left > 0:
                event_days_left -= 1

        previous_running = is_running
        have_previous_state = True

    # Unresolved candidate remains pending; it is not part of the algorithm level.
    result = pd.DataFrame(
        {
            "water_cut_hal_daily": hal,
            "water_cut_accepted": accepted,
            "water_cut_outlier": outlier,
            "water_cut_pending": pending,
            "water_cut_event_confirmed": event_confirmed,
            "water_cut_signal_updated": signal_updated,
            "water_cut_target": target_out.round(2),
            "water_cut_algo": line.round(2),
            "water_cut_mode": mode,
            "water_cut_sample_age_days": sample_age,
            "running": running.astype("int8"),
        },
        index=index,
    )
    result.index.name = "date"
    return result


def compute_well_water_cut_algo(daily: pd.Series, running_daily: pd.Series = None) -> pd.DataFrame:
    """Full per-well table: adaptive water_cut_algo (build_water_cut_line, unmodified).
    v13.3: классификация Рост/Снижение обводненности больше не использует отдельный
    daily-таблицы направленческий признак (delta_90d/slope/direction_candidate) —
    det_wcut считает устойчивый локальный тренд (episode_rules_v12_8) прямо по
    ctx.tele['water_cut_algo']."""
    return build_water_cut_line(hal_daily=daily, running_daily=running_daily)


def load_hal_raw(hal_path: str) -> pd.DataFrame:
    """Raw (well_id, timestamp, hal_value) ХАЛ measurements from water_cut_hal.csv.
    Intentionally NOT pre-aggregated and NOT merged into telemetry rows here: the
    canonical per-well running mask (WellCtx.wmask) must gate each raw measurement
    BEFORE daily aggregation, and it only exists once WellCtx is built. Also, this
    output must stay separate from `tel`/the --enrich output, since that file is
    fed back in as next run's --telem input — merging HAL rows into it would grow
    the enriched CSV by the same rows on every recompute."""
    if not hal_path or not os.path.exists(hal_path):
        _log.warning("файл ХАЛ обводнённости не задан/не найден — категории "
                    "Рост/Снижение обводнённости будут пустыми")
        return pd.DataFrame(columns=["well_id", "timestamp", "hal_value"])

    hal = pd.read_csv(hal_path, sep=";")
    if len(hal.columns) == 1:
        hal = pd.read_csv(hal_path)
    hal.columns = [c.strip().lstrip("﻿") for c in hal.columns]

    value_col = "water_cut_hal" if "water_cut_hal" in hal.columns else "hal" if "hal" in hal.columns else None
    if "well_id" not in hal.columns or "date" not in hal.columns or value_col is None:
        _log.warning("файл ХАЛ %s не содержит требуемых колонок well_id/date/water_cut_hal", hal_path)
        return pd.DataFrame(columns=["well_id", "timestamp", "hal_value"])

    hal = hal[["well_id", "date", value_col]].copy()
    hal["well_id"] = hal["well_id"].astype(str)
    hal["timestamp"] = pd.to_datetime(hal["date"], errors="coerce")
    hal["hal_value"] = pd.to_numeric(hal[value_col], errors="coerce")
    hal = hal.dropna(subset=["well_id", "timestamp", "hal_value"])
    hal = hal[hal["hal_value"].between(0.0, 100.0)]
    _log.info("ХАЛ обводнённость загружена: %d строк, %d скважин", len(hal), hal["well_id"].nunique())
    return hal[["well_id", "timestamp", "hal_value"]].sort_values(["well_id", "timestamp"]).reset_index(drop=True)


def load_inputs(telem_path: str) -> pd.DataFrame:
    """Телеметрия как есть — без подмешивания какого-либо прогноза обводнённости.
    Единственный источник обводнённости (ХАЛ) загружается отдельно (load_hal_raw)
    и подключается per-well в WellCtx, после того как посчитан канонический
    признак «скважина в работе» (wmask), а не здесь."""
    tel = pd.read_csv(telem_path, low_memory=False)
    if "telemetry_time" not in tel.columns:
        raise ValueError("в телеметрии нет колонки telemetry_time")
    tel["telemetry_time"] = pd.to_datetime(tel["telemetry_time"], errors="coerce")
    return tel


def compute(tel: pd.DataFrame, model_version: str, wells=None, pvt_path=None, hal_raw=None) -> pd.DataFrame:
    """Прогнать авторазметку по каждой скважине. Ошибка по одной скважине не валит остальные.
    pvt_path — книга PVT для категории ВГФ (v11). Путь НЕ хардкодится: без него ВГФ
    не рассчитывается и категория остаётся пустой, остальные правила работают.
    hal_raw — сырые (well_id, timestamp, hal_value) измерения ХАЛ, единственный
    источник обводнённости (см. load_hal_raw)."""
    if pvt_path:
        set_pvt_curves(load_pvt_curves(pvt_path))
    computed_at = dt.datetime.now(dt.timezone.utc)
    wells = wells or sorted(tel["well_id"].dropna().unique())
    parts, failed = [], []
    for wid in wells:
        a = tel[tel["well_id"] == wid]
        if a["telemetry_time"].notna().sum() < 20:
            continue
        try:
            hal_a = hal_raw[hal_raw["well_id"] == wid] if hal_raw is not None and len(hal_raw) else None
            df = run_all(a.set_index("telemetry_time").reset_index(),
                            build_vsp(a, wid), wells=[wid], hal_raw=hal_a)
            parts.append(df)
        except Exception as ex:
            failed.append(wid)
            _log.exception("скважина %s упала: %s", wid, ex)
    if not parts:
        return pd.DataFrame(columns=OUT_COLUMNS)
    out = pd.concat(parts, ignore_index=True)
    out["computed_at"] = computed_at.isoformat()
    out["model_version"] = model_version
    for c in OUT_COLUMNS:
        if c not in out.columns:
            out[c] = ""
    out = out[OUT_COLUMNS]
    _log.info("эпизодов: %d | скважин: %d | упало: %d %s",
             len(out), out["well_id"].nunique(), len(failed), failed or "")
    return out


def write_atomic(df: pd.DataFrame, out_path: str):
    """Атомарная запись: во временный файл, затем rename (UI не читает полу-записанное)."""
    tmp = out_path + ".tmp"
    if out_path.lower().endswith(".parquet"):
        df.to_parquet(tmp, index=False)
    else:
        df.to_csv(tmp, index=False, encoding="utf-8-sig")
    os.replace(tmp, out_path)
    _log.info("записано: %s", out_path)


def main(argv=None):
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    ap = argparse.ArgumentParser(description="Суточный пересчёт авторазметки эпизодов")
    ap.add_argument("--telem", required=True, help="CSV телеметрии (well_graph_data_all_full_*.csv)")
    ap.add_argument("--hal", default=None, help="CSV фактической обводнённости ХАЛ (water_cut_hal.csv) — единственный источник Обв. алгоритма")
    ap.add_argument("--out", required=True, help="выходной файл (.parquet или .csv)")
    ap.add_argument("--pvt", default=None, help="Excel PVT file for VGF/high GLF")
    ap.add_argument("--model-version", default=MODEL_VERSION)
    ap.add_argument("--wells", default=None, help="подмножество скважин через запятую (опц.)")
    ap.add_argument("--enrich", default=None, help="доп. выход: телеметрия + построчные auto_target_* (+ kprod_calc) для чарта/экспорта приложения")
    ap.add_argument("--kprod", default=None, help="доп. выход: суточный расчётный Кпрод (well_id,date,kprod_calc) для линии Кпрод_алгоритм")
    args = ap.parse_args(argv)

    try:
        tel = load_inputs(args.telem)
    except Exception as ex:
        _log.error("ошибка загрузки входных данных: %s", ex)
        return 1
    hal_raw = load_hal_raw(args.hal)

    wells = [w.strip() for w in args.wells.split(",")] if args.wells else None
    out = compute(tel, args.model_version, wells, pvt_path=args.pvt, hal_raw=hal_raw)
    write_atomic(out, args.out)

    kp = None
    if args.kprod or args.enrich:
        kp = compute_kprod(tel, wells)
    if args.kprod:
        write_atomic(kp, args.kprod)
        _log.info("расчётный Кпрод (суточный): %s", args.kprod)
    if args.enrich:
        enriched = attach_auto_target(tel, out)
        enriched = attach_auto_episode(enriched, out)   # + auto_episode_explanations (фикс "объяснения = -")
        if kp is not None and len(kp):
            if "kprod_calc" in enriched.columns:
                enriched = enriched.drop(columns=["kprod_calc"])
            enriched["__day"] = pd.to_datetime(enriched["telemetry_time"], errors="coerce").dt.floor("D")
            enriched = enriched.merge(kp.rename(columns={"date": "__day"}), on=["well_id", "__day"], how="left").drop(columns="__day")
        write_atomic(enriched, args.enrich)
        _log.info("обогащённая телеметрия (auto_target_* + kprod_calc): %s", args.enrich)
    print(f"OK: {len(out)} эпизодов по {out['well_id'].nunique()} скважинам -> {args.out}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
